-- ============================================================================
-- 215 — إعادة بناء نص قانون المحاماة 17/1983 (231 مادة + 7 مواد مكررة) من النسخة المجمَّعة المحدَّثة حتى القانون 147/2019 (PDF مقدَّم من المستخدم)
-- ----------------------------------------------------------------------------
-- المشكلة: النص المخزَّن (من استخراج PDF قديم) فيه: (1) تلف عربى واسع: "ال" المبدَّلة بـ"اال/األ"، وكلمات مقطعة ("المحام ي"، "ف ي")،
--          وأرقام الإحالات ساقطة داخل النصوص ("المادة ( )" بلا رقم)، وأرقام الهوامش ملتصقة بالنص؛ (2) سبع مواد مكررة غير موجودة أصلاً
--          (13 مكرر و46 مكرر و50 مكرر و135 مكرر و156 مكرر و156 مكرر (1) و206 مكرر)؛ (3) المواد 2 و3 و5 مُصنَّفة "ملغاة" خطأً بسبب خلط بينها وبين مواد
--          الإصدار الملغاة (والمرجع الصحيح القانون 227 لسنة 1984 لا 327)؛ (4) مبلغ/نص بعض المواد قديم قبل تعديلات 2008 و2019؛ (5) الموقع الهرمى (باب/فصل) خاطئ ومشوه.
-- المصدر: ملف مجمَّع غير رسمى (تصدير Word) لقانون المحاماة مع تعديلاته حتى القانون 147/2019. نُقل نصه بإحداثيات الأحرف لا بطبقة النص المكسورة،
--          ثم صُحِّح إملاؤه بمطابقته على النص المخزَّن (فى مواضع ة/ه والهمزات)، وبقاموس كلمات، وبمراجعة يدوية لكل فرق لفظى بين المصدرين (أكثر من 260 فرقاً)،
--          وتحقَّق مبلغ المادة 59 (20 ألف جنيه) من نص القانون 197/2008. المواد المحكوم بعدم دستورية فقراتها تبقى بنفس نمط المخزَّن: النص السارى ثم "قضي بعدم
--          دستورية ...". لم تُمَسَّ المادتان 15 و84 (بطلان بحكم دستورى). المادة 85 بقيت بنمط المخزَّن مع تصحيح الإملاء (مراجعة قانونية يدوية لازمة لنطاق سقوطها).
--          مواد الإصدار (1 إلى 6 من القانون 17/1983 ذاته) غير مخزَّنة هنا ولا تُضاف فى هذه الهجرة.
-- حدود: النسخة المجمَّعة تنتهى عند القانون 147/2019؛ تعديل 8/7/2020 (المذكور فى laws.last_amended_at) غير مغطى فيها فتلزم مراجعة قانونية.
-- الضمان: كل مادة موجودة تُحدَّث فقط إذا كان md5 نصها الحالى أحد النصين المقيسين (قبل/بعد 208) أو بصمتها الحرفية مطابقة؛ غير ذلك: تحذير وتخطٍّ.
--          النص القديم والحالة والملاحظة والموقع القديمة تُحفظ فى migration_215_backup / migration_215_meta_backup. article_versions المطابقة تُحدَّث معها.
--          المواد المكررة تُنشأ فقط إذا لم تكن موجودة. embeddings لا تُمس (تلزم إعادة التوليد). قابلة لإعادة التشغيل.
-- ============================================================================

CREATE TABLE IF NOT EXISTS migration_215_backup (
  article_id uuid NOT NULL,
  version_id uuid,
  old_body   text NOT NULL,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_215_backup_art ON migration_215_backup (article_id) WHERE version_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_215_backup_ver ON migration_215_backup (version_id) WHERE version_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS migration_215_meta_backup (
  kind       text NOT NULL,
  ref_id     uuid NOT NULL,
  old_status text,
  old_note   text,
  old_loc    text,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_215_meta_backup ON migration_215_meta_backup (kind, ref_id);

DO $m215$
DECLARE
  r record;
  v_law uuid; v_aid uuid; v_cur text;
  v_ok_art int := 0; v_ok_ver int := 0; v_done int := 0; v_skip int := 0; v_new int := 0; v_loc int := 0; v_n int;
BEGIN
  SELECT l.id INTO v_law FROM laws l
   WHERE l.country_code = 'EG' AND l.kind = 'law' AND l.law_no = 17 AND l.law_year = 1983;
  IF v_law IS NULL THEN
    RAISE WARNING '[215] القانون 17/1983 غير موجود — تخطّى';
    RETURN;
  END IF;

  -- 1) المواد الموجودة: تحديث النص بحارس md5/بصمة
  FOR r IN SELECT * FROM (VALUES
    (1, 0, ARRAY['5fcc5b75e13e7207bdb9e22930458b58']::text[], ARRAY['9167fa41cd145c7e1da25982c1f3d8ff']::text[], '5af83e35beb7d608527b5a6702cb5d3b', replace($b$المحاماة مهنة حرة تشارك السلطة القضائية فى تحقيق العدالة وفى تأكيد سيادة القانون وفى كفالة حق الدفاع عن حقوق المواطنين وحريتهم.
ويمارس مهنة المحاماة المحامون وحدهم فى استقلال، ولا سلطان عليهم فى ذلك إلا لضمائرهم وأحكام القانون.$b$, E'\n', E'\r\n')),
    (2, 0, ARRAY['1c5a65ce52707ac351e25b0555d466ed']::text[], ARRAY['3e802ac52c5ac66954368d3ae77c679e']::text[], '9822dde1afce185e65150252d4015a51', replace($b$يعد محاميا من يقيد بجداول المحامين التى ينظمها القانون، وفيما عدا المحامين بإدارة قضايا الحكومة، يحظر استخدام لقب المحامى على غير هؤلاء.$b$, E'\n', E'\r\n')),
    (3, 0, ARRAY['1c5a65ce52707ac351e25b0555d466ed']::text[], ARRAY['3e802ac52c5ac66954368d3ae77c679e']::text[], 'a30bb8b02c3705ec1be02e9c022ce59f', replace($b$مع عدم الإخلال بأحكام القوانين المنظمة للهيئات القضائية وبأحكام قانون المرافعات المدنية والتجارية، ولا يجوز لغير المحامين مزاولة أعمال المحاماة، ويعد من أعمال المحاماة:
(1) الحضور عن ذوى الشأن أمام المحاكم وهيئات التحكيم والجهات الإدارية ذات الاختصاص القضائى وجهات التحقيق الجنائى والادارى ودوائر الشرطة والدفاع عنهم فى الدعاوى التى ترفع منهم أو عليهم والقيام بأعمال المرافعات والإجراءات القضائية المتصلة بذلك.
(2) إبداء الرأى والمشورة القانونية فيما يطلب من المحامى.
(3) صياغة العقود واتخاذ الإجراءات اللازمة لشهرها أو توثيقها.
وتعد أيضا من أعمال المحاماة بالنسبة لمحامى الإدارات القانونية فى الجهات المنصوص عليها فى هذا القانون، فحص الشكاوى وإجراء التحقيقات الإدارية وصياغة اللوائح والقرارات الداخلية لهذه الجهات.$b$, E'\n', E'\r\n')),
    (4, 0, ARRAY['0214161ee132f4b09a4a3c2b195563a7']::text[], ARRAY['93f9269eefc1758f2e5bb587517edbac']::text[], 'aea037ab8ba93fe5307eed2f3224bfa6', replace($b$يمارس المحامى مهنة المحاماة منفردا أو شريكا مع غيره من المحامين أو فى صورة شركة مدنية للمحاماة.
كما يجوز للمحامى أن يمارس مهنة المحاماة فى الإدارات القانونية للهيئات العامة وشركات القطاع العام والخاص والمؤسسات الصحفية وفى البنوك والشركات الخاصة والجمعيات طبقا لأحكام هذا القانون.$b$, E'\n', E'\r\n')),
    (5, 0, ARRAY['1c5a65ce52707ac351e25b0555d466ed']::text[], ARRAY['3e802ac52c5ac66954368d3ae77c679e']::text[], 'ad46d9ec7dc842efa2a822123a6e5054', replace($b$للمحامين المقبولين أمام محكمة النقض ومحاكم الاستئناف أن يؤسسوا فيما بينهم شركة مدنية للمحاماة يكون لها شخصية معنوية مستقلة ويزاولوا المحاماة من خلالها ويجوز أن يشارك فيها المحامون أمام المحاكم الابتدائية.
ويجوز ان يكون اسم الشركة مستمدا من اسم احد المحامين من الشركاء ولو بعد وفاته.
ويضع مجلس نقابة المحامين نموذجا للنظام الأساسى لشركات المحامين ويجب تسجيلها بالنقابة العامة بسجل خاص يصدر به قرار من وزير العدل وذلك مع عدم الإخلال بالأحكام المقررة بشأن الشركات المدنية.
ويجوز أن ينص فى النظام الأساسى للشركة على انه فى حالة عجز احد الشركاء أو وفاته واستمرار الشركة بين الشركاء الآخرين أن يستحق هو أو ورثته حصة من صافى دخل الشركة.$b$, E'\n', E'\r\n')),
    (6, 0, ARRAY['3fc9578ba7d315683f44dfa55478b84f']::text[], ARRAY['521f33af46b7f140ed7d1d90ded747af']::text[], '45e0d655b78854b440b41a3a53b96238', replace($b$يعتبر المحامى الذى يلتحق بمكتب محام ولو لم يكن شريكا له فيه، ممارسا لمهنة حرة ويعتبر ما يحصل عليه إتعابا عن عمله.$b$, E'\n', E'\r\n')),
    (7, 0, ARRAY['0ab28d9253498efe1086e616cd5ce12e']::text[], ARRAY['1bdf3997092e8d2fae7c00f1e687b62c']::text[], 'e50c4e9b2c94e49ff919829adbc2748e', replace($b$يجوز للمحامى مزاولة أعمال المحاماة فى شركات القطاع العام والمؤسسات الصحفية التى تنشأ بها إدارات قانونية طبقا لأحكام القوانين واللوائح المنظمة لذلك.
كما يجوز له مزاولة أعمال المحاماة فى الإدارات القانونية للهيئات العامة القائمة وقت العمل بأحكام هذا القانون.
ولا يجوز مزاولة أعمال المحاماة للهيئات العامة التى يتقرر إنشاؤها بعد العمل بأحكام هذا القانون، إلا بقرار من وزير العدل بعد موافقة مجلس نقابة المحامين.$b$, E'\n', E'\r\n')),
    (8, 0, ARRAY['a6cb13ad33b626f62555dacb1b6129e1']::text[], ARRAY['0f69c13b4301142da748ffa969a89345']::text[], '56c9768e2e0764ce3595e5af1e910bd7', replace($b$مع عدم الإخلال بأحكام قانون المرافعات المدنية والتجارية لا يجوز لمحامى الإدارات القانونية للهيئات العامة وشركات القطاع العام والمؤسسات الصحفية أن يزاولوا أعمال المحاماة لغير الجهة التى يعملون بها وإلا كان العمل باطلا.
كما لا يجوز للمحامى فى هذه الإدارات القانونية الحضور أمام المحاكم الجنائية إلا فى الادعاء بالحق المدنى فى الدعاوى التى تكون الهيئة أو الشركة أو المؤسسة طرفا فيها وكذلك الدعاوى التى ترفع على مديريها أو العاملين بها بسبب أعمال وظائفهم.
قضي بعدم دستورية الفقرة الثالثة من هذه المادة.$b$, E'\n', E'\r\n')),
    (9, 0, ARRAY['dfb3438b26bea1fa97930d86f961d998']::text[], ARRAY['9447bf1276d9c2b16e1777f5b4e2c5f9']::text[], '2737222ef6ecc9882b63d86492b760ef', replace($b$يجوز للمحامى مزاولة أعمال المحاماة فى البنوك وشركات المساهمة الخاصة والجمعيات التعاونية. وتكون علاقة المحامى بهذه الجهات علاقة وكالة ولو اقتصر عمله عليها.$b$, E'\n', E'\r\n')),
    (10, 0, ARRAY['d3976f1f3566116be62fd82983de9685']::text[], ARRAY['6c51b1e92ef6d33273c2bb821f1ac63e']::text[], 'cc74df7fe1372b1462ea893ada3d5173', replace($b$للمحامين المشتغلين جدول عام تقيد فيه أسماؤهم ومحال إقامتهم ومقار ممارستهم المهنة.
ويلحق بكل جدول الجداول الآتية:
(1) جدول للمحامين تحت التمرين.
(2) جدول للمحامين أمام المحاكم الابتدائي وتعتبر المحاكم الإدارية معادلة للمحاكم الابتدائية.
(3) جدول للمحامين المقبولين أمام محاكم الاستئناف.
وتعتبر محاكم القضاء الإدارى معادلة لمحاكم الاستئناف.
(4) جدول للمحامين المقبولين أمام محكمة النقض وتعتبر المحاكم الإدارية العليا والمحكمة الدستورية العليا معادلة لمحكمة النقض.
(5) جدول للمحامين غير المشتغلين.
كما ينشأ جدول خاص للمحامين بالقطاع العام والهيئات العامة والمؤسسات الصحفية تبين به أسماؤهم ومحال إقامتهم، واسم الجهة التى يعملون بها.$b$, E'\n', E'\r\n')),
    (11, 0, ARRAY['4d753c0ee9a439521ba93aa09fa6fdc6']::text[], ARRAY['49e9642a13506377ffd3a47ee2178b25']::text[], 'f58cd094ae29ca5c9c6e4c93cb0df78d', replace($b$تحفظ نسختان من الجداول المذكورة بالمادة السابقة بمقر النقابة العامة وتودع نسخة من هذه الجداول بمقر كل محكمة من محاكم الاستئناف ومحاكم القضاء الإدارى ولدى النائب العام.
وتودع نسخة من جدول المحامين أمام محكمة النقض بمقرها وبمقر كل من المحكمة الإدارية العليا والمحكمة الدستورية العليا.
ويكون بكل نقابة فرعية جدولان عامان وجداول ملحقة مقصورة على إثبات أسماء المحامين الذين توجد مقارهم فى دائرتها.$b$, E'\n', E'\r\n')),
    (12, 0, ARRAY['9db2d011c66dcf18f0c3acc4630dd296']::text[], ARRAY['118870c90cfb129a6cfaf5bd792dfbaa']::text[], '8cd6fc74778ee3d08bbdbcaba015f230', replace($b$يعهد بالجدول العام والجداول المنصوص عليها فى المادة (10) إلى لجنة قبول المحامين المنصوص عليها فى المادة (16) وتتولى هذه اللجنة مراجعة هذه الجداول سنويا والتثبت من مطابقة البيانات الواردة بها لقرارات لجان القبول، وبحث حالات المقيدين بها الذين تقتضى حالاتهم نقل أسمائهم إلى جدول غير المشتغلين وإصدار القرار اللازم فى هذا الشأن.$b$, E'\n', E'\r\n')),
    (13, 0, ARRAY['34e4e255cfc7eeb81a39ed7c397dcfce']::text[], ARRAY['7b6dd0d3a18c774413b3d7d06b121d5f']::text[], '9d4a24cc2c902e66eac0ebfbf149710e', replace($b$يشترط فى من يطلب قيد اسمه فى الجدول العام، أن يكون:
(1) متمتعا بالجنسية المصرية ومقيما بها إقامة دائمة وفقا للضوابط التى يقررها مجلس النقابة، ويجوز لوزير العدل وفقا للقواعد التى يضعها بالتنسيق مع مجلس نقابة المحامين الترخيص للمحامى الأجنبى بالعمل فى دعوى أو موضوع معين بشرط المعاملة بالمثل.
وينشئ مجلس النقابة جداول خاصة بالمحامين الأجانب والمحامين المشتغلين خارج جمهورية مصر العربية وبقواعد التعامل من حيث تدرج القيد ورسومه والاشتراكات السنوية والخدمات التى تقدم لهذه الجداول.
(2) متمتعا بالأهلية المدنية الكاملة.
(3) أن يكون حاصلًا على الثانوية العامة أو ما يعادلها من الشهادات الأجنبية المعتمدة فى مصر.
وإجازة الحقوق من إحدى كليات الحقوق أو شهادة من إحدى الجامعات الأجنبية أو فروعها فى مصر والتى تعتبر معادلة لها طبقًا لأحكام القوانين واللوائح المعمول بها فى جمهورية مصر العربية.
(4) ألا يكون قد سبق إدانته بحكم نهائى فى جنحة ماسة بالشرف أو الأمانة أو بعقوبة جناية، ما لم يكن قد رد إليه اعتباره.
(5) أن يكون محمود السيرة، حسن السمعة، أهلا للاحترام الواجب للمهنة، وألا تكون قد صدرت ضده أحكام تأديبية أو انتهت علاقته بوظيفته أو مهنته أو انقطعت صلته بها لأسباب ماسة بصلاحيته للوظيفة التى كان يشغلها.
(6) قضي بعدم دستورية البند السادس من الفقرة الأولى
(7) أن يسدد رسوم القيد والاشتراك السنوى.
(8) ألا تقوم بشأنه حالة من حالات عدم جواز الجمع الواردة فى المادة التالية.
ويجب لاستمرار القيد فى الجداول توافر الشروط سالفة الذكر عدا البند رقم 6 من هذه المادة، ويسقط القيد بقوة القانون من تاريخ افتقاد أى من هذه الشروط دون حاجة إلى صدور قرار بذلك من لجنة القيد، ويجب الإخطار بهذا الإجراء بكتاب موصى عليه، وإخطار النقابة الفرعية المختصة.$b$, E'\n', E'\r\n')),
    (14, 0, ARRAY['3c25f2f2eaeecac549dc6b87019c25a6']::text[], ARRAY['52704c7fc5016759a3cc31fd640bb074']::text[], 'bdc9173fc4ed640581ffe216167edcf0', replace($b$لا يجوز الجمع بين المحاماة والأعمال الآتية:
(1) رئاسة مجلس النواب أو مجلس الشيوخ.
(2) منصب الوزارة.
(3) الوظائف العامة فى الحكومة والهيئات العامة والإدارة المحلية، والوظائف فى شركات القطاع العام أو الوظائف الخاصة، فيما عدا العمل بالإدارة القانونية المصرح لها بذلك طبقا لأحكام هذا القانون، وفيما عدا أساتذة القانون فى الجامعات المصرية فى الحالات التى يجيزها هذا القانون.
ولا تعد العضوية فى اللجان الحكومية العلمية أو المؤقتة أو القيام بمهام ذات صفة عرضية لا تستغرق أكثر من ستة شهور أو الندب لتدريس القانون فى الجامعات والمعاهد العليا وظيفة يحظر معها الجمع بينها وبين المحاماة.
(4) الاشتغال بالتجارة.
(5) شغل مركز رئيس مجلس الإدارة أو العضو المنتدب أو عضو مجلس إدارة متفرغ فى شركات المساهمة أو المدير فى الشركات ذات المسئولية المحدودة وشركات التضامن والتوصية.
(6) المناصب الدينية.
وباستثناء ما ورد بالبند (3) يشترط التفرغ للمحاماة.$b$, E'\n', E'\r\n')),
    (16, 0, ARRAY['778ad1cd0a71f30fef32c9dca1eeceb8']::text[], ARRAY['58dd796c4bc00efe2b3a89cbaf1cb2fd']::text[], 'a73a8cbfbb168ac740ba4c65a7dc49e7', replace($b$يقدم طلب القيد بالجدول العام الى لجنة قبول المحامين التى تشكل فى النقابة العامة برئاسة النقيب أو وكيل النقابة فى حالة غيابه وعضوية أربعة من المحامين المقبولين أمام محكمة النقض أو محاكم الاستئناف يختارهم مجلس النقابة من بين أعضائه سنويا.
ويرفق بطلب القيد الأوراق المثبتة لتوافر الشروط المبينة بالمادة (13) والتى بينها النظام الداخلى للنقابة.$b$, E'\n', E'\r\n')),
    (17, 0, ARRAY['03153c1ee06c6344bae52affe2bfaa03']::text[], ARRAY['b372c4ee3bbd707170e9393da397d469']::text[], '9b2288cef445cbbb111a21ace8e004a2', replace($b$تنعقد لجنة قبول المحامين مرة على الأقل كل شهر، ويكون لها أمانة من بين موظفى النقابة يختار النقيب أعضاءها، وتحرر محاضر بأعمالها يوقع عليها من رئيس اللجنة.
ولا يصح انعقاد اللجنة إلا بحضور ثلاثة أعضاء على الأقل، على أن يكون من بينهم النقيب أو وكيل النقابة.$b$, E'\n', E'\r\n')),
    (18, 0, ARRAY['b8827810d6f3a473937c85d5ac93e9fa']::text[], ARRAY['5d1c3c4aa371eaaef46b5463721307ae']::text[], '92afa06aa7bb380f763b482e2df34462', replace($b$تصدر اللجنة قرارها بعد التحقق من توافر شروط القيد، وذلك من خلال ثلاثين يوما من تاريخ تقديم الطلب.
وإذا كان قرارها برفض القيد تعين أن يكون مسببا ويخطر به طالب القيد خلال خمسة عشر يوما من تاريخ صدوره بخطاب مسجل مصحوب بعلم الوصول.$b$, E'\n', E'\r\n')),
    (19, 0, ARRAY['e3bf5bd8ed59f0d2854c7267e7790997']::text[], ARRAY['b99b61f07c41128df898245f57d69e58']::text[], 'a32a796e6491653cba72773b9f5fbaba', replace($b$لطالب القيد التظلم من القرار الصادر برفض قيده خلال خمسة عشر يوما من تاريخ إخطاره برفض طلبه.
ويقدم التظلم إلى لجنة القبول التى تفصل فى التظلم بعد سماع أقواله.
ولطالب القيد إذا رفض تظلمه أو كانت قد انقضت مواعيد التظلم إن يطعن فى القرار الصادر برفض التظلم أو رفض القيد أمام محكمة استئناف القاهرة خلال ثلاثين يوما من تاريخ رفض التظلم، أو من تاريخ انتهاء ميعاد التظلم على حسب الأحوال، ويكون لطالب القيد الطعن أمام ذات المحكمة إذا لم يفصل فى طلب قيده خلال لمدة المبينة بالمادة السابقة.
ولا يجوز تجديد الطلب فى الحالات المبينة بالفقرتين السابقتين إلا إذا زالت الأسباب المانعة من القيد.$b$, E'\n', E'\r\n')),
    (20, 0, ARRAY['67b22bdf80bd2dc41b60dbacb2ae8013']::text[], ARRAY['a25f5563434a14dd6f733d3abec94976']::text[], 'be96286b5e73887ccaa93666fe3bd952', replace($b$لا يجوز للمحامى الذى يقيد اسمه بجدول المحاماة أن يزاول المهنة إلا بعد حلف اليمين بالصيغه الآتية:
( أقسم بالله العظيم أن أمارس أعمال المحاماة بالشرف والأمانة والاستقلال وأن أحافظ على سر مهنة المحاماة وتقاليدها وأن أحترم الدستور والقانون ).
ويكون حلف اليمين أمام لجنة قبول المحامين بحضور ثلاثة من أعضائها على الأقل وتثبت إجراءات حلف اليمين فى محاضر اجتماعات اللجنة.$b$, E'\n', E'\r\n')),
    (21, 0, ARRAY['2ee3b65effe5eabd665dcf955d324fe9']::text[], ARRAY['fe66d55d5027a1d0a26261522a17afe5']::text[], '93dced5ae36cb255d5954a4dd8762235', replace($b$يكون قيد المحامى بجدول المحامين تحت التمرين لأول مرة إذا لم تتوافر فيه الشروط التى تسمح بقيده فى أحد الجداول الملحقة الأخرى.
قضي بعدم دستورية الفقرة الثانية من هذه المادة.$b$, E'\n', E'\r\n')),
    (22, 0, ARRAY['5aceac2105f7bb3ae89c9754e307be11']::text[], ARRAY['81f033d3c0800eed4b205959c89057c3']::text[], '2771646aeca4c98673d25804891f79e2', replace($b$يجب أن يلحق المحامى تحت التمرين بمكتب أحد المحامين المقبولين للمرافعة أمام محاكم الاستئناف أو محكمة النقض، أو للعمل بإحدى الإدارات القانونية فى الجهات المرخص لها بذلك طبقا لأحكام هذا القانون تحت إشراف أحد المحامين المقبولين أمام تلك المحاكم من العاملين بالإدارة القانونية لهذه الجهة.
وإذا تعذر على المحامى تحت التمرين أن يجد مكتبا للتمرين فيه يتولى مجلس النقابة الفرعية إلحاقه بأحد مكاتب المحامين.
وعلى طالب القيد أن يرفق بطلب قيده بجدول المحامين تحت التمرين بيانا باسم المحامى الذى التحق بمكتبه وعنوانه مرفقا به موافقة المحامى، أو بيانا بالإدارة القانونية بالجهة التي التحق بها والتى يجوز للمحامين مزاولة أعمال المحاماة فيها طبقا لأحكام هذا القانون واسم المحامى الذى سيتولى الإشراف عليه فى هذه الإدارة مرفقا به موافقتها.$b$, E'\n', E'\r\n')),
    (23, 0, ARRAY['d6f3176d94e7de4e766352127df870ac']::text[], ARRAY['ca9f80731d930e67005426599299d57b']::text[], '994e4d40c42447c3946d601e0fc34ce6', replace($b$يقدم طلب القيد بجدول المحامين تحت التمرين مع طلب القيد بالجدول العام ويعرض على لجنة القبول طبقا لأحكام الفصل السابق.$b$, E'\n', E'\r\n')),
    (24, 0, ARRAY['03bed17f8e34feae0fc1195f676dcaca']::text[], ARRAY['121998c298f02a8d391f75272498bfd0']::text[], '514a99c868ea31e9ae6e360806717ac1', replace($b$تكون مدة التمرين سنتين تبدأ من تاريخ حلف اليمين، يتم إنقاصها إلى سنة واحدة للحاصلين على دبلوماتين من دبلومات الدراسات العليا فى القانون أو على أى مؤهل أعلى، فإذا لم يقيد المحامى أمام المحاكم الابتدائية خلال ستة أشهر من انقضاء المدة المشار إليها، ينتقل تلقائيا إلى جدول غير المشتغلين دون حاجة إلى صدور قرار بذلك من لجنة القيد، ويجوز له طلب إعادة القيد متى توافرت له الشروط المقررة فى هذا القانون.$b$, E'\n', E'\r\n')),
    (25, 0, ARRAY['b3e136b72086662f4b1d155de1a25fc1']::text[], ARRAY['61fac8ed38414c28cf0f30fe62b12cb9']::text[], 'c4347c8c32dfbef1a174285e20996e7e', replace($b$يكون تمرين المحامى فى السنة الأولى بأن يعاون المحامى الذى يتمرن بمكتبه أو بالإدارة القانونية التى ألحق بها فى إعداد الأبحاث والمراجع واستخلاص أحكام المحاكم وتحضير صحف الدعاوى ومستنداتها.
ويجوز له الحضور أمام المحاكم الجزئية باسم المحامى الذى يتمرن بمكتبه أو عن محامى الإدارة القانونية التى ألحق بها دون أن يكون له الحق فى أن يوقع صحف الدعاوى أو المذكرات أو الأوراق التى تقدم إلى المحاكم المذكورة أو إلى مكاتب الشهر أو التوثيق أو مكاتب السجل التجارى أو أن يعد عقودا باسمه.$b$, E'\n', E'\r\n')),
    (26, 0, ARRAY['92c8af49d47602d4cf6a732f22e9965e']::text[], ARRAY['c89ee95e53cbdc0c4071a3ea291125e6']::text[], '6aeae00323d2e443426a2cd18ad2ee98', replace($b$للمحامى تحت التمرين فى السنة الثانية أن يترافع باسمه أمام المحاكم الجزئية – فيما عدا محاكم أمن الدولة والمحاكم المستعجلة - وذلك تحت إشراف المحامى الذى التحق بمكتبه أو محامى الإدارة القانونية التى ألحق بها.
كما يجوز له الحضور باسمه فى تحقيقات النيابة والشرطة فى مواد المخالفات والجنح وبأسم المحامى الذى يتمرن فى مكتبه فى مواد الجنايات.
ويجوز له الحضور أمام المحاكم الابتدائية عن المحامى الذى يتمرن فى مكتبه أو محامى الإدارة القانونية التى ألحق بها.
كما يجوز له الحضور أمام هذه المحاكم عن محام أخر لإبداء طلب التأجيل.
كما يجوز له أن يعد باسمه العقود التى لا تجاوز قيمتها خمسة آلاف جنيه والتى لا تحتاج إلى شهر أو توثيق.
وفى جميع الأحوال لا يجوز للمحامى تحت التمرين تقديمه فتوى كتابية باسمه أو التوقيع على العقود التى تقدم إلى الشهر العقارى فيما عدا طلبات إثبات التاريخ.$b$, E'\n', E'\r\n')),
    (27, 0, ARRAY['4f78abf6f3f7a3a83923f35a8d98f675']::text[], ARRAY['140457718d61ebd4bb17457d6f137164']::text[], '1db55eb7ab2850f3cd9326c541b639f3', replace($b$لا يجوز للمحامى تحت التمرين أن يفتح مكتبا باسمه طوال فترة التمرين.$b$, E'\n', E'\r\n')),
    (28, 0, ARRAY['e4ea6d3d626230dc7b4c72ec5955ef70']::text[], ARRAY['4b568f1d9cdc3fc771819aa5222fddd1']::text[], '6c780d20ed196d9cb96f0ab1dad61080', replace($b$تنظم النقابات الفرعية للمحامين فى بداية كل سنة قضائية ولمدة ست شهور، محاضرات للمحامين تحت التمرين تتناول الجانب التطبيقى لأعمال المحاماة.
وذلك طبقا للمنهج الذى يحدده مجلس النقابة، ويدعى لإلقاء هذه المحاضرات قدامى المحامين ورجال القضاء وأساتذة القانون وخبراؤه المتخصصون.
وعلى مجلس النقابة أن ينشئ معهدا للمحاماة لتدريب المحامين تحت التمرين.$b$, E'\n', E'\r\n')),
    (29, 0, ARRAY['d5c08566473c70685a7511171a8ae475']::text[], ARRAY['5d31bb0195056111fd54fa13af54e16e']::text[], 'de5e23957a06dc8e7854218e08235d2f', replace($b$على كل محام من المقيدين أمام محكمة النقض أو من المقيدين أمام محاكم الاستئناف أن يلحق بمكتبه محاميا تحت التمرين على الأقل، ويحدد مجلس النقابة العامة سنويا الحد الأدنى للمكافأة التى يستحقها المتدرب فى ضوء المتغيرات الاقتصادية.
ويجوز لمجلس النقابة الفرعية بناء على طلب المحامى المقبول أمام النقض ومحاكم الاستئناف أن يقرر إعفاؤه من قبول أى محام للتمرين بمكتبه إذا رأى من ظروفه ما يبرر ذلك.$b$, E'\n', E'\r\n')),
    (30, 0, ARRAY['0eff32281a48d8332f3e4905cb27238b']::text[], ARRAY['3e802ac52c5ac66954368d3ae77c679e']::text[], 'e92ebe02473ae540e86780a17ab84d1b', replace($b$ملغاة$b$, E'\n', E'\r\n')),
    (31, 0, ARRAY['02b624eeb01b41618ac3c8644171b4b4']::text[], ARRAY['741dee8eb2cef9131f737b5e3042a8a4']::text[], '5d2e99594586062a5bdb5ba619ae7d91', replace($b$يشترط لقيد المحامى فى جدول المحامين أمام المحاكم الابتدائية:
(1) أن يكون قد أمضى دون انقطاع فترة التمرين المنصوص عليها فى المادة (24).
(2) أن يقدم صورة من البطاقة الضريبية سارية المفعول ثابت بها اشتغاله بالمحاماة دون سواها.
(3) أن يجتاز بنجاح اختبارات معهد المحاماة.
ويسرى هذا الشرط على المحامين الذين يبدأ قيدهم بعد تاريخ العمل بهذا القانون وبعد صدور قرار مجلس النقابة العامة فى تنظيم الالتحاق بمعهد المحاماة أو معاهد الدراسات القانونية المنصوص عليها فى المادة
(28).$b$, E'\n', E'\r\n')),
    (32, 0, ARRAY['ad669ede97731faf7e257f4076b11f01']::text[], ARRAY['361bafc14f1c54abe24c1c5b408047d0']::text[], 'fc112aef8d14f607ceac4246a92c11a8', replace($b$يجوز قيد المحامى مباشرة أمام المحاكم الابتدائية إذا كان قد أمضى فترة التمرين فى أعمال تعد نظيرة لأعمال المحاماة وفق أحكام المادة (46).$b$, E'\n', E'\r\n')),
    (33, 0, ARRAY['a098fbd7bcbdac1f9692394c7cb0eb46']::text[], ARRAY['13bf5c49e943a2f512d40bfffb4bdc77']::text[], '1eb3c11da4d490819477aa46e8b05d5e', replace($b$يقدم طلب القيد فى جدول المحامين أمام المحاكم الابتدائية إلى لجنة قبول المحامين المنصوص عليها فى المادة (16).
ولمجلس النقابة أن يشكل لجنة خاصة للقبول أمام المحاكم الابتدائية من خمسة من بين أعضائها يرأسها أقدمهم، وتسرى عليها الأحكام المقررة بالنسبة للجنة قبول المحامين.
وتقدم طلبات القيد إلى لجنة القبول المختصة مصحوبة بالمستندات المثبتة لتوافر شروط القيد وشهادة من النقابة الفرعية التى يقع فى دائرتها مكتب المحامى أو الإدارة القانونية التى قضى فيها فترة التمرين وذلك طبقا لما يقرره النظام الداخلى للنقابة.
وتبلغ قرارات اللجنة بالقبول أو الرفض إلى الطالب والى النقابة الفرعية المختصة خلال خمسة عشر يوما بخطاب مسجل مصحوب بعلم الوصول.
ولمن رفض طلبه أن يطعن فى قرار الرفض أمام محكمة استئناف القاهرة خلال ستين يوما من تاريخ إبلاغه بالقرار.$b$, E'\n', E'\r\n')),
    (34, 0, ARRAY['2e465f5718cd6c3a7213c387c848da16']::text[], ARRAY['b90e52b15f5bddde8af9eb8df4aaa183']::text[], '3909fde77d7f9fe7125a8b306e789df7', replace($b$يجوز للمحامى المقيد أمام المحاكم الابتدائية أن يفتح مكتبا باسمه منفردا أو مع غيره، ويكون حضوره أمام المحاكم الجزئية والمحاكم الابتدائية والمحاكم الإدارية التى تنظرها ويجوز له الحضور أمام محاكم الاستئناف ومحاكم القضاء الإدارى نيابة عن أحد المحامين المقيدين أمام هذه المحاكم وعلى مسئوليته كما يكون له أن يحضر باسمه فى سائر التحقيقات التى تجريها النيابة العامة.
وللمحامى المقيد أمام المحاكم الابتدائية إعداد العقود المختلفة وشهرها وتوقيع الطلبات والأوراق المتعلقة بها، وذلك فيما عدا عقود تأسيس شركات المساهمة وعقود الرهن الرسمى أو تعديلها.
ولا يجوز للمحامى أمام المحاكم الابتدائية إعطاء الآراء والفتاوى القانونية المكتوبة.$b$, E'\n', E'\r\n')),
    (35, 0, ARRAY['5601912801735848502bbfdbbe8a66ce']::text[], ARRAY['4f07a717461f23981bdfe1fdf463c6d5']::text[], '36e917a366d027136db33da4534a56ad', replace($b$يشترط لقيد المحامى أمام محاكم الاستئناف أن يكون المحامى قد اشتغل بالمحاماة فعلا خمس سنوات على الأقل من تاريخ قيد اسمه بجدول المحامين المقبولين للمرافعة أمام المحاكم الابتدائية.
ويثبت الاشتغال بالمحاماة بتقديم بيان رسمى بالجلسات التى يكون قد حضرها وبتقديم صور المذكرات والأوراق القضائية التى يكون قد باشرها أو الفتاوى والآراء القانونية أو العقود التى يكون قد أعدها وأن يقدم شهادة من النقابة الفرعية التى يزاول عمله فى دائرتها وذلك طبقا لما يقرره النظام الداخلى للنقابة.
ويجوز استثناء القيد مباشرة أمام محاكم الاستئناف لمن لم يسبق قيده أمام المحاكم الابتدائية إذا كان قد اشتغل بأعمال تعد نظيرة لأعمال المحاماة طبقا لأحكام المادة (46) وذلك لمدة سبع سنوات على الأقل.
ولا يجوز قبول القيد لأول مرة بجدول المحامين أمام محاكم الاستئناف لمن يكون قد انقطع عن مزاولة الأعمال القانونية النظيرة مدة تجاوز عشر سنوات.$b$, E'\n', E'\r\n')),
    (36, 0, ARRAY['01e2a5cb9c5dc123635458fa3589203e']::text[], ARRAY['e8b6a8b18cc3dedc50f2a800f5d6bb22']::text[], '625810d57921a9cefd4bfb58b00ec4c5', replace($b$تقدم طلبات القيد أمام محاكم الاستئناف إلى لجنة القبول المنصوص عليها فى المادة (16).
ويجوز لمجلس النقابة أن يشكل لجنة خاصة للقبول أمام محاكم الاستئناف من خمسة من بين أعضائه يرأسها أقدمهم، وتسرى عليها الأحكام المقررة بالنسبة للجنة قبول المحامين.
وتبلغ قرارات اللجنة بالقبول أو الرفض إلى الطالب والى النقابة الفرعية المختصة خلال خمسة عشر يوما بخطاب مسجل مصحوب بعلم الوصول.
ولمن يرفض طلبه أن يطعن فى قرار الرفض أمام محكمة استئناف القاهرة خلال ستين يوما من تاريخ إبلاغه بالقرار.$b$, E'\n', E'\r\n')),
    (37, 0, ARRAY['5dea1b25324bb80790fb6de7e3d19ebc']::text[], ARRAY['bd58840ad19abcd29091e8d1bbcc9908']::text[], '9c6ac2a8f9ce08ba78028de686c85197', replace($b$للمحامى المقيد بجدول محاكم الاستئناف حق الحضور والمرافعة أمام جميع محاكم الاستئناف ومحاكم القضاء الإدارى، ولا يجوز قبول صحف الدعاوى أمام هذه المحاكم وما يعادلها إلا إذا كان موقعا عليها منه، وإلا حكم ببطلان الصحيفة.
ويكون للمحامى أمام محاكم الاستئناف حق الحضور والمرافعة أمام جميع المحاكم فيما عدا محاكم النقض والإدارية العليا والدستورية العليا.
كما يكون له إبداء الفتاوى القانونية وإعداد العقود وشهرها والقيام بكافة أعمال المحاماة الأخرى.$b$, E'\n', E'\r\n')),
    (38, 0, ARRAY['a92ea506b67766d1ec942fa547ef9eef']::text[], ARRAY['43e7794cef05b3046d7cb492e79f4885']::text[], '95adf2b8934c309136490d164c4cf518', replace($b$ينشأ جدول خاص للمحامين المقبولين أمام محكمة النقض وما يعادلها وتعد المحكمة الإدارية العليا والمحكمة الدستورية العليا فى ذلك معادلة لمحكمة النقض.$b$, E'\n', E'\r\n')),
    (39, 0, ARRAY['c0dc68abf5c56ec1173d9771965eeef8']::text[], ARRAY['87545ccf8915b58c9a8c401309140f96']::text[], 'ed14234e7d5d28c80cf2d95b60c1cea2', replace($b$يشترط لقبول طلب القيد بجدول المحامين أمام محكمة النقض أن يكون طالب القيد من الفئات الآتية:
(1) المحامون المقبولون أمام محاكم الاستئناف الذين يكون قد مضى على اشتغالهم بالمحاماة فعلا أمام هذه المحاكم عشر سنوات على الأقل وكانت لهم أبحاث أو مذكرات أو فتاوى قانونية مبتكرة.
(2) الشاغلون لوظيفة أستاذ فى مادة القانون بالجامعات المصرية.
(3) المستشارون السابقون بالمحاكم وما يعادلها من وظائف الهيئات القضائية.$b$, E'\n', E'\r\n')),
    (40, 0, ARRAY['2f196647de8afc2d5968172695b5083b']::text[], ARRAY['e1975edcc1ebeb96cb7562c4668fe6b6']::text[], '62d2e321f01b9e7b52d4ecdce519f35f', replace($b$يقدم طلب القيد فى جدول المحامين المقبولين أمام محكمة النقض والمحكمة الإدارية العليا إلى لجنة تشكل برئاسة رئيس محكمة النقض أو أحد نوابه وعضوية النائب العام أو أحد مساعديه ونقيب المحامين أو وكيل النقابة وعضوين يندبهما مجلس النقابة سنويا من بين أعضائه ويبلغ قرار اللجنة بالقبول أو الرفض إلى الطالب والى النقابة العام.$b$, E'\n', E'\r\n')),
    (41, 0, ARRAY['7c758255e8746dddbc4764fbbd7a98f8']::text[], ARRAY['439235d6d77d2145459003d92ba424fc']::text[], 'd991f0af6a6620e00c5f08731c789cf9', replace($b$فى غير المواد الجنائية لا يجوز التقرير بالطعن أمام محكمة النقض والمحكمة الإدارية العليا والمحكمة الدستورية العليا، إلا للمحامين المقيدين بجدول المحامين أمام محكمة النقض وإلا حكم بعدم قبول الطعن، كما لا يجوز لغيرهم الحضور عن الخصوم والمرافعة أمام هذه المحاكم.$b$, E'\n', E'\r\n')),
    (42, 0, ARRAY['26932eda70ec1146ba55d62dc5ee8c7f']::text[], ARRAY['2314b50acb99f683ee044a75b97d2c32']::text[], 'c3e7ab1d52dedddd25e725ab275c3eb6', replace($b$مع عدم الإخلال بأحكام الاتفاقيات القضائية المبرمة بين مصر والدول العربية للمحامى من رعايا هذه الدول المرافعة أمام المحاكم المصرية بالاشتراك مع محام مصرى من الدرجة المقابلة للدرجة التى يحق له المرافعة أمامها طبقا لقانون بلده وذلك فيما عدا الطعون الدستورية والإدارية وبإذن من النقابة العامة وفى دعوى معينة بذاتها وبشرط المعاملة بالمثل.$b$, E'\n', E'\r\n')),
    (43, 0, ARRAY['52b557edb03994badd8837c38fe433b7']::text[], ARRAY['b960bc0bdaa53c14bb82efb8a1305662']::text[], 'ca94b532c22c77faafe2069b84eb36f4', replace($b$للمحامى الذى يرغب فى اعتزال المحاماة أن يطلب إلى لجنة قبول المحامين المنصوص عليها فى المادة
(16) نقل اسمه إلى جدول المحامين غير المشتغلين.
وعلى المحامى أن يطلب أيضا نقل اسمه إلى جدول غير المشتغلين إذا تولى إحدى الوظائف أو الأعمال التى لا يجوز الجمع بينها وبين المحاماة أو إذا كف عن مزاولة المهنة ويتعين عليه أن يخطر لجنة القبول بذلك خلال ثلاثين يوما.
وعلى الإدارات القانونية فى الجهات التى يجوز لمحاميها مزاولة أعمال المحاماة طبقا لأحكام هذا القانون إخطار النقابة بأى تغير يطرأ على أعضاء هذه الإدارات بما يستوجب نقل اسم العضو إلى جدول غير المشتغلين.$b$, E'\n', E'\r\n')),
    (44, 0, ARRAY['0ee2fb8b37d9505a2cd6174dc3b821de']::text[], ARRAY['060ec237a334a4773ea2ab28f75d16f3']::text[], 'f357e75507e5d4fc6b9f381448b6c547', replace($b$لمجلس النقابة بعد سماع أقوال المحامى أو بعد إعلانه فى حالة تخلفه عن الحضور، أن يصدر قرارا مسببا بنقل اسمه إلى جدول المحامين غير المشتغلين إذا فقد شرطا من شروط القيد فى الجدول العام المنصوص عليها فى هذا القانون.
ويكون للمحامى حق الطعن أمام الدائرة الجنائية بمحكمة النقض فى القرار الذى يصدر فى هذا الشأن خلال الأربعين يوما التالية لإعلانه بهذا القرار.$b$, E'\n', E'\r\n')),
    (45, 0, ARRAY['db07d84ed963f3d36ccac9b1bb54903e']::text[], ARRAY['5a521d54ed144dbe4963e63b3deafe45']::text[], '6ea60f58a9d9614938e458ecba4f937d', replace($b$يجوز لمن ينقل اسمه إلى جدول غير المشتغلين أن يطلب إعادة قيده إذا كان من المحامين السابق قيدهم بجدول المحامين أمام محاكم الاستئناف أو محكمة النقض.
فإذا كان من غير هؤلاء، فلا يجوز إعادة قيده إلا إذا كان قد مارس أعمالا نظيرة لأعمال المحاماة خلال المدة التى نقل فيها اسمه إلى جدول غير المشتغلين.
وفى جميع الأحوال يشترط ألا يزيد انقطاع المحامى عن ممارسة أعمال المحاماة أو الأعمال النظيرة لها على خمس عشرة سنة، مع عدم الإخلال بحقه فى أن يطلب قيده من جديد فى الجدول العام إذا توافرت فيه شروط هذا القيد.
ويجوز لمن لا يتوافر فيه شروط هذه المادة من المقيدين بجدول غير المشتغلين أن يعدلوا أوضاعهم خلال سنة من تاريخ العمل بهذا القانون.$b$, E'\n', E'\r\n')),
    (46, 0, ARRAY['cbd3489e7f8ac6ea2e0bf99f91bb24fb']::text[], ARRAY['ba4928ecd80437c5e2739b318d1f7429']::text[], 'e025efebab875bcc6482ff078d5c16d7', replace($b$يعد نظيرا لأعمال المحاماة عند تطبيق أحكام القيد بجداول المحامين المشار إليها فى الفصل السابق، الوظائف الفنية فى القضاء ومجلس الدولة والمحكمة الدستورية العليا والنيابة العامة والنيابة الإدارية وإدارة قضايا الحكومة وتدريس القانون فى الجامعات.
ويصدر قرار من وزير العدل بعد موافقة مجلس النقابة العامة بما يعتبر من الأعمال القانونية الأخرى التى تعد نظيرة لأعمال المحاماة.$b$, E'\n', E'\r\n')),
    (47, 0, ARRAY['250135337716e8c8f4fbd22e4dc766f4']::text[], ARRAY['bff57fd8a659568b053dedac5848b60e']::text[], '2932d788b5172b70f9406f12af44b0d7', replace($b$للمحامى أن يسلك الطريقة التى يراها ناجحة طبقا لأصول المهنة فى الدفاع عن موكله ولا يكون مسئولا عما يورده فى مرافعته الشفوية أو فى مذكراته المكتوبة مما يستلزمه حق الدفاع، وذلك مع عدم الإخلال بأحكام قانون الإجراءات الجنائية وقانون المرافعات المدنية والتجارية.$b$, E'\n', E'\r\n')),
    (48, 0, ARRAY['2bf6faa4a51d95dcf569cd372352c05f']::text[], ARRAY['a2dcf9e524822b4d6a93eb8b07b0d7d1']::text[], '7a9dacb2326e99fb7f7eba5a20543bdc', replace($b$للمحامى حرية قبول التوكيل فى دعوى معينة أو عدم قبوله وفق ما يمليه عليه اقتناعه.$b$, E'\n', E'\r\n')),
    (49, 0, ARRAY['99720ee7eae7703682c2f48124d3e46a']::text[], ARRAY['b924ac7258b8fb8916ebbcb562495c82']::text[], 'd67b748143af27e51cfcf0c2f885c09a', replace($b$للمحامى الحق فى أن يعامل من المحاكم وسائر الجهات التى يحضر أمامها بالاحترام الواجب للمهنة.
واستثناء من الأحكام الخاصة بنظام الجلسات والجرائم التى تقع فيها المنصوص عليها فى قانونى المرافعات والإجراءات الجنائية إذا وقع من المحامى أثناء وجوده بالجلسة لأداء واجبه أو بسببه إخلال بنظام الجلسة أو أى أمر يستدعى محاسبته نقابيا أو جنائيا، يأمر رئيس الجلسة بتحرير مذكرة بما حدث ويحيلها إلى النيابة العامة ويخطر النقابة الفرعية المختصة بذلك.$b$, E'\n', E'\r\n')),
    (50, 0, ARRAY['90313c5271894b93a4437273be68ca40']::text[], ARRAY['ea0a40ea5c1c62fb9a7955396bfb7dc5']::text[], '1eea24b201fd67e9b21754dc8a9e77f5', replace($b$لا يجوز القبض على محام أو حبسه احتياطيا لما ينسب إليه فى الجرائم المنصوص عليها فى المادة السابقة وجرائم القذف والسب والإهانة بسبب أقوال أو كتابات صدرت منه أثناء أو بسبب ممارسته أى من أعمال المهنة المشار إليها فى هذا القانون.
ويحرر فى هذه الحالة مذكرة بما حدث وتحال إلى النيابة العامة وتبلغ صورتها إلى مجلس النقابة، وللنائب العام أن يتخذ الإجراءات إذا كان ما وقع من المحامى يشكل جريمة يعاقب عليها فى قانون العقوبات، أو أن يحيله إلى مجلس النقابة إذا كان ما وقع منه مجرد إخلال بالنظام أو الواجب المهنى وفى هذه الحالة تجرى المحاكمة فى جلسة سرية.
ولا يجوز أن يشترك فى نظر الدعوى القاضى أو أحد أعضاء الهيئة التى وقع أمامها الفعل المؤثم.$b$, E'\n', E'\r\n')),
    (51, 0, ARRAY['9960434847b00a6f53fa6a09e9b338a3']::text[], ARRAY['29e0dbcf068301e88732d65d40d0fa3b']::text[], '59f3920e4ae5fa7bcec289e7e9b00bbd', replace($b$لا يجوز التحقيق مع محامٍ أو تفتيش مكتبه إلا بمعرفة أحد أعضاء النيابة العامة أو قاضى التحقيق فى الأحوال التى يجيز فيها القانون ذلك.
وفى غير حالات التلبس، لا يجوز لمأمور الضبط القضائى احتجاز أو القبض على المحامى الموجه له اتهام بارتكاب جناية أو جنحة أثناء مباشرته حق الدفاع، ويتعين عرض الأمر فورا على المحامى العام الأول لنيابة الاستئناف المختصة.
ويجب على النيابة العامة أن تخطر مجلس النقابة أو مجلس النقابة الفرعية قبل الشروع فى تحقيق أية شكوى ضد محام بوقت مناسب.
وللنقيب أو رئيس النقابة الفرعية إذا كان المحامى متهما بجناية أو جنحة خاصة بعمله أن يحضر هو أو من ينيبه من المحامين، التحقيق.
ولمجلس النقابة، ولمجلس النقابة الفرعية المختص طلب صور التحقيق بغير رسوم.$b$, E'\n', E'\r\n')),
    (52, 0, ARRAY['d428fe544e6c447269a49fa635ded614']::text[], ARRAY['eb1469b420870da25c8a75affe0dcd02']::text[], '7ee9eb7e706375f13b19f90788c1eb99', replace($b$للمحامى حق الاطلاع على الدعاوى والأوراق القضائية والحصول على البيانات المتعلقة بالدعاوى التى يباشرها.
ويجب على جميع المحاكم والنيابات ودوائر الشرطة ومأموريات الشهر العقارى وغيرها من الجهات التى يمارس المحامى مهمته أمامها أن تقدم له التسهيلات التى يقتضيها القيام بواجبه وتمكينه من الاطلاع على الأوراق والحصول على البيانات وحضور التحقيق مع موكله وفقا لأحكام القانون ولا يجوز رفض طلباته دون مسوغ قانونى.
ويجب إثبات جميع ما يدور فى الجلسة فى محضرها.$b$, E'\n', E'\r\n')),
    (53, 0, ARRAY['d50ae889578a2b4a9de0ab586c6acdce']::text[], ARRAY['0ff3b50ae7f89701e1f842be352c44f6']::text[], '39659d8977aa9203a43f51a5807438b8', replace($b$للمحامى المرخص له من النيابة بزيارة أحد المحبوسين فى السجون العمومية حق زيارته فى أى وقت والاجتماع به على انفرد، وفى مكان لائق داخل السجن.$b$, E'\n', E'\r\n')),
    (54, 0, ARRAY['2d561acb7a872d32b0001a2452406a0b']::text[], ARRAY['ecb8f9f6b09a94ec4c990dbb509b28d6']::text[], '68320f8af218139b340a216736bd7d0a', replace($b$يعاقب كل من تعدى على محام أو أهانه بالإشارة أو القول أو التهديد أثناء قيامه بأعمال مهنته أو بسببها بالعقوبة المقررة لمن يرتكب هذه الجريمة ضد أحد أعضاء هيئة المحكمة.$b$, E'\n', E'\r\n')),
    (55, 0, ARRAY['8ba8211e492d86a1793bcf8facb2f9e5']::text[], ARRAY['72e4a593fa156f51c508f7108a5f294b']::text[], '348b45e7142b54a9602666b257bd086a', replace($b$لا يجوز الحجز على مكتب المحامى وكافة محتويات المستخدمة فى مزاولة المهنة.
قضي بعدم دستورية الفقرة الثانية من هذه المادة.$b$, E'\n', E'\r\n')),
    (56, 0, ARRAY['2538f4e738ad4a03855de2508a10a2d6']::text[], ARRAY['24a893198b5c60a001f8f2a5b5e5de3a']::text[], '70aa01279e5f39db05e8c5c7a713bf61', replace($b$للمحامى سواء كان خصما أصليا أو وكيلا فى دعوى أن ينيب عنه فى الحضور أو فى المرافعات أو فى غير ذلك من إجراءات التقاضى محاميا أخر تحت مسئوليته دون توكيل خاص ما لم يكن فى التوكيل ما يمنع ذلك.$b$, E'\n', E'\r\n')),
    (57, 0, ARRAY['d66a59c5bfe77957291693fec3de91fc']::text[], ARRAY['57eb7334e69e75eea4f9fa17fd4b917a']::text[], '699304cb13fb950ba7a27f1237822c69', replace($b$لا يلتزم المحامى الذى يحضر عن موكله بمقتضى توكيل عام أن يودع التوكيل بملف الدعوى ويكتفى بالاطلاع عليه وإثبات رقمه وتاريخه والجهة المحرر أمامها بمحضر الجلسة.$b$, E'\n', E'\r\n')),
    (58, 0, ARRAY['d4d3b36bfc7456bdebd9616f5a98a5ea']::text[], ARRAY['f1ffa4fe6f7adc504895e877312d4d68']::text[], '665b3f84c4fb83a664d4f2c64c8193cb', replace($b$لا يجوز فى غير المواد الجنائية التقرير بالطعن أمام محكمة النقض أو المحكمة الإدارية العليا إلا من المحامين المقررين لديها سواء كان ذلك عن أنفسهم أو بالوكالة من الغير.
كما لا يجوز تقديم صحف الاستئناف أو تقديم صحف الدعاوى أمام محكمة القضاء الإدارى إلا إذا كانت موقعة من أحد المحامين المقررين أمامها.
وكذلك لا يجوز تقديم صحف الدعاوى وطلبات أوامر الأداء للمحاكم الابتدائية والإدارية إلا إذا كانت موقعه من أحد المحامين المقررين أمامها على الأقل.
وكذلك لا يجوز تقديم صحف الدعاوى أو طلبات أوامر الأداء للمحاكم الجزئية إلا إذا كانت موقعه من أحد المحامين المشتغلين وذلك متى بلغت أو جاوزت قيمة الدعوى أو أمر الأداء خمسين جنيها.
ويقع باطلا كل إجراء يتم بالمخالفة لأحكام هذه المادة.$b$, E'\n', E'\r\n')),
    (59, 0, ARRAY['d1c6fac0c68e7b937924b6a2ef3ab754']::text[], ARRAY['1b3efe6845b61268e47f2cd97a695d55']::text[], 'f1d27ee481533ee24ca5b94a780b8338', replace($b$مع مراعاة حكم الفقرة الثانية من المادة (34) لا يجوز تسجيل العقود التى تبلغ قيمتها عشرين ألف جنيه فأكثر أو التصديق أو التأشير عليها بأى إجراءات أمام مكاتب الشهر والتوثيق أو أمام الهيئة العامة للاستثمار أو مكاتب السجل التجارى وغيرها إلا إذا كانت موقعا عليها من أحد المحامين المقبولين للمرافعة أمام المحاكم الابتدائية على الأقل بعد التصديق على توقيعه أمام النقابة العامة أو النقابة الفرعية التابع لها.$b$, E'\n', E'\r\n')),
    (60, 0, ARRAY['90ad39702b44241b2b1c022e22219178']::text[], ARRAY['b4439fee6d835b463b6ee25b3752e8a4']::text[], '45ac0c1ad12dd278df50ee96288c85f8', replace($b$يشترط أن يتضمن عقد أو نظام تأسيس أى شركة من الشركات التى يشترط القانون أن يكون لها مراقب حسابات، تعيين مستشار قانونى من المحامين المقبولين للمرافعة أمام محاكم الاستئناف على الأقل.
ولا يجوز قيد هذه الشركات فى السجل التجارى أو تجديد قيدها قبل التحقق من استيفاء ذلك عن طريق إيداع صورة من التوكيل الصادر للمحامى من ممثلها القانونى معتمدا من نقابة المحامين الفرعية التى يتبعها المحامى.
ويجب على المحامى خلال ثلاثين يوما على الأكثر من تاريخ التوكيل إيداع صورة منه بالنقابة العامة أو النقابة الفرعية وسداد مبلغ خمسين جنيها مصريا سنويا عن كل وكالة من هذه الشركات لصالح صندوق الرعاية الصحية والاجتماعية تخصص لدعم المحامين الشبان وتدريبهم ورعايتهم، ويسرى على هذا المبلغ أحكام الاشتراك المنصوص عليها فى المادتين (169) و (170) من هذا القانون، ولا يجوز الإعفاء منه.
ويسرى هذا الحكم على الشركات المذكورة القائمة عند العمل بأحكام هذا القانون وذلك عند تجديد قيدها بالسجل التجارى.$b$, E'\n', E'\r\n')),
    (61, 0, ARRAY['946563d31f4f3fb365b20f7282ff101e']::text[], ARRAY['efdeaf0bc5649fa259080f6cc45907a8']::text[], 'b4fa8b899468277965c04af997c9a22b', replace($b$يقبل المحامون المقيدون بجدول محاكم الاستئناف على الأقل للقيد فى جداول الحراس القضائيين ووكلاء الدائنين.$b$, E'\n', E'\r\n')),
    (62, 0, ARRAY['173823183fa667d5c87f4ec9a9a6c680']::text[], ARRAY['085e8212b4885f451002165914433418']::text[], 'df9b8b5d30c28b5e03a9aa64c3df47ef', replace($b$على المحام أن يلتزم فى سلوكه المهنى والشخصى بمبادئ الشرف والاستقامة والنزاهة وأن يقوم بجميع الواجبات التى يفرضها عليه هذا القانون والنظام الداخلى للنقابة ولوائحها وآداب المحاماة وتقاليدها.
ويضع مجلس النقابة العامة مدونة للسلوك المهنى للمحاماة، تقرها الجمعية العمومية للنقابة وتنشر المدونة، وكل تعديل لها، فى الوقائع المصرية وتكون ملزمة لأعضاء النقابة، ويترتب على مخالفتهم لأحكامها انعقاد مسئوليتهم المهنية عن الأفعال التى ترتكب بالمخالفة لأحكام مدونة السلوك.$b$, E'\n', E'\r\n')),
    (63, 0, ARRAY['c8bf0c8c5e60f821c6990966d150d44c']::text[], ARRAY['22fdad1becaef66f707b7a7d84dd72b2']::text[], '03cfe49245baa068c67778a1cd2460f4', replace($b$يلتزم المحامى بأن يدافع عن المصالح التى تعهد إليه بكفاية وأن يبذل فى ذلك غاية جهده وعنايته.
ولا يجوز له النكوص عن الدفاع عن متهم فى دعوى جنائية إلا إذا استشعر أنه لن يستطيع بسبب ظروفه أو ملابسات الدعوى أن يؤدى واجب الدفاع فيها بأمانة وكفاية.$b$, E'\n', E'\r\n')),
    (64, 0, ARRAY['49d8ec6920c5c6dbf1fdd42d03e34850']::text[], ARRAY['a044f28113fc12bfc8caab95a2a05a98']::text[], '3778287812afb3e0e110a31567ac172b', replace($b$على المحامى تقديم المساعدات القضائية للمواطنين غير القادرين وغيرهم فى الحالات التى ينص عليها هذا القانون، وعليه أن يؤدى واجبه عمن يندب للدفاع عنه بنفس العناية التى يبذلها إذا كان موكلا. ولا يجوز للمحامى المنتدب للدفاع أن يتنحى عن مواصلة الدفاع إلا بعد استئذان المحكمة التى يتولى الدفاع أمامها وعليه أن يستمر فى الحضور حتى تقبل تنحيته وتعيين غيره.$b$, E'\n', E'\r\n')),
    (65, 0, ARRAY['4e966360cb57246e4e0834654633046b']::text[], ARRAY['ce67545493bfd12edec079fd3e60866b']::text[], 'b097a0e3d01d8ea695d76035023216f2', replace($b$على المحامى أن يمتنع عن أداء الشهادة عن الوقائع أو المعلومات التى علم بها عن طريق مهنته إذا طلب منه ذلك من أبلغها إليه، إلا إذا كان ذكرها له بقصد ارتكاب جناية أو جنحة.$b$, E'\n', E'\r\n')),
    (66, 0, ARRAY['1965fb66dd90504c661dae6f1c9bb74f']::text[], ARRAY['8e0fa41c141a7a0b93ea72d4f0943d22']::text[], '784715bbf19e5f28c8347a125debd52b', replace($b$لا يجوز لمن تولى وظيفة عامة أو خاصة وانتهت علاقته بها واشتغل بالمحاماة أن يقبل الوكالة بنفسه أو بواسطة محام يعمل فى مكتبه بأية صفة كانت فى دعوى ضد الجهة التى كان يعمل بها وذلك خلال السنوات الثلاث التالية لانتهاء علاقته بها.
ويسرى هذا الحظر على المحامى الذى يتولى عضوية مجلس الشعب أو مجلس الشورى أو المجالس المحلية بالنسبة للدعاوى التى ترفع على هذه المجالس.$b$, E'\n', E'\r\n')),
    (67, 0, ARRAY['01b65210f74014c426cfc53629d36312']::text[], ARRAY['e5e276044668f8e3e3a887d78903421a']::text[], '227ae25e68feb0e644277975ed243d5a', replace($b$يراعى المحامى فى مخاطبته المحاكم عند انعقادها أن يكون ذلك بالتوقير اللازم وأن يعمل على أن تكون علاقته بأعضاء الهيئات القضائية قائمة على التعاون والاحترام المتبادل.$b$, E'\n', E'\r\n')),
    (68, 0, ARRAY['c4f74ea6ca9f86e49ad16d66ff970daf']::text[], ARRAY['d3397ee08dc74031c5f9a5f46a718542']::text[], '992047717601d64840d77453501b6740', replace($b$يراعى المحامى فى معاملاته لزملائه ما تقضى به قواعد اللياقة وتقاليد المحاماة وفيما عدا الدعاوى المستعجلة يجب عليه أن يستأذن مجلس النقابة الفرعية التى يتبعها المحامى إذا أراد مقاضاة زميل له.
قضي بعدم دستورية الفقرة الثانية من هذه المادة.
وإذا لم يصدر الإذن فى الحالتين المبينتين بالفقرتين السابقتين خلال خمسة عشر يوما كان للمحامى اتخاذ ما يراه من إجراءات.$b$, E'\n', E'\r\n')),
    (69, 0, ARRAY['cbc05c65ad463a514f72b4ed55da2283']::text[], ARRAY['d3e71bd9a087935d4f5c801dc253722e']::text[], 'e03c56f48c63c6651fcfe23320c11e8c', replace($b$على المحامى أن يمتنع عن ذكر الأمور الشخصية التى تسئ لخصم موكله أو اتهامه بما يمس شرفه وكرامته، ما لم تستلزم ذلك ضرورة الدفاع عن مصالح موكله.$b$, E'\n', E'\r\n')),
    (70, 0, ARRAY['6a4c12a77b2f2c3375f9e067440ff419']::text[], ARRAY['a7ae7dc03327836e93b770e96fd4e05f']::text[], 'c2b4e7ac14da3eefc4763c087d0f3fd3', replace($b$لا يجوز للمحامى أن يدلى بتصريحات أو بيانات عن القضايا المنظورة التى يتولى الدفاع فيها أو أن ينشر أمورا من شأنها التأثير فى سير هذه الدعاوى ولصالح موكله أو ضد خصمه.$b$, E'\n', E'\r\n')),
    (71, 0, ARRAY['52fa5d65df567237e01b88b90e8922c2']::text[], ARRAY['6c238dde2afb668cdc0337c7f25020be']::text[], '04f6fdc5724bf9a3af301d99b8f7cc2c', replace($b$يحظر على المحامى أن يتخذ فى مزاولة مهنته وسائل الدعاية أو الترغيب أو استخدام الوسطاء أو الإيحاء بأى نفوذ أو صلة حقيقية أو مزعومة كما يحظر عليه أن يضع على أوراقه أو لافتة مكتبه اى ألقاب غير اللقب العلمى وبيان درجة المحكمة المقبول للمرافعة أمامها أو استخدام أى بيان أو اشارة إلى منصب سبق أن تولاه.
ويجوز لقاضى الأمور الوقتية بالمحكمة التابع لها المكتب المخالف بناء على طلب النقابة العامة أو النقابة الفرعية المختصة أن يأمر بإزالة اللافتة أو الأمر بإزالة المخالفة من أوراق المحامى وعدم قبول أوراقه أمام المحاكم ومكاتب الشهر العقارى لحين إزالة أسباب الشكوى.$b$, E'\n', E'\r\n')),
    (72, 0, ARRAY['9bdd9e87dfea7912d70cad92e3b40f43']::text[], ARRAY['1337e1fe9cbed43ca26c41d6e3e87703']::text[], '85ad86742cd84045630371f7c4e6153d', replace($b$مع عدم الإخلال بحقوق ورثة المحامى، لا يجوز أن تخصص حصة من أتعاب المحامى لشخص من غير المحامين ولو كان من موظفى مكتبه.$b$, E'\n', E'\r\n')),
    (73, 0, ARRAY['8e27915977b3a69a19cbb6c33494aa10']::text[], ARRAY['2a4d39b7b6ec319dd6b23db469328c50']::text[], 'fbcf73ee89168c5b1b59417fc5cb6977', replace($b$يكون حضور المحامى أمام جميع المحاكم بالرداء الخاص بالمحاماه، وعلى المحامى أن يحافظ على أن يكون مظهره لائقا وجديرا بالاحترام.$b$, E'\n', E'\r\n')),
    (74, 0, ARRAY['30c7ba0aabb64954450c89bb57d26524']::text[], ARRAY['88e76875d2e6299c80fc1261af77924d']::text[], '4088f37ebafde30d6b32e4e108729992', replace($b$مع مراعاة الأحكام الخاصة بالمحامين أعضاء الإدارات القانونية يجب على المحامى أن يتخذ له مكتبا لائقا فى دائرة النقابة المقيد بها.
ولا يجوز أن يكون للمحامى أكثر من مكتب واحد فى جمهورية مصر العربية.$b$, E'\n', E'\r\n')),
    (75, 0, ARRAY['6f7777c866f9510974a837f2f9402e24']::text[], ARRAY['c1a099bf8ac721092310ae37dd25e0ba']::text[], '35368409f71f1ad39d93f832289a136e', replace($b$يلتزم المحامي بالإشراف على الموظفين العاملين بمكتبه ومراقبة سلوكهم والتحقق من أنهم يؤدون ما يكلفون به بأمانة وصدق.
وللمحامي أن يصدر توكيلًا لواحد أو أكثر من العاملين بمكتبه للإطلاع نيابة عنه وتقديم الأوراق واستلامها لدى أية جهة وكذلك استلام الأحكام واتخاذ إجراءات تنفيذها وتسوية الرسوم والأمانات واستردادها.
ويقبل أن يكون هذا التوكيل مصدقاً عليه من النقابة الفرعية المختصة.$b$, E'\n', E'\r\n')),
    (76, 0, ARRAY['749aa86d2bfff7deda23eb369e085f41']::text[], ARRAY['915ba66d1ac7ae0874078ccc711dd959']::text[], '1e9db4bb5a77c08dfccfb298659cef52', replace($b$لا يجوز للمحامي التوقيع على صحف الدعاوى والطعون وسائر أوراق المحضرين والعقود المقدمة للشهر العقاري أو الحضور والمرافعة بالمخالفة لأحكام ممارسة أعمال المحاماة المنصوص عليها في هذا القانون وإلا حكم بعدم القبول أو البطلان بحسب الأحوال وذلك مع عدم الإخلال بمسئولية المحامي طبقاً لأحكام هذا القانون ومسئوليته قبل من أضر به الإجراء المخالف.$b$, E'\n', E'\r\n')),
    (77, 0, ARRAY['0423d081f9725d0c334082c3733ded91']::text[], ARRAY['a9eff901f38e20ea8a9f464d472911ee']::text[], '9bb1d8474d88249415c7abdb349106a7', replace($b$يتولى اًلمحامي تمثيل موكله في النزاع الموكل فيه في حدود ما يعهد به إليه وطبقا لطلباته، مع احتفاظه بحرية دفاعه في تكييف الدعوى وعرض الأسانيد القانونية طبقاً لأصول الفهم القانوني السليم.$b$, E'\n', E'\r\n')),
    (78, 0, ARRAY['373f2a8a3c7c634adb31f8c90b049e13']::text[], ARRAY['077b68bd1f1e6a9b44179e6fe39b1d0c']::text[], '8dae718737676f84198cbc452c38f725', replace($b$يتولى المحامي إبلاغ موكله بمراحل سير الدعوى وما يتم فيها وعليه أن يبادر إلى إخطاره بما يصدر من أحكام فيها وأن يقدم له النصح فيما يتعلق بالطعن في الحكم إذا كان في غير مصلحته، وأن يلفت نظره إلى مواعيد الطعن.$b$, E'\n', E'\r\n')),
    (79, 0, ARRAY['6e169116da30fd32f4cedd0b854f5718']::text[], ARRAY['c9f7ca62f64be2984a5593a7cddf3a9d']::text[], '6160bc4946b0b00aa5651f293114b4d4', replace($b$على المحامي أن يحتفظ بما يفضي به إليه موكله من معلومات، ما لم يطلب منه إبداءها للدفاع عن مصالحه في الدعوى.$b$, E'\n', E'\r\n')),
    (80, 0, ARRAY['0b63bd7d20c4d2b8cebe77922fb0ef82']::text[], ARRAY['cca74800fcf3b2aba29eeecb87b87d7d']::text[], '23f03e30f5d3a7802813a84a1f56dafd', replace($b$على المحامي أن يمتنع عن إبداء أية مساعدة ولو من قبيل المشورة لخصم موكله في النزاع ذاته أو في نزاع مرتبط به إذا كان قد أبدى فيه رأياً للخصم أو سبقت له وكالة عنه فيه ثم تنحى عن وكالته وبصفة عامة لا يجوز للمحامي أن يمثل مصالح متعارضة.
ويسري هذا الحظر على المحامي وشركائه وكل من يعمل لديه في نفس المكتب من المحامين بأية صفة كانت.$b$, E'\n', E'\r\n')),
    (81, 0, ARRAY['9b6eba7c069a04129cc9caaa0c02e01e']::text[], ARRAY['af1623b29e59c811166651418a362628']::text[], '11a5ec089477bfcb6bf55f5718074d2c', replace($b$لا يجوز للمحامي أن يبتاع كل أو بعض الحقوق المتنازع عليها إذا كان يتولى الدفاع بشأنها.$b$, E'\n', E'\r\n')),
    (82, 0, ARRAY['b6b39b114be841fee6402e2b032d3bdb']::text[], ARRAY['d9a5ccb944faeee24ee4af7082b5d7d4']::text[], '16c0f7031fe52a64329910a021ffea01', replace($b$للمحامي الحق في تقاضي أتعاب لما يقوم به من أعمال المحاماة والحق في استرداد ما أنفقه من مصروفات في سبيل مباشرة الأعمال التي وكل فيها.
ويتقاضى المحامي أتعابه وفقاً للعقد المحرر بينه وبين موكله، وإذا تفرع عن الدعوى موضوع الاتفاق أعمال أخرى حق للمحامي أن يطالب بأتعابه عنها.
ويدخل في تقدير الأتعاب أهمية الدعوى والجهد الذي بذله المحامي والنتيجة التي حققها وأقدمية درجة قيد المحامي، ويجب ألا تزيد الأتعاب على عشرين في المائة من قيمة ما حققه المحامي من فائدة لموكله في العمل موضوع طلب التقدير.
وفي جميع الأحوال لا يجوز أن يكون أساس تعامل المحامي مع موكله أن تكون أتعابه حصة عينية من الحقوق المتنازع عليها.
قضي بعدم دستورية ما تضمنته الفقرة الثالثة من هذه المادة من الاعتداد بملاءة الموكل كأحد عناصر تقدير الأتعاب ومن ألا تقل الأتعاب المستحقة عن 5% من قيمة ما حققه المحامي من فائدة لموكله.$b$, E'\n', E'\r\n')),
    (83, 0, ARRAY['1df71f6d6b2c06cdc81654e789335061']::text[], ARRAY['3eb00f583560df908c88b8e1c97dacbd']::text[], '44c78e41bf67b25349e5e0cbb3a30ea5', replace($b$إذا انتهت الدعوى أو النزاع صلحاً أو تحكيماً استحق المحامي الأتعاب المتفق عليها ما لم يكن قد تم الاتفاق على غير ذلك.
ويستحق المحامي أتعابه إذا أنهى الموكل الوكالة دون مسوغ قبل إتمام المهمة الموكلة إليه.
وللمحامي الذي صدر قرار بتقدير أتعابه أو عقد صلح مصدق عليه من مجلس النقابة الفرعية أو من المحكمة أن يحصل على أمر باختصاصه بعقارات من صدر ضده قرار التقدير أو عقد الصلح أو الحكم.$b$, E'\n', E'\r\n')),
    (85, 0, ARRAY['ef964b19e908da567d850957887fe4f9']::text[], ARRAY['9293e9fb025af5cef9de6124a04b1ac6']::text[], '4e137ab7ad4e3af50f866dd4637f0158', replace($b$قضي بسقوط المادة.
ولا يكون قرار التقدير نهائيا إلا بعد انتهاء ميعاد الاستئناف دون طعن أو صدور الحكم فيه وتوضع الصيغة التنفيذية على قرارات التقدير النهائية بواسطة قاضى الأمور الوقتية المختص وذلك بغير رسوم.$b$, E'\n', E'\r\n')),
    (86, 0, ARRAY['c023e73e859721f411f8e5e208913089']::text[], ARRAY['3bae1aff8ce7e35394a77adcf732d057']::text[], '875465089593bbff96eb281849d15f09', replace($b$يسقط حق المحامي في مطالبة موكله أو ورثته بالأتعاب عند عدم وجود اتفاق كتابي بشأنها بمضي خمس سنوات من تاريخ انتهاء الوكالة أو من تاريخ وفاة الموكل حسب الأحوال.
وتنقطع هذه المدة بالمطالبة بها بكتاب موصى عليه.$b$, E'\n', E'\r\n')),
    (87, 0, ARRAY['349eb55adec274f5b691ecc652813f70']::text[], ARRAY['1d0dcd63f1dc6e06825b04c9e4b06b97']::text[], '0a68bc8fdd07e334ef5be5318bdb45b2', replace($b$للمحامي الحق في أن يسترد من موكله ما يكون قد أنفقه من مصروفات قضائية مؤيدة بالمستندات.$b$, E'\n', E'\r\n')),
    (88, 0, ARRAY['7681326a058001b7f11c6c09f5f30726']::text[], ARRAY['77246c20a0783093d26eb876de56671e']::text[], 'c0b9fc2857208db285d18bd5a5c00215', replace($b$لأتعاب المحامين وما يلحق بها من مصروفات امتياز يلي مباشرة حق الخزانة العامة على ما آل إلى موكله نتيجة عمل المحامي أو الحكم في الدعوى موضوع الوكالة وعلى ضمانات الإفراج والكفالات أياً كان نوعها.$b$, E'\n', E'\r\n')),
    (89, 0, ARRAY['5dfd7f4a1b3a2579e9123d6a6b46a647']::text[], ARRAY['b50e805ba9a4d376ef7a24bd27c9e0d3']::text[], 'f6ce960b121aa140f1daacf8bd1c2a2e', replace($b$على المحامي عند انتهاء توكيله لأي سبب من الأسباب أن يقدم بياناً إلى موكله بما يكون قد تم دفعه أو تحصيله ناشئاً عن الدعوى أو العمل الموكل إليه بمناسبتهما وأن يرد إلى الموكل جميع ما سلمه إليه من أوراق أو مستندات مالم يكن قد تم إيداعها في الدعوى وأن يوافيه بصور المذكرات والإعلانات التي تلقاها باسمه.
ولا يلتزم المحامي بأن يسلم موكله مسودات الأوراق التي حررها في الدعوى أو العمل الذي قام به ولا الكتب الواردة إليه.
ومع ذلك يجب على المحامي أن يعطي موكله صوراً من هذه الأوراق بناء على طلب الموكل وعلى نفقته.$b$, E'\n', E'\r\n')),
    (90, 0, ARRAY['0c5cbb3278e385e11128ff27606d9e1e']::text[], ARRAY['ee7da1e7ecaa4105588efa2327766acb']::text[], '0f021354b053b5afeab366adbc515afe', replace($b$عند وجود اتفاق كتابي على الأتعاب يحق للمحامي حبس الأوراق والمستندات المتعلقة بموكله أو حبس المبالغ المحصلة لحسابه بما يعادل مطلوبه من الأتعاب التي لم يتم سدادها له وفق الإتفاق.
وإذا لم يكن هناك اتفاق كتابي على الأتعاب، كان للمحامي أن يستخرج صوراً من هذه الأوراق والمستندات التي تصلح سنداً له في المطالبة، وذلك على نفقة موكله.
ويلتزم برد الصور الأصلية لهذه الأوراق متى استوفى من موكله مصروفات استخراجها.
وفي جميع الأحوال يجب أن يراعى ألا يترتب على حبس الأوراق والمستندات تفويت أي ميعاد محدد لاتخاذ إجراء قانوني يترتب على عدم مراعاته سقوط الحق فيه.$b$, E'\n', E'\r\n')),
    (91, 0, ARRAY['f82cffaf1adfc7544b4a788a0cefed46']::text[], ARRAY['05b2b2d1c4c5fc56427007b84420c1c5']::text[], '02dbd9edf9f9e7cf35565eed9933d07a', replace($b$يسقط حق الموكل في مطالبة محاميه برد الأوراق والمستندات والحقوق المترتبة على عقد الوكالة بمضي خمس سنوات من تاريخ انتهاء وكالته، وتنقطع هذه المدة بالمطالبة بها بكتاب موصى عليه.$b$, E'\n', E'\r\n')),
    (92, 0, ARRAY['e0471bddda2e76c8b1f562f799f10fef']::text[], ARRAY['9eb20a534ab3c26e47307cf586a0e614']::text[], '9c2dce48f2bc8ab59ff32a6d5f78e920', replace($b$لا يجوز للمحامي أن يتنازل عن التوكيل في وقت غير لائق.
ويجب عليه أن يخطر موكله بكتاب موصى عليه بتنازله عن التوكيل وأن يستمر في إجراءات الدعوى شهراً على الأقل متى كان ذلك لازماً للدفاع عن مصالح الموكل.
ويتعين على المحكمة تأجيل الدعوى المدة الكافية لتوكيل محام آخر.$b$, E'\n', E'\r\n')),
    (93, 0, ARRAY['a4e155243f38ac5e33c9c7d432e07546']::text[], ARRAY['5e400ed6e43c9e50ce93b949a03144a3']::text[], '0597b3bbc562078278b5f40704383ec8', replace($b$تقوم مجالس النقابات الفرعية بتشكيل مكاتب تابعة لها لتقديم المساعدات القضائية لغير القادرين من المواطنين في دائرة اختصاص كل منها.
وتشمل هذه المساعدات القضائية رفع الدعاوى والحضور فيها وفي تحقيقات النيابة العامة وإعطاء المشورة القانونية وصياغة العقود.
ويصدر مجلس النقابة العامة نظاماً لمكاتب المساعدات القضائية يبين كيفية ترتيب المحامين بهذه المكاتب والمكافآت التي تدفع لهم وشروط انتفاع المواطنين بخدماتها.$b$, E'\n', E'\r\n')),
    (94, 0, ARRAY['2e6e39117e5b363a7360f3794e63aa4f']::text[], ARRAY['23b6ce8f8a951e0b8cbfb3183a84b421']::text[], 'd8e7989d37023cdccac69816ddc04500', replace($b$مع عدم الإخلال بحكم المادة السابقة يندب مجلس النقابة الفرعية محامياً للحضور عن المواطن الذي يتقرر إعفاؤه من الرسوم القضائية لإعساره.
ويقوم المحامي المنتدب بالدفاع عنه أمام القضاء بغير اقتضاء أي أتعاب منه.$b$, E'\n', E'\r\n')),
    (95, 0, ARRAY['ad5473a594f261897571b57570158c5c']::text[], ARRAY['219b760e38d2f170a4d7b0457b4952e7']::text[], 'ee07e1f962b9ddfcabc8d4d852269c73', replace($b$إذا رفض عدة محامين قبول الوكالة في دعوى من الدعاوى التي يتطلب القانون اتخاذ الإجراء القانوني فيها عن طريق مكتب محام، يندب مجلس النقابة الفرعية بناء على طلب صاحب الشأن محامياً لاتخاذ الإجراء القانوني والحضور والمرافعة، ويحدد مجلس النقابة أتعابه بموافقة صاحب الشأن.$b$, E'\n', E'\r\n')),
    (96, 0, ARRAY['a4470206d0414de776b19dc95b4d4d50']::text[], ARRAY['541b23c5d625130f252f4ab3e6c2b448']::text[], 'd85d683d343984b2834123074a534b4a', replace($b$في حالة وفاة المحامي أو استبعاد اسمه أو محوه من الجدول أو تقييد حريته وبصورة عامة في جميع الأحوال التي يستحيل فيها عليه ممارسة المحاماة ومتابعة أعمال ودعاوى موكليه، يندب مجلس النقابة الفرعية محامياً من نفس درجة القيد على الأقل ما لم يختر المحامي أو ورثته محامياً آخر تكون مهمته اتخاذ الإجراءات الكفيلة بالمحافظة على مصالح الموكلين وتصفية المكتب إذا كان لذلك مقتضى،
وتتم هذه التصفية بموافقة ذوي الشأن وتحت إشراف مجلس النقابة الفرعية.$b$, E'\n', E'\r\n')),
    (97, 0, ARRAY['1e90876c5e0714f53801397ad0146d71']::text[], ARRAY['2ac3a545152f948a2b6510c8bb1cbf7a']::text[], 'cea55a5d44170324ae7902b6af33f34e', replace($b$يكون ندب المحامين في الحالات السابقة بالدور من الكشوف السنوية التي تعدها النقابة الفرعية لهذا الغرض من بين المحامين المقيدين أمام محاكم الاستئناف أو المحاكم الابتدائية الذين يزاولون المهنة استقلالًا وبقرار من مجلسها.
وفي حالة الاستعجال يصدر القرار من نقيب النقابة الفرعية، ويجوز لمجلس النقابة الفرعية وحده الاستثناء من الدور نظراً لطبيعة الدعوى أو بناء على طلب المحامي الذي يتولى إجراءات إعفاء موكله المعسر من الرسوم.
ويجب على المحامي المنتدب أن يقوم بما يكلف به، ولا يسوغ له أن يتنحى إلا لأسباب تقبلها الجهة التي تندبه.$b$, E'\n', E'\r\n')),
    (98, 0, ARRAY['d1cafafe8d2b245a765aac1c3033266b']::text[], ARRAY['6581599beca8be7734f0a36bdef92525']::text[], 'e6e010fd15c94bb6322fc5ddb85527a7', replace($b$كل محامي خالف أحكام هذا القانون أو النظام الداخلي للنقابة أو يخل بواجبات مهنته أو يقوم بعمل ينال من شرف المهنة أو يتصرف تصرفاً شائناً يحط من قدر المهنة يجازى بإحدى العقوبات التأديبية التالية:
1 الإنذار.
2 اللوم.
3 المنع من مزاولة المهنة.
4 محو الاسم نهائياً من الجدول.
ويجب ألا تتجاوز عقوبة المنع من مزاولة المهنة ثلاث سنوات ولا يترتب على محو الاسم نهائياً من الجدول المساس بالمعاش المستحق.$b$, E'\n', E'\r\n')),
    (99, 0, ARRAY['77cd96a3f5937167dd907bc5d26d4d97']::text[], ARRAY['54c4b44e41d4c14f9d33805c3d41fa3b']::text[], '85e3cdc46d99571709fd39c29c9134d1', replace($b$يجوز لهيئة مكتب النقابة العامة لفت نظر المحامى أو توقيع عقوبة الإنذار عليه.
كما يجوز لها أن تأمر بوقف المحامى الذى أقيمت ضده الدعوى التأديبية عن مزاولة المهنة احتياطيا، إلى أن يفصل فى هذه الدعوى وذلك بعد سماع أقواله، ويجوز للمحامى التظلم لمجلس النقابة خلال ثلاثين يوما، ولمجلس النقابة إما إلغاء القرار أو عرض الأمر على الدائرة المختصة بالتأديب للفصل فى القرار والموضوع.
ويعرض هذا الأمر على مجلس التأديب المنصوص عليه فى المادة 107 من هذا القانون خلال الثلاثين يوما التالية لتاريخ صدوره ويقرر المجلس خلال عشرة أيام من تاريخ عرض الأمر عليه بعد سماع أقوال المحامى إما الاستمرار فى منعه من مزاولة المهنة احتياطيا أو السماح له بالاستمرار فى مزاولتها إلى أن يفصل فى الدعوى التأديبية المرفوعة عليه.
وعلى مجلس النقابة الفرعية أن يندب محاميا أخر لمباشرة قضايا المحامى الموقوف طوال فترة وقفه.$b$, E'\n', E'\r\n')),
    (100, 0, ARRAY['1435e5c9c05613ef641c78df71fc8018']::text[], ARRAY['b61d8198157771e88e071afbba1cede4']::text[], 'f068fd4dd9cbd61e8a54cb76a315bcac', replace($b$يترتب على منع المحامي من مزاولة المهنة نقل اسمه إلى جدول المحامين غير المشتغلين.
ولا يجوز للمحامي الممنوع من مزاولة المهنة فتح مكتبه طوال مدة المنع.
ويحرم من جميع الحقوق الممنوحة للمحامين.
ومع ذلك يبقى خاضعاً لأحكام هذا القانون.
ولا تدخل فترة المنع في حساب مدة التمرين ومدة التقاعد والمدد اللازمة للقيد بجدول النقابة والترشيح لمجلس النقابة.
وإذا زاول المحامي مهنته في فترة المنع يعاقب تأديباً بمحو اسمه نهائياً من الجدول.$b$, E'\n', E'\r\n')),
    (101, 0, ARRAY['898d0f59043c5ae79e48575189d1e9a8']::text[], ARRAY['465f6d584124131092777d769a18ef83']::text[], '89588e641fb5e020b37cded548a07da9', replace($b$لا يحول اعتزال المحامي أو منعه من مزاولة المحاماة دون محاكمته تأديبياً عن أعمال ارتكبها خلال مزاولته مهنته وذلك لمدة السنوات الثلاث التالية للاعتزال أو المنع.$b$, E'\n', E'\r\n')),
    (102, 0, ARRAY['271aec0c4fee20071793f1f0a99d4671']::text[], ARRAY['002eb7dc62550bd5dbc6c2aa30c69657']::text[], 'e88d27b888a841d0810ed011316cdbbb', replace($b$ترفع النيابة الدعوى التأديبية من تلقاء نفسها أو متى طلب ذلك مجلس النقابة أو رئيس محكمة النقض أو رئيس المحكمة الإدارية العليا أو رئيس محكمة استئناف أو رئيس محكمة القضاء الإداري أو رئيس محكمة ابتدائية أو رئيس محكمة إدارية.$b$, E'\n', E'\r\n')),
    (103, 0, ARRAY['8d3347d794b06ef04c5a384fe5ebd5f8']::text[], ARRAY['af063695966ed522a0210c4156d043db']::text[], '12b13fd0a306a77ecb3ccf12e4695929', replace($b$تسرى أحكام قانون السلطة القضائية بشأن رجال القضاء على جميع إجراءات التحقيق أو رفع الدعوى العمومية أو التأديبية على النقيب العام للمحامين.$b$, E'\n', E'\r\n')),
    (104, 0, ARRAY['0be238724e0b4ec7e20c55e748ce7c3b']::text[], ARRAY['8afb17d5462347be57c8473dfa27b6c8']::text[], '476e0462e4d26d468825001dd667aaf9', replace($b$إذا لم تكن الوقائع المسندة إلى المحامي من الجسامة بحيث تستدعي المحاكمة الجنائية أو التأديبية، جاز للنيابة أن ترسل لمجلس النقابة التحقيق الذي أجرته ليتخذ ما يراه في هذا الشأن.$b$, E'\n', E'\r\n')),
    (105, 0, ARRAY['2ad107418b4c76142a0bf7fde94a4922']::text[], ARRAY['764caf66c0cac2db6c0d67ede32e7c38']::text[], '0111076b3d00cc64c6caec65325e27d2', replace($b$يشكل مجلس النقابة الفرعية سنويا لجنة أو أكثر من بين أعضائه لتحقيق الشكاوى التى تقدم ضد المحامين أو تحال إلى المجلس من النقابة فإذا رأت اللجنة فيها ما يستوجب المؤاخذة، وقعت عقوبة الإنذار أو أحالت الأمر إلى مجلس النقابة العامة إذا رأت توقيع عقوبة أشد وإلا حفظت الشكوى، على أن يتم ذلك خلال ثلاثة أشهر على الأكثر ولكل من الشاكى والمشكو فى حقه أن يتظلم من هذا القرار خلال خمسة عشرة يوما إلى النقابة العامة.$b$, E'\n', E'\r\n')),
    (106, 0, ARRAY['7a719dc09ad3a32fa1d8e35100f36ca8']::text[], ARRAY['bfa9c9d10cf21526f705d7b7375538ba']::text[], '0e26cd8086ff2b7a80e80733f04a33dc', replace($b$على كل محكمة جنائية تصدر حكما متضمنا معاقبة محام أن ترسل إلى نقابة المحامين نسخة من الحكم.$b$, E'\n', E'\r\n')),
    (107, 0, ARRAY['62ee4f8ef85b2bc3edfe0db0de7b5ac3']::text[], ARRAY['6f915daa7bd2cec9e09e544a63e78853']::text[], 'bbbd0c070bde7f70a043509dd5572d5c', replace($b$يكون تأديب المحامين من اختصاص مجلس يشكل من رئيس محكمة استئناف القاهرة أو من ينوب عنه ومن اثنين من مستشارى المحكمة المذكورة تعينهما جمعيتها العمومية كل سنة ومن عضوين من أعضاء مجلس النقابة يختار أحدهما المحامى المرفوعة عليه الدعوى التأديبية ويختار الآخر مجلس النقابة.$b$, E'\n', E'\r\n')),
    (108, 0, ARRAY['378112604415f9c3f25fa049f6453bb2']::text[], ARRAY['7ba8080a5282629d77fcf4f63fc4b1f9']::text[], '28d35463c73dec574d326b1e87cf695e', replace($b$يعلن المحامى بالحضور أمام مجلس التأديب بكتاب موصى عليه بعلم وصول على أن يصله قبل الجلسة بخمسة عشر يوما كاملة.
ويجب أن يبلغ المحامى رئيس المجلس اسم عضو النقابة الذى يختاره قبل الجلسة بسبعة أيام فان لم يفعل اختار مجلس النقابة عضوا آخر.$b$, E'\n', E'\r\n')),
    (109, 0, ARRAY['5944a94476c0874d27ead7a913edfda3']::text[], ARRAY['1d2ed4e6238b11fca027a1ee481a1015']::text[], '097d14b7ec6ab10bad34716ff8a4be47', replace($b$يجوز للمحامى أن يوكل محاميا للدفاع عنه من بين المحامين المقبولين للمرافعة أمام محكمة النقض والمحكمة الإدارية العليا أو محاكم الاستئناف ومحكمة القضاء الإدارى.
ولمجلس التأديب أن يأمر بحضوره شخصيا أمامه.$b$, E'\n', E'\r\n')),
    (110, 0, ARRAY['7a5a56ee5d6b0d3acc81dba28b1d3789']::text[], ARRAY['3f20f3c26d6c90bef0e34a33ca31c68b']::text[], 'f28ab2165bf0354955be1df9db7b9db1', replace($b$يجوز لمجلس التأديب وللنيابة وللمحامى أن يكلفوا بالحضور الشهود الذين يرون فائدة من سماع شهادتهم فإذا تخلف أحد من الشهود عن الحضور أو حضر وامتنع عن أداء الشهادة جاز للمجلس معاقبته بالعقوبات المقررة فى قانون الإجراءات الجنائية فى مواد الجنح، ويعاقب على شهادة الزور أمام مجلس التأديب بعقوبات شهادة الزور فى مواد الجنح.$b$, E'\n', E'\r\n')),
    (111, 0, ARRAY['adc4d33e52c68f76c3ff64098919fd20']::text[], ARRAY['53bd8aac1a8a53a16f69b317245b58c8']::text[], 'b88db84aa1592c84e7d79199c848488d', replace($b$تكون جلسات التأديب دائما سرية ويصدر القرار بعد سماع أقوال الاتهام وطلباته ودفاع المحامى أو من يوكله للدفاع عنه.$b$, E'\n', E'\r\n')),
    (112, 0, ARRAY['e9d5a746d92cf178062781fa8dde2081']::text[], ARRAY['dac8fc01d56b2253108624610e450a69']::text[], '6c1e5b997be993e441630158757ae2ba', replace($b$يجب أن يكون قرار مجلس التأديب مسببا وأن تتلى أسبابه كاملة عند النطق به فى جلسة سرية.$b$, E'\n', E'\r\n')),
    (113, 0, ARRAY['eb3dabac03400be0c54c1f6a1c15ac0b']::text[], ARRAY['24b373b6aba9bf4050f8ddb4a7404afc']::text[], 'ce6da8934a7b49beda8a58b214ba262e', replace($b$تعلن القرارات التأديبية فى جميع الأحوال على يد محضر إلى ذوى الشأن والنيابة العامة ويقوم مقام هذا الإعلان تسليم صورة القرار إلى المحامى صاحب الشأن بإيصال.$b$, E'\n', E'\r\n')),
    (114, 0, ARRAY['c0db396b3e45334c63243198c48db491']::text[], ARRAY['2cf0d28b21e2c6334b62ade649a928ba']::text[], '6cb9424b4d19ca0c82b32df2f38e8c0a', replace($b$يجوز للمحامى أن يعارض فى القرارات التى تصدر فى غيبته خلال عشرة أيام من تاريخ إعلانه أو استلامه صورة منها.$b$, E'\n', E'\r\n')),
    (115, 0, ARRAY['8734176d9d3f1d9582cec829cc03c49c']::text[], ARRAY['cd3bc1e6dc39056d5c326149a2742fd3']::text[], '5d1905fffce65df8ffa377aa5c64e83d', replace($b$تكون المعارضة بتقرير من المحامى المعارض أو الوكيل عنه بقلم كتاب محكمة استئناف القاهرة،
أما الطعن فى القرار فيكون بتقرير بقلم كتاب محكمة النقض.$b$, E'\n', E'\r\n')),
    (116, 0, ARRAY['91981fb01f64a0348b56460cf72a673e']::text[], ARRAY['90c2b58fb9380bfbcc4749355a51c3f4']::text[], '27650143d3f6e623d08341825f3fccba', replace($b$للنيابة العامة وللمحامى المحكوم عليه حق الطعن فى القرارات الصادرة من مجلس التأديب المنصوص عليه فى المادة (107) وذلك خلال خمسة عشر يوما بالنسبة إلى النيابة من تاريخ صدور القرار وبالنسبة إلى المحامى من تاريخ إعلانه بالقرار أو تسلمه صورته.
ويفصل فى هذا الطعن مجلس يؤلف من أربعة من مستشارى محكمة النقض تعينهم جمعيتها العمومية كل سنة ومن النقيب أو وكيل النقابة وعضوين من مجلس النقابة.
وللمحامى الذى رفعت عليه الدعوى التأديبية أن يختار أحد هذين العضوين.
ولا يجوز أن يشترك فى المجلس أحد أعضاء مجلس التأديب الذى أصدر القرار المطعون عليه.
والقرار الذى يصدر يكون نهائيا.$b$, E'\n', E'\r\n')),
    (117, 0, ARRAY['fbecad4d11361d637dfb00d75960420e']::text[], ARRAY['151365960a07a80dddc38062ecce79b6']::text[], 'c6976d7a2fe3d6cae2d12b740bc3d0c5', replace($b$إذا حصل من محى اسمه من جدول المحامين على أدلة جديدة تثبت براءته جاز له بعد موافقة مجلس النقابة أن يطعن فى القرار الصادر بمحو اسمه بطريق التماس إعادة النظر أمام مجلس تأديب المحامين بمحكمة النقض، فإذا رفض المجلس طلبه جاز له تجديده بعد مضى خمس سنوات ويشترط أن يقدم أدلة غير الأدلة السابق تقديمها.
ولا يجوز تجديد الطلب أكثر من مرة.
ويرفع الالتماس بعريضة تقدم إلى المجلس ويكون القرار الذى يصدر برفضه نهائيا.$b$, E'\n', E'\r\n')),
    (118, 0, ARRAY['702e44e9619f874209483878e6060b14']::text[], ARRAY['b081c51cb5cb6cfe88e11f85a52ee1bf']::text[], '2b5b4a7cdd02f761c7324b5a6630a29d', replace($b$لمن صدر ضده قرار تأديبى بمحو اسمه من جدول المحامين أن يطلب بعد مضى سبع سنوات كاملة على الأقل، من لجنة قبول المحامين المنصوص عليها فى المادة (16) من هذا القانون قيد اسمه فى الجدول فإذا رأت اللجنة أن المدة التى مضت من وقت صدور القرار بمحو اسمه كافية لإصلاح شأنه وإزالة أثر ما وقع منه أمرت بقيد اسمه بالجدول وحسبت أقدميته من تاريخ هذا القرار.
وللجنة أن تسمع أقوال الطالب وتصدر قرارها بعد أخذ رأى مجلس النقابة فإذا قضت برفض طلبه جاز له تجديده بعد مضى خمس سنوات.
ولا يجوز تجديد الطلب أكثر من مرة.
والقرار الذى يصدر برفض الطلب يكون نهائيا.$b$, E'\n', E'\r\n')),
    (119, 0, ARRAY['5b340ccebc4942b2ce75371ebf571f80']::text[], ARRAY['20e5b6180ac38d3ae89358557645fa50']::text[], '7a572ec40098588a12bf9586cc9db92f', replace($b$تسجل فى سجل خاص بالنقابة القرارات التأديبية النهائية الصادرة ضد المحامى ويشار إليها فى الملف الخاص به.
وتخطر به النقابات الفرعية وأقلام كتاب المحاكم والنيابات، وتنشر القرارات النهائية بمجلة المحاماة، دون ذكر أسماء من تناولتهم القرارات.
وإذا كان القرار صادرا بمحو الاسم من الجدول أو المنع من مزاول المهنة فينشر منطوقه دون الأسباب فى الوقائع المصرية.
ويتولى مجلس النقابة الفرعية تنفيذ القرارات التأديبية على أن تعاونه النيابة العامة متى طلب منها ذلك.$b$, E'\n', E'\r\n')),
    (120, 0, ARRAY['fe42f9e2840374c15b319e43ba101021']::text[], ARRAY['c7b4eb2e1d8713e80bf21fb162b08c2d']::text[], 'c7dc57f02676a304f58777bf42f74264', replace($b$نقابة المحامين مؤسسة مهنية مستقلة تضم المحامين فى جمهورية مصر العربية المقيدين بجداولها، وتتمتع بالشخصية الاعتبارية، ومقرها مدينة القاهرة وتتبعها نقابات فرعية على النحو الذى ينظمه هذا القانون.$b$, E'\n', E'\r\n')),
    (121, 0, ARRAY['23f330c2d8a4f67843e0e1554bf13ca1']::text[], ARRAY['3b89f10d17bea8cd5325c13259e0667b']::text[], '3b381bd575b497243c9037ecfd2a700f', replace($b$تعمل النقابة على تحقيق الأهداف الآتية ( وفق أحكام هذا القانون):
(أ) تنظيم ممارسة مهنة المحاماة وضمان حسن أدائها.
(ب) كفالة حق الدفاع للمواطنين وتقديم المساعدات القضائية لغير القادرين منهم.
(ج) العناية بمصالح أعضائها وتزكية روح التعاون بينهم وضمان استقلالهم فى أداء رسالتهم.
(د) تشجيع البحوث القانونية ودراسات الشريعة الإسلامية.
(ه) التعاون مع النقابات المهنية والمنظمات المماثلة فى الدولة العربية والدول الإفريقية وغيرها للعمل على خدمة الأهداف القومية للأمة العربية ونصرة قضايا الحرية والسلام والتقدم.$b$, E'\n', E'\r\n')),
    (122, 0, ARRAY['7c4d2931c28a7748655fa1e92ec56be0']::text[], ARRAY['28c24925171e9aa4b38b0f5362f0523b']::text[], 'b9d6b43db2f43519ad1f4ddbfe78481c', replace($b$للنقابة فى سبيل تحقيق أهدافها المبينة بالمادة السابقة التعاون مع النقابات المهنية الأخرى والجمعيات القانونية العلمية والمنظمات المماثلة فى الدول العربية واتحاداتها تحقيقا للأهداف القومية للأمة العربية فى أن يكون القانون فى خدمة قضايا الحرية وأداة لمناهضة الاستعمار والعنصرية بجميع إشكالها.
وللنقابة أيضا التعاون مع اتحادات المحامين ومنظماتها الدولية لتبادل الخبرات حول نظم القضاء والمحاماه والارتقاء بمستوى المهنة وتأكيد رسالتها فى الدفاع عن حقوق الإنسان.$b$, E'\n', E'\r\n')),
    (123, 0, ARRAY['7b82c3ed635442d4548d4855314e29e9']::text[], ARRAY['5bf4a7147e58010384e50cd63749e284']::text[], 'a4ecc19d7557d05c74e91548c10ec4f4', replace($b$تمارس النقابة العامة نشاطها عن طريق الأجهزة الآتية:
(أ) الجمعية العمومية.
(ب) مجلس النقابة.$b$, E'\n', E'\r\n')),
    (124, 0, ARRAY['61f14cda082e69a4d43c83e8ff03efff']::text[], ARRAY['9077ea5b80e872b3a19b92f3ccf98aa1']::text[], 'b74e0cd2c414808fa1912010e7cf505f', replace($b$تتكون الجمعية العمومية للنقابة العامة سنويا من المحامين المقبولين أمام محكمة النقض ومحاكم الاستئناف والمحاكم الابتدائية الذين سددوا رسوم الاشتراك المستحقة عليهم أو أعفوا منها حتى أخر السنة السابقة على موعد انعقاد الجمعية العمومية وقبل اجتماعها بشهر على الأقل.
وتنعقد الجمعية العمومية سنويا فى شهر يونيه فى مقر نقابة المحامين بالقاهرة ولا يكون اجتماعها صحيحا إلا إذا حضره ثلث الأعضاء على الأقل أو ثلاثة آلاف عضو أيهما أقل، فإذا لم يتوافر هذا العدد أجل الاجتماع أسبوعين ويكون الاجتماع الثانى صحيحا إذا حضره ألف وخمسمائة عضو من أعضائها على الأقل فإذا لم يكتمل العدد فى هذا الاجتماع أعيدت الدعوى لاجتماع يعقد خلال أسبوعين وتكرر الدعوى حتى يكتمل العدد المطلوب.
وفى جميع الأحوال يجوز لمجلس النقابة تأجيل انعقاد الجمعية العمومية إلى ما بعد انتهاء العطلة القضائية.$b$, E'\n', E'\r\n')),
    (125, 0, ARRAY['2908f4ce5a27a6b968e5c5642abd1f2c']::text[], ARRAY['588b53abad8587a5da216b0e81dde570']::text[], '44e8a0da5bf2236c1ae0d88fde4bc47b', replace($b$يرأس النقيب اجتماع الجمعية العمومية وفى حالة غيابه ينوب عنه أقدم الوكيلين ممن يزاول المهنة مستقلا وفى حالة غيابه ينوب عنه الوكيل الآخر.
ويعلن رئيس الجمعية افتتاح اجتماعها بعد التحقق من توافر النصاب اللازم لانعقادها.
كما يعلن فض الاجتماع، ويتولى أمين عام النقابة أمانة الاجتماع وعند غيابه يختار رئيس الجمعية أمينا للاجتماع.
وتختار الجمعية العمومية اثنين من بين أعضائها فارزى الأصوات.$b$, E'\n', E'\r\n')),
    (126, 0, ARRAY['bef813c15f6e0572699bdc9f9f00ef67']::text[], ARRAY['2263e2f5892503a990691bafa3b3a1c0']::text[], 'ad99d2da195d56ead6fb87613e164bac', replace($b$علاوة على ما ورد بشأنه نص خاص فى هذا القانون تختص الجمعية العمومية فى اجتماعها السنوى بما يأتى:
(1) النظر فى تقرير مجلس النقابة ومراقبى الحسابات عن الحساب الختامى للنقابة عن السنة المنتهية وإقرار الميزانية التقديرية عن السنة المقبلة.
(2) تعديل رسوم القيد والإشتراك ورسوم الدمغة التى يؤديها المحامون لصالح النقابة بناء على اقتراح مجلس النقابة.
(3) تعديل مقدار المعاش المقرر للمحامين والمستحقين عنهم وتعديل قواعد استحقاق المعاش بناء على اقتراح مجلس النقابة، ووفقا لتقرير خبيرين اكتواريين يختارهما مجلس النقابة.$b$, E'\n', E'\r\n')),
    (127, 0, ARRAY['ad97c32d43c008ada70f713d5e089839']::text[], ARRAY['503e039eb6ff6e03dbed5bff6c03216d']::text[], 'cceab53f7df7ba83ebb532c41babfbb2', replace($b$لا يجوز للجمعية العمومية أن تنظر فى غير المسائل الواردة فى جدول الأعمال ومع ذلك يجوز لمجلس النقابة أن يعرض لنظر المسائل العاجلة التى طرأت بعد توجيه الدعوى وتمت دراستها.$b$, E'\n', E'\r\n')),
    (128, 0, ARRAY['853ce5eaa70f3fd7b29530cfd06fe845']::text[], ARRAY['0ff20dcff2d364a59a1b298c4945e004']::text[], '8bddd0c961e555917e2df9806660f647', replace($b$للجمعية العمومية أن تعقد اجتماعات غير عادية بناء على دعوة مجلس النقابة العامة، أو بناء على طلب كتابى يقدم إلى النقيب من عدد لا يقل عن خمس نقابات فرعية، أو ألفى عضو من أعضاء جمعية الانتخاب يكون مصدقًا على توقيعاتهم من النقابة الفرعية المختصة أو مصلحة الشهر العقارى، ويجب أن يبين فى الطلب أسبابه وجدول الأعمال المقترح، ويتولى النقيب توجيه الدعوة للاجتماع خلال ثلاثين يوما على الأكثر من تاريخ الطلب.
وإذا لم يوجه النقيب الدعوة خلال المدة المذكورة، اجتمعت الجمعية العمومية غير العادية بقوة القانون فى اليوم التالى لانتهاء تلك المدة.$b$, E'\n', E'\r\n')),
    (129, 0, ARRAY['e4d95c2935f759ebefecaa3cd8bb1e1d']::text[], ARRAY['e3b934760f03907f1858eb3bee4208ac']::text[], '0e62602958ff674c4ece3bb1533e61a1', replace($b$إذا كان طلب عقد الجمعية العمومية غير العادية لسحب الثقة من النقيب أو عضو أو أكثر من أعضاء مجلس النقابة، فيشترط لصحة طلب انعقادها توقيع عدد لا يقل عن خمس عدد الأصوات الحاصل عليها النقيب أو العضو المطلوب سحب الثقة منه مصدقًا على توقيعاتهم من النقابة الفرعية المختصة وموضحا فيه أسباب الطلب وأسانيده ومستنداته، ويجب لانعقادها حضور عدد لا يقل عن عشر عدد أعضاء الجمعية العمومية، وتكون رئاستها فى هذه الحالة لأكبر الأعضاء سنا من غير أعضاء مجلس النقابة.
وفى حالة عدم اكتمال نصاب انعقادها يعتبر الطلب كأن لم يكن.
ولا يجوز تقديم هذا الطلب قبل مرور عام من تاريخ تشكيل مجلس النقابة العامة إلا إذا كانت أسباب سحب الثقة تشكل جريمة جنائية، كما لا يجوز إعادة تقديم الطلب لذات الأسباب التى رفضتها الجمعية العامة صراحة أو ضمنا قبل مرور عام على تقديم الطلب المشار إليه.$b$, E'\n', E'\r\n')),
    (130, 0, ARRAY['5d18bcaaed4bf186f9a5381fb0c5316a']::text[], ARRAY['ccb00be31e700de910b4f59c85206fbc']::text[], '32226f4cb6a0e325d647736383a36d9b', replace($b$تصدر قرارات الجمعية العمومية بالأغلبية المطلقة لأصوات الحاضرين.
فإذا تساوت الأصوات يرجح الجانب الذى فيه رئيس الجمعية، ويحرر محضر بنتيجة الاجتماع يثبت فى دفتر خاص ويوقع عليه من رئيس الجمعية والأمين العام وفارزى الأصوات.
ويبين النظام الداخلى للنقابة إجراءات دعوة الجمعية العمومية وانعقادها وكيفية سير العمل فيها.$b$, E'\n', E'\r\n')),
    (131, 0, ARRAY['c7905a91b758130af2d59b18b8abbfce']::text[], ARRAY['1ae017151216df4d8cc319103d1a83a6']::text[], '845a40fb1eabb2caa43f12c7c6ba734b', replace($b$يشكل مجلس النقابة العامة من:
1- نقيب المحامين.
2- ثمانية وعشرين عضوا.
ويراعى فى انتخابهم الآتى:
أولا - أن يكون نصف عدد الأعضاء على الأقل من المحامين المقبولين للمرافعة أمام محكمة النقض أو محاكم الاستئناف.
ثانيا - أن يمثل المحامون فى دائرة كل محكمة استئناف بعضو واحد.
ثالثًا - أن يمثل المحامون بالهيئات العامة والوحدات الاقتصادية وشركات قطاع الأعمال بثلاثة أعضاء.
ولا يجوز الجمع بين الترشح لمنصب النقيب والترشح لعضوية مجلس النقابة، كما لا يجوز الترشح لتمثيل أكثر من فئة من الفئات المذكورة فى هذه المادة.
ويتم انتخاب النقيب وجميع أعضاء النقابة من الجمعية العمومية للنقابة.$b$, E'\n', E'\r\n')),
    (132, 0, ARRAY['025e7ffc4c2e070b2a437b8d65e59f99']::text[], ARRAY['340eea85cde4c7837cc4058370d8a143']::text[], '1c0f237953a34084474c7a64473b6f9f', replace($b$يشترط فيمن يرشح نفسه نقيبا أن يكون من المحامين أصحاب المكاتب الخاصة والمقيدين أمام محكمة النقض والذين أمضوا فى الاشتغال الفعلى بالمهنة أكثر من عشرين سنة متصلة بالإضافة إلى الشروط العامة للترشيح لعضوية مجلس النقابة.$b$, E'\n', E'\r\n')),
    (133, 0, ARRAY['a4ae60d07335ad0844f290ad47314e7b']::text[], ARRAY['05c237c4312d45cf7668f56c289cf9b5']::text[], 'c48c66b3a6952ec6315dc7469f80a753', replace($b$يشترط فيمن يرشح نفسه لعضوية مجلس النقابة:
(1) أن يكون من أعضاء الجمعية العمومية الذين مضى على مزاولتهم المهنة سبع سنوات متصلة لا تدخل فيها مدة الأعمال النظيرة للمحاماة.
(2) أن يكون مسددا لرسوم الاشتراك المستحقة عليه حتى قفل باب الترشيح.
(3) ألا يكون قد صدر ضده خلال الثلاث سنوات السابقة على ذلك أحكام أو قرارات تأديبية تجاوز عقوبة الإنذار.$b$, E'\n', E'\r\n')),
    (134, 0, ARRAY['f0cb8f3febaff0924ce35bf2638badeb']::text[], ARRAY['51c51c4ae564874caf7df02212184f5c']::text[], '68ad0ffb91eac9edbcd5ce51630a2a30', replace($b$يكون الترشيح لعضوية المجلس بطلب يقدم من المرشح إلى مجلس النقابة فى الميعاد الذى يحدده لقبول طلبات الترشيح على أن يكون قبل الموعد المحدد لإجراء الانتخابات بأربعين يوما على الأقل.
ويعد مجلس النقابة قائمة المرشحين خلال عشرة أيام على الأكثر من قفل باب الترشيح وتعلن على المحامين فى النقابات الفرعية.
ولمن أغفل إدراج اسمه بها أن يتظلم إلى مجلس النقابة أو أن يطعن فى قراره أمام محكمة استئناف القاهرة خلال عشرة أيام من تاريخ نشر كشوف المرشحين ويفصل فى الطعن على وجه الاستعجال.$b$, E'\n', E'\r\n')),
    (135, 0, ARRAY['98d7fd8d5216f21918a7c1fd1803a099']::text[], ARRAY['5d51de6907614c28d41df38af6eec8cd']::text[], '822f259cc82ff37ce285e32c2bce4fe1', replace($b$يجرى الانتخاب لاختيار النقيب وأعضاء مجلس النقابة العامة بدار النقابة وفى مقار النقابات الفرعية أو أندية المحامين وذلك وفقا للقواعد والإجراءات التى يحددها النظام الداخلى للنقابة.
ويكون الانتخاب بطريق الاقتراع السرى المباشر وبالأغلبية النسبية فإذا تساوت الأصوات بين أكثر من مرشح للعضوية يعلن نجاح الأقدم قيدا.
وتتولى الجمعية المذكورة بالمادة (124) اختيار النقيب والأعضاء الخمسة عشر المبين بالمادة (131).$b$, E'\n', E'\r\n')),
    (136, 0, ARRAY['49442360415c5d9a2bd04a6cb5e4a741']::text[], ARRAY['9d36a1b1e86d285a9d8efb615ee4a008']::text[], 'faf589d14039cdcf48df61faaab52557', replace($b$تكون مدة مجلس النقابة أربع سنوات من تاريخ إعلان نتيجة الانتخاب وتجرى لتجديد المجلس خلال الستين يوما السابقة على انتهاء مدته.$b$, E'\n', E'\r\n')),
    (137, 0, ARRAY['1f157c894f1b73729700951b7872edbf']::text[], ARRAY['08061b453e6a27b907d761ceb58dd2ed']::text[], '3f8879e3f9065660c0847caba2d44f49', replace($b$يعين مجلس النقابة من بين أعضائه كل سنتين هيئة المكتب المشكلة من وكيلين وأمين عام وأمين الصندوق ويتولى النقيب رئاسته.
ويشترط أن يكون النقيب وأحد الوكيلين على الأقل ممن يزاولون المهنة مستقلين.
ويجوز للمجلس أن يعين من بين أعضائه أمينا عاما مساعدا أو أمينا مساعدا للصندوق، ويكونون أعضاء بهيئة المكتب.
ويحدد النظام الداخلى للنقابة اختصاصات أعضاء المكتب وتوزيع الأعمال بين أعضاء المجلس وتشكيل لجانه واختصاصاتها.$b$, E'\n', E'\r\n')),
    (138, 0, ARRAY['16d34e3b77c9c4802437662843bab4f5']::text[], ARRAY['8d0fbd9b19709356616ea1a2190fa3a5']::text[], '64b234106f2745ec289a23bb9a55b1ad', replace($b$نقيب المحامين هو الذى يمثل المحامين ويتكلم باسمهم ويحافظ على كرامة النقابة وكرامة أعضائها ويراعى الالتزام بتقاليدها ويشرف بوجه عام على سير أعمال النقابة وفق أحكام هذا القانون وله أن يتخذ صفة المدعى أو أن يتدخل بنفسه أو بواسطة من ينيبه من المحامين فى كل دعوى تتعلق بكرامة النقابة أو أحد أعضائها.
ويرأس النقيب اجتماعات مجلس النقابة وفى حالة غيابه تكون الرئاسة لأقدم الوكيلين فى القيد بجدول المحامين بشرط أن يكون مزاولا مستقلا وفى حالة غيابهما تكون الرئاسة لأكبر أعضاء المجلس سنا.$b$, E'\n', E'\r\n')),
    (139, 0, ARRAY['d74510beecb13b30c5560875859da51c']::text[], ARRAY['6e0eb02e0ce37541c10b36de73793f94']::text[], '425b700102f7bf21afea511f95ea6214', replace($b$يعقد مجلس النقابة العامة اجتماعا دوريا كل خمسة عشر يوما على الأقل بناء على دعوة النقيب. ويكون اجتماعه صحيحا إذا حضره أكثر من نصف أعضائه.
وتصدر قراراته بأغلبية أصوات الحاضرين.
فإذا تساوت الأصوات يرجح الجانب الذى منه الرئيس.
ويجوز أن يعقد المجلس اجتماعات غير عادية بناء على دعوة من النقيب أو بناء على طلب عشرة على الأقل من أعضاء المجلس أو بناء على طلب مجالس خمس نقابات فرعية على الأقل، وذلك بكتاب يوجه إلى النقيب مرفقا به جدول الأعمال المقترح.$b$, E'\n', E'\r\n')),
    (140, 0, ARRAY['05d46e7524dc4fa85abeeb9be52b4cd2']::text[], ARRAY['cce8d2a3eb9f06c9c8c05018ad2487ea']::text[], 'c575fcacd067e010efba0fc7dd5916df', replace($b$تحرر محاضر لجلسات المجلس وتثبت فى دفتر خاص يوقع عليه من النقيب أو من يحل محله ومن أمين عام المجلس.
ويبين النظام الداخلى للنقابة إجراءات دعوة المجلس إلى الانعقاد وكيفية إعداد جدول أعماله ونظام العمل فيه.$b$, E'\n', E'\r\n')),
    (141, 0, ARRAY['fd585afa8fb4b8fdcc07a30b0a03b771']::text[], ARRAY['f36ffb79fe7f724c3509696c8a6aa641']::text[], '15f7be013a638b1d72c6d3afb41fe51c', replace($b$تسقط العضوية عن النقيب وعن أي عضو فى المجلس إذا فقد أى شرط من شروط صلاحية الترشيح المنصوص عليها فى هذا القانون.
ويصدر بذلك قرار من المجلس بأغلبية ثلثى أعضائه بعد سماع أقوال العضو إذا كان لذلك مقتضى. وللمجلس أن يقرر بنفس الأغلبية إسقاط عضوية من يتغيب عن جلساته أربع مرات متتالية أو ثمانى مرات منقطعة خلال السنة الواحدة بغير عذر يقبله المجلس على أن يخطر العضو لسماع أقواله قبل تقرير إسقاط العضوية.
وللجمعية العمومية للنقابة الفرعية أو لمجلس نقابتها أن يطلب من مجلس النقابة العامة إسقاط العضوية عن عضو المجلس المنتخب من النقابة الفرعية فى حالة الغياب المبين فى الفقرة السابقة.
وللعضو الذى أسقطت عضويته حق الطعن أمام الدائرة الجنائية لمحكمة النقض فى القرار الذى يصدر بإسقاط عضويته بتقرير يقدمه إلى محكمة النقض خلال أربعين يوما من تاريخ إخطاره بالقرار.$b$, E'\n', E'\r\n')),
    (142, 0, ARRAY['a735a785ad5f32ab531de071d41d512e']::text[], ARRAY['89ebbe578c2d5702bf3837da1e1045ea']::text[], 'be8d9e2707a36dcdd46590a5229f00c3', replace($b$إذا شغر مركز النقيب لأى سبب وكانت المدة الباقية له تقل عن سنة يقوم أقدم الوكيلين مقامه بشرط أن يكون ممن يزاول المهنة مستقلا، فإذا زادت المدة الباقية على سنة يتعين على مجلس النقابة الدعوة إلى انتخاب نقيب جديد يكمل المدة الباقية للنقيب الأصلى وذلك خلال ستين يوما من شغر مركز النقيب.
وإذا شغر مكان أحد أعضاء المجلس لأى سبب كان، عين المجلس بدلا منه للمدة الباقية من العضوية المرشح الحاصل على الأصوات التالية فى الانتخاب السابق مع مراعاة حكم المادة (131).
وإذا لم يوجد تعين على مجلس النقابة الدعوة إلى انتخاب عضو جديد يكمل المدة الباقية للعضو الأصلى، على أن يجرى الانتخاب خلال ستين يوما من تاريخ شغر المكان.$b$, E'\n', E'\r\n')),
    (143, 0, ARRAY['46b0a4e2e6b0f5df92eb89156bc4cb39']::text[], ARRAY['7c6d8b906a9f2e7667c2c2f115c56a24']::text[], '1a86b298abd758edff6f6eb6ad151dc1', replace($b$يكون لمجلس النقابة العامة جميع الصلاحيات اللازمة فى كل ما يتعلق بإدارة شئون النقابة وتحقيق أهدافها، ويكون له بالإضافة للاختصاصات الأخرى المقررة فى هذا القانون الآتى:
1- وضع الضوابط التى تضمن الاشتغال الفعلى بالمحاماة، وربط تجديد الاشتراك السنوى وأداء الخدمة النقابية بالاشتغال الفعلى داخل مصر وخارجها، وتحديث ومراجعة جداول النقابة بشكل دورى.
2- قبول العضوية فى اتحادات المحامين الدولية والإقليمية، أو الانسحاب منها.
3- إصدار مجلة المحاماة، والإشراف على تحريرها.
4- وضع النظام الداخلى للنقابة واللوائح والقواعد المالية للنقابة العامة وللنقابات الفرعية.
5- وضع لائحة الرعاية الاجتماعية والصحية.
6- إعداد الموازنة التقديرية المجمعة للنقابة، وحساباتها الختامية المجمعة.$b$, E'\n', E'\r\n')),
    (144, 0, ARRAY['457e7fab845c4e9777dd7407f9e99fa1']::text[], ARRAY['8e989a9105ce3241d147b47f6c0b202d']::text[], '064df603ecd301a6582dc86fc1c6eb18', replace($b$تنشأ نقابات فرعية فى دائرة كل محكمة ابتدائية، ويكون لها الشخصية الاعتبارية فى حدود اختصاصها.
ولمجلس النقابة العامة أن يقرر إنشاء نقابة فرعية واحدة تشمل اختصاصها أكثر من دائرة محكمة ابتدائية.
ولا يسرى قرارها المذكور إلا بعد موافقة الجمعية العمومية للنقابة المعنية.$b$, E'\n', E'\r\n')),
    (145, 0, ARRAY['b459cc1b333ec3b78b59b3a63f0efdea']::text[], ARRAY['ebed72282b85953f2f0cebb80049e9c6']::text[], 'a9cfc878f715c551e4f119769609f249', replace($b$تضم النقابة الفرعية جميع المحامين المقيدين بالجدول العام فى دائرة النقابة الفرعية والذين يتخذون مكاتبهم أو يلحقون بالإدارات القانونية المنصوص عليها فى هذا القانون فى دائرة اختصاصها.$b$, E'\n', E'\r\n')),
    (146, 0, ARRAY['e17db0aa55804276d8e80f249033b316']::text[], ARRAY['451c370525911c8c3f22f34eee637eb1']::text[], '7f3b697d88bade71fbad8f041ba5fafc', replace($b$تتكون هيئات النقابة الفرعية من:
- الجمعية العمومية.
- مجلس النقابة الفرعية.$b$, E'\n', E'\r\n')),
    (147, 0, ARRAY['6f57ed476731b888d8d0e83c79cf4271']::text[], ARRAY['0c70b12c9c8ee07b348d92db93c77cef']::text[], 'e14db7a8ac6bfd3df738f48de0508649', replace($b$تتكون الجمعية العمومية للنقابة الفرعية من المحامين المقيدين فى الجدول العام فى دائرتها المقبولين للمرافعة أمام محكمة النقض أو محاكم الاستئناف أو المحاكم الابتدائية ممن تتوافر فيهم الشروط المبينة بالفقرة الأولى من المادة (124).$b$, E'\n', E'\r\n')),
    (148, 0, ARRAY['3f62331ae121ee328746df3c6d303507']::text[], ARRAY['ce7950f82c8b9a10c3961acf809e7208']::text[], 'c835a0f8a1ace01aa76be4bcb1c7be64', replace($b$تنعقد الجمعية العمومية للنقابة الفرعية سنويا فى شهر مارس من كل سنة برئاسة نقيبها وذلك بمقر النقابة الفرعية أو فى أى مكان آخر ملائم فى الجهة التى يقع بها مقرها إذا تبين أن مقر النقابة لا يتسع لأعضائها.$b$, E'\n', E'\r\n')),
    (149, 0, ARRAY['2edfa7e0a6ad8f81d7421dc66a5e0afc']::text[], ARRAY['0c64df72c9abbc3103492a06e9a3c3fa']::text[], 'bf3433b34af43b812f86a91f22d34148', replace($b$تختص الجمعية العمومية للنقابة الفرعية بما يأتى:
(1) النظر فى تقرير مجلس النقابة الفرعية وملاحظات مراقبى الحسابات عن الحساب الختامى للنقابة فى السنة المنتهية واقتراح الميزانية التقديرية عن السنة المقبلة.
(2) إبداء الرأى فى الأمور التى يعرضها عليها مجلس النقابة الفرعية أو التى تطلب النقابة العامة الرأى فيها.
(3) انتخاب النقيب وأعضاء مجلس النقابة الفرعية.$b$, E'\n', E'\r\n')),
    (150, 0, ARRAY['d67566284b5c44df8e7fefb9eb6e4a76']::text[], ARRAY['220fbe6fcca5e7f54bc63be2aae326cb']::text[], '2fe8c1a4edd9a379f7e9c24750786b66', replace($b$للجمعية العمومية أن تعقد اجتماعا غير عادى للنظر فى سحب الثقة من مجلس النقابة الفرعية أو من أحد أعضائه بناء على طلب كتابى يقدم من مجلس النقابة الفرعية موقع من عدد من الأعضاء لا يقل عن ثلث عدد أعضاء الجمعية العمومية أو مائة عضو أيهما أقل.
ويبلغ طلب عقد الجمعية إلى مجلس النقابة العامة الذى يتولى توجيه الدعوة خلال ستين يوما على الأكثر من تاريخ طلبها وندب أحد أعضائه لرئاسة اجتماعها والإشراف على إجراءات إبداء الرأى فيها.
كما أن للجمعية العمومية أن تعقد اجتماعا غير عادى كلما رأى مجلس النقابة الفرعية ضرورة لذلك أو قدم به طلب مسبق موقع عليه من ثلث عدد أعضاء الجمعية العمومية أو بناء على طلب مجلس النقابة العامة لطرح موضوع عليه لأخذ الرأى فيه، ويتولى مجلس النقابة الفرعية الدعوى إلى الاجتماع فى هذه الحالات.$b$, E'\n', E'\r\n')),
    (151, 0, ARRAY['c5b1cac29f2ea7cbf931f426eafa03f9']::text[], ARRAY['1daa3dee2a905a03a90aa080018e3f14']::text[], '63c8b335b9d70208ee8953a110b1ddf8', replace($b$تسرى بشأن دعوة الجمعية العمومية للنقابة الفرعية وشروط انعقادها وإجراءاتها وقراراتها ومحاضر جلساتها، الأحكام المقررة فى هذا القانون وفى النظام الداخلى بشأن الجمعية العمومية للنقابة العامة.$b$, E'\n', E'\r\n')),
    (152, 0, ARRAY['5b90eece267b11e111b1cd2b4b5b0205']::text[], ARRAY['c1d3c91cb1d8cd684f2f0b07b7cf1425']::text[], 'b13d4c20f961a2824810916de4d0d89f', replace($b$يتولى شئون النقابة الفرعية مجلس يشكل من:
1- نقيب
2- عدد من الأعضاء لا يقل عن سبعة بواقع عضو عن كل محكمة جزئية وعضو عن الشباب لا يزيد عمره يوم الانتخاب عن خمسة وثلاثين عامًا ومضى على اشتغاله بالمحاماة فعليًا خمس سنوات متصلة، فضلًا عن توافر باقى الشروط المنصوص عليها فى المادة (133) من هذا القانون.
ويتم انتخابهم عن طريق الجمعية العمومية للنقابة وتكون مدة عضوية المجلس أربع سنوات، ويتعين دعوة الجمعية العمومية قبل انتهاء مدة المجلس بستين يوما على الأقل لإجراء انتخابات جديدة.$b$, E'\n', E'\r\n')),
    (153, 0, ARRAY['0eff32281a48d8332f3e4905cb27238b']::text[], ARRAY['3e802ac52c5ac66954368d3ae77c679e']::text[], 'e92ebe02473ae540e86780a17ab84d1b', replace($b$ملغاة$b$, E'\n', E'\r\n')),
    (154, 0, ARRAY['7204219f8e6917867aea5d735808518c']::text[], ARRAY['dace745cfb538e6f0a2df5ed0ec675fd']::text[], 'ca01f57f85a31ac1d74e6117ce7ec2de', replace($b$تشكل هيئة مكتب مجلس النقابة الفرعية من النقيب والأمين العام وأمين الصندوق.
وينتخب مجلس النقابة الفرعية فى أول اجتماع له بعد تشكيله الوكيل والأمين العام وأمين الصندوق. ويشترط فى النقيب أن يكون من المحامين الذين يزاولون المهنة استقلالا المقبولين للمرافعة أمام محكمة النقض ممن مضى على اشتغالهم بالمهنة عشرون سنة متصلة على الأقل.
ويكون لهيئة المكتب كافة الاختصاصات المخولة لهيئة مكتب النقابة العامة فى حدود اختصاص النقابة الفرعية.$b$, E'\n', E'\r\n')),
    (155, 0, ARRAY['3450ba3c49b6c735536fe5b7d6aecac5']::text[], ARRAY['f37caa81c6eaa99491519f293bde4269']::text[], 'ea1ac91548ff9c6043a1292faa8a9718', replace($b$فيما عدا الاختصاصات التى احتفظ بها هذا القانون صراحة لمجلس النقابة العامة يتولى مجلس النقابة الفرعية جميع الاختصاصات المخولة لمجلس النقابة العامة فى دائرة النقابة الفرعية وكذلك الاختصاصات الأخرى التى نص عليها هذا القانون.$b$, E'\n', E'\r\n')),
    (156, 0, ARRAY['99265412c9b984e154417afe099ad4bc']::text[], ARRAY['a94fa123ba83873517e7ea181d8c4be4']::text[], '1357f80cba3e7f1d2d54d98aee980754', replace($b$تسرى على نظام الترشيح وشروطه وحالات عدم الجمع وطريقة الانتخاب أو الإشراف عليه وإسقاط العضوية وشغل الأماكن الشاغرة واجتماعات المجلس وقراراته ومحاضر جلساته، الأحكام المقررة فى هذا القانون وفى النظام الداخلى للنقابة بشأن مجلس النقابة العامة.$b$, E'\n', E'\r\n')),
    (157, 0, ARRAY['b4629a5d55839a3517d5353ca6af6a14']::text[], ARRAY['fe6bb07a3f87d02d9d87c900ca1b88e3']::text[], 'a365027221d4052d7cbdb48f37a7f972', replace($b$يكون للنقابة نظام مالى يصدر به قرار من مجلس النقابة ويبين طريقة إمساك حساباتها وحسابات النقابات الفرعية وطريقة إعداد موازناتها التقديرية وإعداد حساباتها الختامية السنوية ووضع الموازنة السنوية المجمعة والحسابات الختامية المجمعة وطريقة مراجعتها.$b$, E'\n', E'\r\n')),
    (158, 0, ARRAY['71d74452399569cc420358c924ab2f0a']::text[], ARRAY['452fd884d205b207316884e5fbbfaacf']::text[], '63351e315a82c80dec005180936985aa', replace($b$مجلس النقابة هو المهيمن على أموال النقابة وتحصيلها وحفظها ويقوم بإقرار أو صرف النفقات التى تستلزمها شئون النقابة فى حدود الاعتمادات المقررة فى الميزانية.
ويشرف أمين الصندوق على تطبيق النظام المالى والتحقيق من سلامته.
وتباشر مجالس النقابات الفرعية ذات الصلاحيات فى حدود دائرة النقابة الفرعية وفقا للميزانيات التقديرية المقررة من مجلس النقابة العامة.$b$, E'\n', E'\r\n')),
    (159, 0, ARRAY['9eac9605fe9dd17c9236f420769be5f3']::text[], ARRAY['ec7e2fa38eedbdf5a670ef52c4a86144']::text[], 'f6daca69b0206f472b44e70eabf35f81', replace($b$تبدأ السنة المالية للنقابة فى أول يناير وتنتهي فى آخر ديسمبر.$b$, E'\n', E'\r\n')),
    (160, 0, ARRAY['26ab46cbcd37d793ce4483c31aa16a4e']::text[], ARRAY['b09e9818e13021173efb80240a52ab13']::text[], '8d81fcb1bfcc8bcb44099161bcb298db', replace($b$تعين الجمعية العمومية فى اجتماعها السنوى بناء على اقتراح مجلس النقابة العامة مراقبا للحسابات أو أكثر من المقيدين بجدول المحاسبين وتحدد أتعابه.
ويختص بمراجعة حسابات النقابة العامة والنقابات الفرعية وله فى سبيل ذلك اقتراح النظام المالى الذى يكفل حسن سير العمل وأن يقوم بجرد سنوى للخزينة وحسابات العهد والمخازن فى النقابة العامة وفى النقابات الفرعية ويعد تقريرا بالملاحظات عن كل ما تقدم يعرض على مجلس النقابة العامة.
وعليه خلال السنة موافاة أمين الصندوق بما قد يكون لديه من ملاحظات.
ولمراقب الحسابات الاطلاع على دفاتر النقابة العامة والنقابات الفرعية وسجلاتها ومستنداتها وطلب البيانات والإيضاحات التى يرى لزوما لها.$b$, E'\n', E'\r\n')),
    (161, 0, ARRAY['e61fbd487cdf2f506055daa4aec77d76']::text[], ARRAY['fd736dd01d40020edb7f5110312305a7']::text[], '567c039ba2ad4df754c2b940d3038d1f', replace($b$يتلقى مجلس النقابة العامة من النقابات الفرعية فى بداية كل عام وفى موعد لا يجاوز شهر فبراير مقترحاتها بشأن موازنتها التقديرية لسنة مقبلة كما يتلقى منها بيانا بحساباتها الختامية عن السنة المنتهية.$b$, E'\n', E'\r\n')),
    (162, 0, ARRAY['404640f1eeb15b5e39524e54792d561e']::text[], ARRAY['063a9f5da7a6be08654f412a2554001c']::text[], '3006cc499715f672f7dcf7f770ccfa77', replace($b$يضع مجلس النقابة سنويا موازنة تقديرية مجمعة تضم الموازنات التقديرية للنقابات الفرعية فى موعد لا يجاوز آخر فبراير من كل سنة.
كما يعد الحساب الختامى للسنة المنتهية متضمنا الحسابات الختامية لكل نقابة فرعية.
ويحيلها إلى مراقب الحسابات لوضع تقرير عنها.$b$, E'\n', E'\r\n')),
    (163, 0, ARRAY['479cd38abda98cc09dd122dd209f6bc2']::text[], ARRAY['79dc087de59f1d504868d116e2282372']::text[], '164f60c278aa625db57716d5503de052', replace($b$تنشر الموازنة التقديرية والحساب الختامى مع تقرير مراقب الحسابات فى مجلة المحاماة قبل الموعد المحدد لانعقاد الجمعية العمومية بخمسة عشر يوما على الأقل.$b$, E'\n', E'\r\n')),
    (164, 0, ARRAY['959f659e4e42f77ee43d3fe7c9b2e7de']::text[], ARRAY['05a576a6baaef5ad33dd3d46151d977a']::text[], 'f3b298f8fad9a5fe270f271bde47e707', replace($b$يستمر العمل بموازنة السنة السابقة حتى تقوم الجمعية العمومية بإقرار الموازنة الجديدة.$b$, E'\n', E'\r\n')),
    (165, 0, ARRAY['37d1df292fb7cd08749d4e7444bbb5ad']::text[], ARRAY['89302b0b4b16c365a9071292ffb77406']::text[], '258e2ac757eb28608d421aaea812ee7b', replace($b$تودع أموال النقابة العامة فى حساب خاص بالمصرف أو بالمصارف التى يعينها مجلس النقابة العامة بناء على اقتراح أمين الصندوق.
ولمجلس النقابة العامة أن يحدد بناء على اقتراح أمين الصندوق، ما يودع من هذه الأموال فى حسابات الودائع أو فى الحسابات الجارية وما يتم استثماره منها فى سندات حكومية أو أوراق مالية وما يحتفظ به بخزينة النقابة بصفة مستديمة للصرف منها فى الحالات الطارئة.
ويكون الصرف من حسابات النقابة وفق ما يقضى به النظام المالى للنقابة وبتوقيع النقيب أو الوكيل وأمين الصندوق أو الأمين المساعد للصندوق.$b$, E'\n', E'\r\n')),
    (166, 0, ARRAY['93cd6505ae3921328f6093c25f637a37']::text[], ARRAY['c7d3037bd9ec049b9f393d70b6089bb0']::text[], '43046afdc6fa112b58b987f8830bab66', replace($b$تتكون موارد النقابة العامة أساسا من:
(1) رسوم القيد بجدول النقابة.
(2) الاشتراكات السنوية وفوائد الاشتراكات المتأخرة.
(3) حصيلة ثمن أجور الإعلانات القضائية التى تنشر بمجلة المحاماة.
(4) عائد استثمارات أموال النقابة.
(5) الموارد الأخرى التى يوافق عليها مجلس النقابة.
ويحدد مجلس النقابة العامة عند إعداد الموازنة التقديرية ما يخصص سنويا من هذه الموارد للنقابات الفرعية على أساس عدد الأعضاء المقيدين بكل نقابة فرعية.$b$, E'\n', E'\r\n')),
    (167, 0, ARRAY['011e10139934e7d8873d67c133670f08']::text[], ARRAY['78cdad4057aa9a2dc93e019aacdd402c']::text[], '9c5088da5c796c894cd7167c9d0b0bd9', replace($b$على المحامى أن يؤدى عند التقدم بطلب قيد اسمه فى الجدول العام أو بأحد الجداول الملحقة به رسم القيد المقرر للجدول الذى يريد قيد اسمه به مع رسوم القيد بالجداول السابقة إذا لم يكن قد أداها.
وتكون رسوم القيد كالاتى:
60 جنيه للقيد بالجدول العام.
على أن يزاد هذا الرسم إلى خمسة أمثاله إذا تجاوزت سن طالب القيد أربعين سنة، ويزاد إلى عشرة أمثاله إذا تجاوزت سنه خمسين سنة، ويزاد إلى ألف جنيه إذا تجاوزت سنة الستين.
80 جنيه للقيد بجداول المحامين المقبولين أمام المحاكم الابتدائية.
120 جنيه للقيد بجداول المقبولين أمام محاكم الاستئناف.
180 جنيه للقيد بجداول المحامين المقبولين أمام محكمة النقض.
60 جنيه للإعادة إلى الجدول، ما لم يكن قد مضى على نقله إلى جدول غير المشتغلين أكثر من خمس عشر سنة فتسرى بشأنه الرسوم المقررة بالجدول العام.$b$, E'\n', E'\r\n')),
    (168, 0, ARRAY['f3e16ed90dc4aa330957434ea0a27b8c']::text[], ARRAY['23c7dea14738b030d12193e0f4f059f6']::text[], '24a121b7bbea827a098a1f82394b0b09', replace($b$يؤدى المحامى اشتراكا سنويا وفق الفئات الآتية:
6 جنيه للمحامى تحت التمرين.
12 جنيه للمحامى أمام المحاكم الابتدائية إذا لم تزد مدة قيده فى هذا الجدول على ثلاث سنوات
24 جنيه للمحامى أمام المحاكم الابتدائية إذا زادت مدة قيده فى هذا الجدول على ثلاث سنوات.
60 جنيه للمحامى أمام محاكم الاستئناف.
80 جنيه للمحامى أمام محكمة النقض.$b$, E'\n', E'\r\n')),
    (169, 0, ARRAY['94f40f8689d59d3d760fa9c6d2a3964a']::text[], ARRAY['8faba877bae20b40cf5764492b8f0b04']::text[], '8c5e30a6fbc23ed0eb6b4fc2238cc574', replace($b$على المحامى أن يؤدى الاشتراك السنوى وفق الفئات المبينة بالمادة السابقة فى ميعاد غايته آخر مارس من كل سنة.
ويتم السداد إلى النقابة الفرعية التى يتبعها أو إلى النقابة العامة.
وعلى النقابة الفرعية توريد ما حصلته من اشتراكات إلى النقابة العامة بمجرد تحصيلها.
ومن يتأخر فى سداد الاشتراك عن الموعد المشار إليه لا يقبل منه أى طلب ولا تعطى له أى شهادة من النقابة ولا يتمتع بأى خدمة نقابية إلا بعد أن يؤدى جميع الاشتراكات المتأخرة.$b$, E'\n', E'\r\n')),
    (170, 0, ARRAY['5cad8bae55e8fd473bd0190b317d815f']::text[], ARRAY['3b56972c163f4ed40aea4baf52adce81']::text[], '0814be233805e79ecedda05613b657ad', replace($b$يقوم أمين الصندوق بعد التاريخ المبين بالمادة السابقة بإنذار المتخلف باستبعاد اسمه بمقتضى إعلان ينشر فى مجلة المحاماة خلال شهر ابريل من كل سنة.
ومن يتخلف عن تأدية الاشتراك حتى أخر يونيو يستبعد اسمه من الجدول بقوة القانون.
فإذا أوفى الاشتراكات المستحقة عليه أعيد اسمه إلى الجدول بغير إجراءات وأحتسب له مدة الاستبعاد فى الاقدمية والمعاش.
فإذا مضى على استبعاد المحامى سنتان دون أن يؤدى الاشتراكات المستحقة عليه وجب التنبيه عليه بالوفاء خلال ثلاثة أشهر، فإذا انقضى هذا الموعد دون الوفاء بالاشتراكات السنوية زالت عضوية النقابة عنه بقوة القانون ولا يجوز أن يعيد اسمه إلا بإجراءات جديدة ورسوم قيد جديدة مع سداد رسوم الاشتراكات المستحقة، وتضم المدة السابقة على زوال عضويته من النقابة إلى مدد القيد الجديدة.$b$, E'\n', E'\r\n')),
    (171, 0, ARRAY['52c1d9d1caa8b56eb23a26a033a59d9c']::text[], ARRAY['2ddb105fe543e98617ae041c6ad7ca78']::text[], '27cc5116ce70f0269e07f7fa8355e866', replace($b$يجوز لمجلس النقابة إعفاء المحامى - فيما عدا من كان تحت التمرين - من رسم الاشتراك عن سنة واحدة متى وجدت أسباب قوية تبرر ذلك بناء على توصية مجلس النقابة الفرعية المختص.
ولا يجوز أن يتكرر الإعفاء لأكثر من سنتين متتاليتين خلال عشر سنوات.$b$, E'\n', E'\r\n')),
    (172, 0, ARRAY['a5b54eab32a0a394e0cb52da724ed340']::text[], ARRAY['6cf7f755b42760ac34f3f080482944b0']::text[], 'b94bec5cdd2af76546d7fc6b3f4857d1', replace($b$لا ترد رسوم القيد التى تدفع للنقابة، على أن للجنة القبول المختصة أن تأذن برد رسوم القيد إذا كان رفض الطلب لسبب لا يرجع إلى تقصير فى استيفاء شروط القيد.
ولا تقبل طلبات استرداد رسوم القيد والاشتراكات بعد انتهاء السنة المالية التالية للسنة التى دفعت فيها.$b$, E'\n', E'\r\n')),
    (173, 0, ARRAY['950a56e575754bc1847f34aa5a81b631']::text[], ARRAY['23dc26fdd9fa0668fbc002a4eb7f078d']::text[], 'aeb00c49555b0430304daf7a868c749b', replace($b$تتحمل الهيئات العامة وشركات القطاع العام والشركات والجهات الخاصة برسوم القيد والاشتراكات الخاصة بالمحامين العاملين فى إدارتها القانونية المرخص لها بذلك طبقا لأحكام هذا القانون.
وإذا لم تقم بسدادها فى الميعاد المحدد، كان المحامى مسئولا أمام النقابة عن سدادها، مع حفظ حقه فى استردادها من الجهة التى يتبعها.$b$, E'\n', E'\r\n')),
    (174, 0, ARRAY['b01fd7cca34ea1eb62933e3ece9cd07f']::text[], ARRAY['de11c9186cf534129dc006d0385cfed0']::text[], 'cf033c5824e576604c0b734f0f48dbcd', replace($b$تعد مجلة المحاماة من الصحف المقررة لنشر الإعلانات القضائية.
وفى الحالات التى يلزم فيها القانون بنشر الحكم فى إحدى الصحف يتم النشر فى مجلة المحاماة.
وعلى الجهات المسئولة عن تنفيذ الأحكام مراعاة ذلك.$b$, E'\n', E'\r\n')),
    (175, 0, ARRAY['ad8ca477af93963c66decd14f6cd0328']::text[], ARRAY['8f629a28e70a31dc9233ce530dee9001']::text[], '5dbb43c00ba2828761d3baf7571c96e1', replace($b$تعفى نقابة المحامين والنقابات الفرعية واللجان الفرعية وكافة المؤسسات التابعة للنقابة من كافة الضرائب والرسوم والدمغة والعوائد أو غير ذلك من التكاليف المالية مهما كان نوعها.
وتعفى أموال النقابة والنقابات الفرعية الثابتة والمنقولة. وجميع العمليات الاستثمارية مهما كان نوعها من جميع الضرائب والرسوم والدمغة والعوائد التى تفرضها الحكومة أو أية سلطة عامة.$b$, E'\n', E'\r\n')),
    (176, 0, ARRAY['639600b7f10f40a22d6e9adbd6b12339']::text[], ARRAY['ae0af6e8a16446fdf2fa0b636f973c6e']::text[], 'ee3423133481cdd1ede5689bd325eb5c', replace($b$ينشأ بنقابة المحامين صندوق للرعاية الاجتماعية والصحية ويكون مقره بها، ويهدف إلى رعاية أعضاء النقابة من المحامين المقيدين بالجدول العام اجتماعيا وصحيا بما فى ذلك ترتيب معاشات لهم عند تقاعدهم أو للمستحقين عنهم فى حالة الوفاة.
ويكون للصندوق شخصية اعتبارية مستقلة ويمثله نقيب المحامين قانونا أمام الغير ويكون له فروع فى دائرة كل نقابة فرعية، تختص بمباشرة اختصاصاته فى حدود دائرة النقابة الفرعية وذلك فيما عدا ترتيب المعاشات.$b$, E'\n', E'\r\n')),
    (177, 0, ARRAY['fa4c2d7876ee2144288e72230d6aba08']::text[], ARRAY['3ec3dde7226dcac8146c5a674b1f8de8']::text[], '11a8ccd06f85c3053ac3c35fc57c878f', replace($b$يقوم على إدارة الصندوق لجنة تشكل برئاسة نقيب المحامين وعضوية أقدم وكيلى النقابة العامة ممن يزاول المهنة مستقلا وأمين صندوقها ونقيب القاهرة وثلاثة من نقباء النقابات الفرعية الأخرى وأربعة من أعضاء مجلس النقابة العامة يختارهم المجلس كل سنتين.
ويحل الوكيل الآخر محل أقدم الوكيلين، كما يحل أمين الصندوق المساعد محل أمين الصندوق وذلك عند غياب أى منهما.$b$, E'\n', E'\r\n')),
    (178, 0, ARRAY['94f91e7d1f7cac9c22772ffab0103b1e']::text[], ARRAY['f5d0a2c0fc9dc02dbd06be1e42163101']::text[], '39c35b66f716294f763f31497e3ab87e', replace($b$لجنة الصندوق هى السلطة المهيمنة على تصريف شئونه فى حدود أحكام هذا القانون ولائحته التنفيذية، وتتولى اللجنة على الأخص المهام التالية:
(1) إعداد اللائحة التنفيذية للرعاية الاجتماعية والصحية.
(2) الإشراف على تنفيذ أحكام القانون واللائحة التنفيذية، واتخاذ ما تراه لازما لرفع مستوى أداء الخدمات التى يقدمها.
(3) وضع الخطة العامة لاستثمار أموال الصندوق والموافقة على مجالات توظيفها.
(4) تعيين الخبراء الاكتواريين الذين قد يختارهم الصندوق وتحديد أتعابهم.
(5) إعداد ميزانية الصندوق التقديرية وحساباته الختامية السنوية ومركزه المالى وعرضها على مجلس النقابة.
(6) اقتراح بتعديل الأحكام المنظمة للصندوق فى القانون أو فى لائحته التنفيذية.$b$, E'\n', E'\r\n')),
    (179, 0, ARRAY['d169cb511fd733598bace95e3f94f189']::text[], ARRAY['61302564af4b2716b972e2bc19f74f0c']::text[], '01733834849a9588484259ca8ecffde9', replace($b$تنعقد اللجنة بدعوة من رئيسها مرة كل ثلاثين يوما على الأقل ويجوز لها أن تدعو خبراء مختصين للاشتراك فى اجتماعاتها دون أن يكون لهم حق التصويت.
وتكون اجتماعاتها صحيحة بحضور سبعة من أعضائها على أن يكون من بينهم النقيب أو وكيل النقابة وأمين الصندوق أو من ينوب عنه.
وتصدر قراراتها بالأغلبية لأصوات الحاضرين، وذلك فيما عدا تقرير أوجه الاستثمار فيشترط موافقة الأغلبية المطلقة لأعضاء اللجنة.$b$, E'\n', E'\r\n')),
    (180, 0, ARRAY['177c88d9e2115e8139a5672888d2fec3']::text[], ARRAY['38888177e8dfa70d87f2e8508a7defbd']::text[], 'aee5e5eb9ea7ceafef074db5eab16523', replace($b$للجنة أن تشكل من بين أعضائها لجنة فرعية تختص بالبت فى الحالات العاجلة فيما عدا ترتيب المعاشات، وذلك فى الحدود التى تبينها اللائحة التنفيذية.$b$, E'\n', E'\r\n')),
    (181, 0, ARRAY['55442b7fc84f938e928a3138d4f93a48']::text[], ARRAY['10e7db79341bd2f1af9dfca6569e5714']::text[], 'a4406d11e42e0da5338bf6b6a2c0aa70', replace($b$تتكون موارد الصندوق من:
(1) حصيلة صندوق الإعانات والمعاشات الموجودة بالنقابة وقت العمل بأحكام هذا القانون.
(2) حصيلة طوابع دمغة المحاماة.
(3) حصيلة أتعاب المحاماة التى تحكم بها المحاكم فى جميع القضايا.
(4) عائد استثمار أموال الصندوق.
(5) الهبات والتبرعات والإعانات التى يتلقاها والتى يوافق الصندوق على قبولها.$b$, E'\n', E'\r\n')),
    (182, 0, ARRAY['5a463b5518e9889740d6b34b0906432b']::text[], ARRAY['a26d653b76b3ff94ed3e34ebcc124495']::text[], 'e325d3172b2ec13ac4623b5f09672834', replace($b$تصدر نقابة المحامين لصالح صندوق الرعاية الاجتماعية والصحية طوابع دمغة المحاماة بفئات من خمسة جنيهات إلى جنيه واحد وأى فئات أخرى يقررها مجلس النقابة بناء على اقتراح لجنة الصندوق.$b$, E'\n', E'\r\n')),
    (183, 0, ARRAY['fa085dd7110527fa6ab9764df239c797']::text[], ARRAY['6031f6ac82ee974228e37bd0dc9e10cd']::text[], '90f5b7d481cff6c8d13e14e06650c8a4', replace($b$تستحق الدمغة على المحامى عند إثبات حضوره لأول مرة فى محاضر جلسات المحاكم أيا كان نوعها واللجان القضائية واللجان الإدارية ذات الاختصاص القضائى وجلسات التحقيق الذى تجريه النيابات وجهات التحقيق المختلفة.
ولا يجوز للمحاكم والجهات المتقدمة أن تقبل حضور المحامى أو تقبل تقديم أى دفاع أو أوراق منه إلا إذا سدد الدمغة.
وإذا تعدد المحامون فى الدعوى أو التحقيق ولو عن نفس الموكل، تعددت الدمغة.
وتكون قيمة طابع الدمغة فى الحالات المتقدمة على النحو التالى:
جنيه واحد عند الحضور أمام المحاكم الجزئية أو فى جلسات التحقيق.
جنيهان عن الحضور أمام المحاكم الابتدائية والإدارية.
ثلاثة جنيهات عند الحضور أمام محاكم الاستئناف والقضاء الإدارى.
خمسة جنيهات عند الحضور أمام محاكم النقض والإدارية العليا والدستورية العليا.$b$, E'\n', E'\r\n')),
    (184, 0, ARRAY['bf606c0e14a1cfdd57a8c22247cffd6c']::text[], ARRAY['98a21d03e0489c51207dfdcc00cd0f52']::text[], 'fadc410d5ac93737e6a19a04832721d6', replace($b$تستحق دمغة المحاماة بفئة (خمسة جنيهات) على طلبات تقدير أتعاب المحامين التى تقدم اللجنة المشار إليها فى المادة (84) من هذا القانون فإذا قبل الطرفان نتيجة وساطتها، استحقت الدمغة بواقع عشرة جنيهات من الخمسمائة جنيه الأولى من قيمة المتصالح عليه وعشرين جنيها عن الخمسمائة جنيه التالية وخمسين عن كل خمسمائة جنيه تالية ويلزم بسدادها المسئول عن قيمة المطالبة ويتم لصقها على المحضر الذى تحرره اللجنة فى هذا الشأن.
وإذا أصر أحد الطرفين على طلب النظر فى أمر التقدير ضوعف ما يستحق من دمغة على الطلب وفق ما تقدم ويسددها مقدم الطلب ويرجع بها على المحكوم عليه.$b$, E'\n', E'\r\n')),
    (185, 0, ARRAY['83c8a4cd2d96c9d1babaa13b337bf30f']::text[], ARRAY['9828dc6f509e517048e401ed8129661c']::text[], '39d6815f62ba789419eec82fd7a74549', replace($b$علاوة على ما نص عليه فى المادة السابقة تستحق دمغة المحاماة على الأوراق الآتية:
(1) التوكيلات الصادرة إلى المحامين.
(2) طلبات القيد بجداول المحامين.
(3) الشهادات التى تصدرها نقابة المحامين بناء على طلب المحامى أو أى جهة أخرى ويكون طابع الدمغة فى هذه الحالات من فئة جنيه واحد على كل ورقة.$b$, E'\n', E'\r\n')),
    (186, 0, ARRAY['330a80a83fb49620237a3592dfffb4f2']::text[], ARRAY['9b636e8bbe52cb3025a24d8c355ac33b']::text[], '1d4d5b26ee503fff05d4ca3e698c5e82', replace($b$يكون سداد قيمة دمغة المحاماة المبينة بالمواد الثلاثة السابقة عن طريق لصقها على محاضر الجلسات أو الأوراق المشار إليها ويكون الموظف المختص مسئولا عن تنفيذ ذلك.
ولمفتشى أقلام الكتاب بوزارة العدل ولمن تندبه النقابة التحقق من سداد الدمغات المشار إليها بالاطلاع على المحاضر والأوراق المفروضة عليها وفى حالة عدم تنفيذ حكم القانون فى هذا الشأن يكون الموظف المختص مسئولا شخصيا عن قيمتها مع عدم الإخلال بمسئوليته الإدارية.$b$, E'\n', E'\r\n')),
    (187, 0, ARRAY['d6041c5c8fec247b8762865009b23422']::text[], ARRAY['28fe3654f48b271720adfa9448eaca5c']::text[], 'e64020fbca212d0b978dc31106f98c64', replace($b$على المحكمة من تلقاء نفسها وعند إصدار حكمها أن تلزم من خسر الدعوى بأتعاب المحاماة لصالح صندوق الرعاية الصحية والاجتماعية بحيث لا تقل عن الآتى:
1- خمسين جنيهًا فى الدعاوى المنظورة أمام المحاكم الجزئية.
2- خمسة وسبعين جنيهًا فى الدعاوى المنظورة أمام المحاكم الابتدائية والإدارية.
3- مائة جنيه فى الدعاوى المنظورة أمام محاكم الاستئناف ومحاكم القضاء الإدارى.
4- مائتى جنيه فى الدعاوى المنظورة أمام محاكم النقض والإدارية العليا والدستورية العليا.
وتحصل أتعاب المحاماة مع الرسوم القضائية عند قيد الدعوى.
وعلى المحكمة فى الدعوى الجنائية أن تحكم بأتعاب المحاماة التى يندب فيها محامٍ بحيث لا تقل عن الآتى:
1- مائتى جنيه فى دعاوى الجنح المستأنفة.
2- ثلاثمائة جنيه فى دعاوى الجنايات.
3-- خمسمائة جنيه فى دعاوى النقض الجنائى.
ويحصل فى قضايا التحكيم مبلغ خمسمائة جنيه كأتعاب محاماة تحصل مع الرسوم القضائية عند إيداع حكم المحكمين بالمحكمة المختصة.$b$, E'\n', E'\r\n')),
    (188, 0, ARRAY['9ae97ed71130cb27c466923632537038']::text[], ARRAY['08baa49fdb1aab2934b2d4bfa89891c8']::text[], '7a52137da75309a9fbf5b0938e2849ed', replace($b$تؤول إلى الصندوق أتعاب المحاماة المحكوم بها فى جميع القضايا طبقا للمبين بالفقرة الأولى من المادة السابقة وتأخذ هذه الأتعاب بحكم الرسوم القضائية وتتولى أقلام الكتاب تحصيلها لحساب الصندوق بذات القواعد المقررة لتحصيل الرسم بمقتضى قوانين الرسوم القضائية وتخصص من الأتعاب المحصلة نسبة 5% لأقلام الكتاب والمحضرين ويكون توزيعها فيما بينهم طبقا للقواعد التى يضعها وزير العدل بقرار منه.$b$, E'\n', E'\r\n')),
    (189, 0, ARRAY['ec99cdbca1ebae9dad1b4d9f223dcfb5']::text[], ARRAY['f1c492f205ab54b1d672a7268fae13f4']::text[], '361ce2e16365ca9c76969dafc30b3aff', replace($b$تودع أموال الصندوق فى حساب خاص بالمصرف أو المصارف التى تختارهم لجنة الصندوق ويكون الصرف منها بناء على قرار من اللجنة وبتوقيع رئيسها أو أمين الصندوق أو من ينوب عنهما.
ويمسك الصندوق حسابات له مستقلة عن حسابات النقابة العامة.
ويكون للصندوق مراقب للحسابات تعينه الجمعية العمومية سنويا وتحدد أتعابه بناء على اقتراح مجلس النقابة، ويجوز أن يكون مراقب حسابات النقابة مراقبا لحسابات الصندوق.$b$, E'\n', E'\r\n')),
    (190, 0, ARRAY['3798053bafe1e84487607f2539827d2f']::text[], ARRAY['e5f33604de57a30c07ea99fc060f11ea']::text[], '6243ff1e48f0289467490af31884c50c', replace($b$تعفى أموال الصندوق الثابت والمنقولة وجميع العمليات الاستثمارية مهما كان نوعها من الضرائب والرسوم والدمغة والعوائد التى تفرضها الحكومة أو أى سلطة أخرى.
كما تعفى العمليات التى يباشرها الصندوق من الخضوع لاحكام القوانين الخاصة بالاشراف والرقابة على هيئات التأمين.
وذلك دون إخلال بحق مجلس النقابة فى أن يعهد إلى الهيئة العامة للتأمين بندب بعض خبرائه الاكتواريين لفحص بعض أوجه نشاط الصندوق واستثماراته.$b$, E'\n', E'\r\n')),
    (191, 0, ARRAY['1cf80eed2320e0f4b6411e5fb43d00b3']::text[], ARRAY['7f61a1c980a3b4277f8cf2b7f6c6b155']::text[], '3c3175dfbe710a33db407190fb860027', replace($b$تعد اللجنة فى موعد لا يجاوز آخر فبراير من كل سنة مشروع موازنة السنة المقبلة والحساب الختامى للسنة المنتهية ويعرض على مجلس النقابة مع تقرير مراقب حسابات الصندوق للنظر فيه وعرضه على الجمعية العمومية الصندوق.
ويستمر العمل على أساس الموازنة السابقة حتى يتم اعتماد الموازنة الجديدة من الجمعية العمومية.$b$, E'\n', E'\r\n')),
    (192, 0, ARRAY['821c4a7719bb5f824890ce1013460964']::text[], ARRAY['20b04f005f932ff7a7824843b6cae3c7']::text[], 'ff08357088d1301ec59ed5d8a8b0e482', replace($b$تعد الجمعية العمومية للنقابة التى تدعى للنظر فى موازنة النقابة وحساباتها الختامية السنوية، جمعية عمومية للصندوق تختص باعتماد موازنته التقديرية وحساباته الختامية وتعيين مراقب حساباته وتحديد أتعابه.$b$, E'\n', E'\r\n')),
    (193, 0, ARRAY['9e4f1410282def7529e3b4a1b89f9788']::text[], ARRAY['00098b084fbe2ecbd7d321498597a349']::text[], 'e2119a8f7fb84785a8573b010a65535e', replace($b$تنشر الموازنة التقديرية والحساب الختامى للصندوق فى مجلة المحاماة مع الموازنة التقديرية والحساب الختامى للنقابة العامة.$b$, E'\n', E'\r\n')),
    (194, 0, ARRAY['58f5f85bfabf7bb0677737a4542ab802']::text[], ARRAY['e1bd871a9a671d0aec810e840272a165']::text[], 'c40af86f4a4e90295088fe0556a1d361', replace($b$يراعى فى اعداد الموازنة السنوية للصندوق تكوين احتياطى للصندوق يقدر بما لا يقل عن عشرين فى المائة من إيراداته ويخصص لمواجهة أى عجز طارئ فى موازنة الصندوق.
كما يراعى فى إعداد هذه الموازنة تحديد المبالغ التى تخصص للرعاية الاجتماعية والصحية للأعضاء، وما يرصد منها للنقابات الفرعية على أساس عدد أعضائها المقيدين بالجدول العام.$b$, E'\n', E'\r\n')),
    (195, 0, ARRAY['8880f0da3c0c5a08ad4d28bbb08d0b9a']::text[], ARRAY['ad498d06baf04fd69e139305ea6defc1']::text[], 'bdf5e89ad8946aae2d1b6dd8a4f29eb6', replace($b$يفحص المركز المالى للصندوق مرة على الأقل كل خمس سنوات بمعرفة خبير اكتوارى تندبه الهيئة العامة التأمين بناء على طلب مجلس النقابة، فإذا تبين وجود عجز فى أموال الصندوق أوضح الخبير أسباب العجز وما يقترحه من وسائل لتلافيه.
ويعرض تقريره على مجلس النقابة ويبلغ إلى لجنة الصندوق.
ويكون على مجلس النقابة فى هذه الحالة - بناء على الملاحظات التى تبديها لجنة الصندوق -أن يدعو الجمعية العمومية للانعقاد ويعرض عليها ما يقترحه من وسائل لسد العجز وإذا تبين من نتيجة الفحص الاكتوارى وجود فائض فى الصندوق، كان لمجلس النقابة أن يقترح على الجمعية العمومية إما زيادة الاحتياطي العام أو تكون احتياطيات خاصة لأغراض مختلفة أو زيادة المعاشات والخدمات التى يؤديها الصندوق للمنتفعين به.$b$, E'\n', E'\r\n')),
    (196, 0, ARRAY['191d52a1a497ba6f15bcc4bc1214e449']::text[], ARRAY['0ce0d03113ecd5ba03efbe298ec77a04']::text[], 'e36294aab4dbe4505c4b8ca41464bdf0', replace($b$للمحامى الحق فى معاش كامل إذا توافرت فيه الشروط الآتية:
(1) أن يكون اسمه مقيدا بجدول المحامين المشتغلين.
(2) أن يكون قد مارس المحاماة ممارسة فعلية مدة خمس وعشرين سنة ميلادية متصلة أو منفصلة بما فيها مدة التمرين التى لا تزيد على أربع سنوات مع احتساب مدة التجنيد الإلزامية اللاحقة على القيد بالجدول ضمن المدد السابقة، وذلك دون الإخلال بحكم المادة (24) من هذا القانون.
(3) أن يكون قد بلغ ستين سنة ميلادية على الأقل.
ويعتبر فى حكم بلوغ سن الستين وفاة المحامى أو عجزه عجزا كاملا مستديما.
(4) أن يكون مسددا لرسوم الاشتراك المستحق عليه ما لم يكن قد أعفى منها طبقا لأحكام هذا القانون.$b$, E'\n', E'\r\n')),
    (197, 0, ARRAY['f919380f97b9ddd9108f603b0e2c4919']::text[], ARRAY['5b62d61f48da2e5fb2c5eb0c6863a6d7']::text[], '924f65fe4bff02a0885a81d1cde1ed28', replace($b$يقدر المعاش المنصوص عليه فى المادة السابقة بواقع ستة جنيهات عن كل سنة من سنوات الاشتغال بالمحاماة بحد أقصى قدره مائتان وأربعون جنيها.
ويجوز للجمعية العمومية تعديل المعاش أو تعديل الحد الأقصى تبعا لتغير الأسعار القياسية لنفقات المعيشة وفى ضوء المركز المالى للصندوق وفق أحكام المادة (194).
قضي بعدم دستورية عجز الفقرة الأولى من هذه المادة فيما نصت عليه من "ويخفض المعاش إلى النصف بالنسبة للمحامين المعاملين بأحكام قانون التأمين الاجتماعى وذلك عن كل سنة من سنوات التأمين الاجتماعى".$b$, E'\n', E'\r\n')),
    (198, 0, ARRAY['13a07d3b96526e85fd05e1da9736469e']::text[], ARRAY['a9fd6587fcdfca3e9d746f0c07358939']::text[], '64660ffd90869bcbb2485ae86289fdae', replace($b$يستحق المعاش للمحامى على ذات الأساس الوارد بالمادة السابقة فى الحالتين الآتيتين:
1-إذا طلب المحامى الذى مارس المحاماة عشرين سنة كاملة فأكثر وبلغ الخامسة والخمسين إحالته إلى المعاش لأسباب توافق عليها لجنة الصندوق.
2-إذا أصاب المحامى عجز كامل يمنعه من الاستمرار فى مزاولة المهنة وكانت مدة اشتغاله عشر سنوات على الأقل.$b$, E'\n', E'\r\n')),
    (199, 0, ARRAY['f316a597e8877502469069e9570bd795']::text[], ARRAY['a06f154795d34cf269271a9bb2b714b2']::text[], 'cdc12f43cbc262246a355fac60d55d31', replace($b$فى حالة وفاة المحامى الذى يستحق معاشا طبقا للمادة السابقة يؤول معاشه إلى المستحقين عنه.$b$, E'\n', E'\r\n')),
    (200, 0, ARRAY['cae93b0ee579bb22acddeb48765fe2cf']::text[], ARRAY['5e9af20b816dd0e246eb415b53d92012']::text[], '7f77eb271ee4c49099ee551c1e474738', replace($b$إذا توفى المحامى أو أصيب بعجز كلى دون أن تتوافر فيه شروط استحقاقه معاشا طبقا للمواد السابقة وكان مقيدا بالجدول العام صرف له أو المستحقين عنه مبلغ خمسمائة جنيه دفعة واحدة ومعاش قدره أربعون جنيها شهريا.$b$, E'\n', E'\r\n')),
    (201, 0, ARRAY['9076a277748b8937db34c84efedc0902']::text[], ARRAY['a694e320a69b5a897cc9cb71401cd4f3']::text[], 'ccd2059a29dbfa50635947ea65321870', replace($b$عند حساب مدة ممارسة المحامى للمحاماة تجبر كسور السنة إذا زادت على النصف وتهمل أن قلت عن ذلك.$b$, E'\n', E'\r\n')),
    (202, 0, ARRAY['4adef3452f67b7c95c9a2fcead7c8fe3']::text[], ARRAY['0d3bcad5414d065431b3fcc7db3a1b09']::text[], '1d010def5de7f1747fe73ac622827cd8', replace($b$يقصد بالمستحقين فى المعاش:
(1) أرملة المحامى أو صاحب المعاش.
(2) أبناؤه وبناته الذى لم يجاوزوا الحادية والعشرين وقت وفاته، فإذا كانوا قد جاوزوها اعتبروا ضمن المستحقين إذا كانوا فى إحدى مراحل التعليم التى لا تجاوز التعليم الجامعى أو العالى حتى بلوغهم سن السادسة والعشرين أو الانتهاء من دراستهم، أى التاريخين أقرب.
ويعاد توزيع نصيب المستحق المقطوع معاشه على باقى المستحقين.
(3) بناته غير المتزوجات أو المترملات أو المطلقات ممن تجاوزن الحادية والعشرين.
(4) الأخوات والأخوة المصابون بعجز كامل عند وفاته بمنعهم على الكسب.
(5) الوالدان.
ويشترط للاستحقاق فى المعاش فى الحالات المبينة فى البنود 3، 4، 5 أن تثبت إعالة المحامى لطالب الاستحقاق حال حياته وألا يكون له دخل خاص يعادل ما يستحقه فى المعاش فإذا نقص عما يستحق له أدى إليه الفرق.
وتبين اللائحة التنفيذية كيفية إثبات الإعالة وعدم وجود دخل خاص وكيفية ثبوت العجز الكامل وذلك فى الحالات المشار إليها.
قضي بعدم دستورية نص البند (1) من هذه المادة فيما تضمنه من قصر استحقاق المعاش على أرملة المحامى دون أرمل المحامية.$b$, E'\n', E'\r\n')),
    (203, 0, ARRAY['4bbab56fa3ea45cbb1ffa9b6ca21e85d']::text[], ARRAY['40793be4164691a6849df0d6b9f92caf']::text[], 'd8c56fecafa41865b9e211933bccd064', replace($b$يقطع معاش المستحق فى الحالات الآتية:
(1) وفاة المستحق.
(2) زواج الأرملة أو المطلقة والبنت أو الأخت.
(3) بلوغ الابن أو الأخ سن الحادية والعشرين ويستثنى من ذلك:
(أ) العاجز عن الكسب حتى زوال حالة العجز.
(ب)الطالب فى إحدى مراحل التعليم التى لا تجاوز الجامعى أو العالى حتى انتهاء دراسته أو بلوغه سن السادسة والعشرين أيهما أقرب ويستمر صرف معاش الطلب الذى بلغ سن السادسة والعشرين خلال السنة الدراسية حتى نهايتها.
(4) إذا توافرت فى المستحق شروط استحقاق معاش أكبر مع مراعاة حكم المادة (206).$b$, E'\n', E'\r\n')),
    (204, 0, ARRAY['fd2888fc4c003c57c6b212b38cae1b37']::text[], ARRAY['768561915d865016ecc286f88d693313']::text[], 'da55fdf70ae58767eaeda43e8f2e0bd8', replace($b$إذا طلقت البنت أو الأخت أو ترملت أو عجز الابن أو الأخ عن الكسب بعد وفاة المحامى أو صاحب المعاش منح كل منهم ما كان يستحق له من معاش بافتراض استحقاقه فى تاريخ وفاة المورث دون مساس بحقوق باقى المستحقين.
كما يعود حق الأرملة فى المعاش إذا طلقت أو ترملت ولم تكن مستحقة لمعاش عن الزوج الأخير.$b$, E'\n', E'\r\n')),
    (205, 0, ARRAY['9f8831f1efd98eaa2611e0a2dc7e8617']::text[], ARRAY['3562f1d4c1db41693b9aa631296e62e7']::text[], '68e59c6f64a609fcfa4b311cd2cd6364', replace($b$يوقف صرف المعاشات إلى المستحقين عن المحامى عدا الزوجة إذا استخدموا فى اى عمل وكان دخلهم فيه يعادل المعاش أو يزيد عليه.
فإذا نقص الدخل عما يستحقونه من المعاش أدى إليهم الفرق.
ويعود حق هؤلاء فى صرف المعاش كاملا أو جزء منه إذا انقطع هذا الدخل كله أو بعضه.
قضي بعدم دستورية نص هذه المادة فيما تضمنه من قصر الحق في الجمع بين المعاش والدخل من العمل على أرملة المحامى دون أرمل المحامية.$b$, E'\n', E'\r\n')),
    (206, 0, ARRAY['4eff28cfbe139bb1aa23fce33b771bcd']::text[], ARRAY['d63a56bd819a9c93a7d46708947f31f3']::text[], 'b5c400ce4cdadd4e6cef96012385c659', replace($b$لا يجوز الجمع بين معاش التقاعد المقرر وفقا لأحكام هذا القانون وبين المعاش المستحق بمقتضى قوانين أخرى عن ذات السنوات إلا إذا كان مجموع المعاشين لا يزيد على مائتين وأربعين جنيها وإلا خصم من معاش النقابة مقدار الزيادة،
ولا يسرى هذا القيد على محامى الإدارات القانونية.
على أنه إذا كان المعاش المستحق بمقتضى قوانين أخرى عن سنوات غير سنوات مزاولة المهنة، فلا يسرى عليه حكم الفقرة السابقة.$b$, E'\n', E'\r\n')),
    (207, 0, ARRAY['614c852c27b96d22bed0f960683c3e2c']::text[], ARRAY['b9aca4918e22c1b48a1424fc90d7c440']::text[], '4178644429dd6c6f3eee6aa8b9b91f19', replace($b$تقدم طلبات الإحالة إلى المعاش كتابة إلى النقابة حتى آخر شهر أكتوبر من كل سنة، وعلى لجنة الصندوق وترتيب المعاش للطالب متى توافرت فيه الشروط المنصوص عليها فى هذا القانون وذلك فى آخر شهر ديسمبر.
وعلى الطالب تصفية أعمال مكتبه خلال ثلاثة أشهر تبدأ من يوم قبول الطلب.
ويبدأ صرف المعاش فى أول الشهر التالى لأخطار لجنة الصندوق بتصفية أعماله فعلا.$b$, E'\n', E'\r\n')),
    (208, 0, ARRAY['edd868d6b5ad0a5e8d51d284278d74c3']::text[], ARRAY['e894ced645460a0d266c1f370c3d5628']::text[], 'b47e05524c997573eba193912d15622a', replace($b$يترتب على صرف معاش التقاعد ألا يباشر المحامى أى عمل من أعمال المحاماة أيا كان نوعه ويرفع اسم المحامى نهائيا من جدول المحامين المشتغلين ولا يجوز للمحامى بعد أن يحصل على معاش التقاعد أن يطلب قيد اسمه فى جدول المشتغلين.$b$, E'\n', E'\r\n')),
    (209, 0, ARRAY['cdabe7413acee335d10fe220385938b2']::text[], ARRAY['1bf5db6c51fcd25d62b601fcbe1e96ff']::text[], 'dc8968076b4aa15caed2c1d9e2859fdb', replace($b$لا يجوز استبدال المعاشات المقررة وفقا لهذا القانون.$b$, E'\n', E'\r\n')),
    (210, 0, ARRAY['1f7e0eefe69118f371c37330fcee9277']::text[], ARRAY['69cfff00ee798725123b25d9a660d2ca']::text[], 'a90ab377960084fdfea39bc5ea114644', replace($b$تسرى الأحكام الخاصة بالمستحقين المنصوص عليها فى هذا القانون على المستحقين عن المحامين المعاملين بالقانون رقم (101) لسنة 1944 بشأن المحاماة أمام المحاكم الشرعية، المشتغلين وقت صدور هذا القانون وذلك عند استحقاق المعاش.$b$, E'\n', E'\r\n')),
    (211, 0, ARRAY['4a979f8d7ca35052b87bbdc5cdc0fb3f']::text[], ARRAY['c1cd1970ce4ad159d3e3d3717ed38055']::text[], 'a065388090f3a2737d95aae83e99f271', replace($b$تزاد المعاشات الأصلية المقررة طبقا لأحكام القوانين السابقة بما فى ذلك معاشات المحامين المعاملين بالقانون رقم (101) لسنة 1944 طبقا للاتى:
(1) خمسون فى المائة من المعاش الذى لم يكن يجاوز أربعين جنيها.
(2) أربعون فى المائة من المعاش الذى لم يكن يجاوز خمسين جنيها.
(3) ثلاثون فى المائة من المعاش الذى لم يكن يجاوز ستين جنيها.
(4) عشرون فى المائة من المعاش فى الحالات الأخرى.
ويكون الحد الأدنى لنصيب المستحقين عن صاحب المعاش خمسة وثلاثين جنيها فى الشهر بالنسبة للأرملة وخمسة جنيهات بالنسبة لكل من باقى المستحقين ويسرى ما تقدم على المعاشات والأنصبة المستحقة ابتداء من الشهر التالى لتاريخ العمل بأحكام هذا القانون.$b$, E'\n', E'\r\n')),
    (212, 0, ARRAY['b20a0ac9b4206a5d8c9887af481914e2']::text[], ARRAY['1ccc77e6292d0e58c287dcd6b8019dc5']::text[], 'a3d487f7ea7a4879f2f9a650ab6099e5', replace($b$يجوز لمجلس النقابة أن يعقد تأمينا لدى إحدى شركات التأمين لتغطية التزامات الصندوق عن معاشات التقاعد ومخاطر الوفاة الموجبة لاستحقاقها.$b$, E'\n', E'\r\n')),
    (213, 0, ARRAY['4cbf78b4934e2ca9ed44cc9a79f687ca']::text[], ARRAY['ea7c0090ea204df4f6cc9e690fee7653']::text[], '42dab07c14e39e2acc9fba22ae46e81a', replace($b$إذا طرأ على المحامى ما يقتضى معاونته ماليا جاز للجنة الصندوق أن تقرر له معونة وقتية لمواجهة حالته أو معونة شهرية ثابتة لمدة لا تجاوز سنة.
وللجنة أن تقرر معونة للمستحقين عن المتوفى طبقا لأحكام هذا القانون إذا لم تتوافر له شروط الحصول على معاش التقاعد.
وفى جميع الأحوال لا يجوز أن يزيد مجموع ما يحصل عليه المحامى أو المستحقون عنه من معونات عن الحد الأقصى لمعاش سنة واحدة.$b$, E'\n', E'\r\n')),
    (214, 0, ARRAY['7b5a83db68582b43a5812614563d7151']::text[], ARRAY['745786e38a16ed9548db8486133081ff']::text[], 'ba6f339f3a16cdcc455532805921d5b6', replace($b$يكفل الصندوق، الرعاية الصحية للمحامين المقيدين بالجدول العام وأسرهم طبقا للقواعد الموحدة التى تقررها اللائحة التنفيذية للرعاية الاجتماعية والصحية على أن يتم توفير الرعاية الصحية على مستوى النقابات الفرعية وطبقا للاعتمادات السنوية التى تخصص لكل منها فى الموازنة التقديرية.
ويجوز أن يكون ذلك عن طريق إنشاء نظام للتأمين الصحى.$b$, E'\n', E'\r\n')),
    (215, 0, ARRAY['715f110f3a4f021410a111fbdf6bf67f']::text[], ARRAY['378efde9f2cee91a128633e67ff72766']::text[], '46fa06f56d56e3676dde53111cbc3676', replace($b$تضع اللائحة التنفيذية للرعاية الاجتماعية والصحية نظاما لتقديم قروض للمبتدئ لمعاونته على اتخاذ مكتب له أو تكوين مكتبه قانونية خاصة به بعد انتهاء فترة تمرينه وقبوله بجدول المحاكم الابتدائية والإدارية على ألا يقبل قيد المحامى أمام محاكم الاستئناف إلا بعد سداد هذه القروض.$b$, E'\n', E'\r\n')),
    (216, 0, ARRAY['a3c49e6cd874a48c34088e304b382dbb']::text[], ARRAY['3e802ac52c5ac66954368d3ae77c679e']::text[], 'e92ebe02473ae540e86780a17ab84d1b', replace($b$ملغاة$b$, E'\n', E'\r\n')),
    (217, 0, ARRAY['7467ff8551b567204561202c71848be0']::text[], ARRAY['fbaa15cbaf7d22fcea84c7512523c986']::text[], '59ecee1dfbaa1d48c83c683166188e58', replace($b$يختص مجلس النقابة وحده بالفصل فى تظلمات ذوى الشأن من قرارات لجنة الصندوق، كما تختص مجلس النقابات الفرعية فى الفصل فى تظلمات ذوى الشأن من قرارات لجانه الفرعية.$b$, E'\n', E'\r\n')),
    (218, 0, ARRAY['dfc8883fd78a7404c4969daeb04bc0d3']::text[], ARRAY['c74f58adde22bec68f9fa007fd011008']::text[], '221fc6e28908c67317be3186d4fc72c3', replace($b$مع عدم الإخلال بأحكام قانون المرافعات تعتبر المعاشات والمعونات التى تقرر طبقا لأحكام هذا القانون نفقة لا يجوز تحويلها أو الحجز عليها أو التنازل عنها للغير.$b$, E'\n', E'\r\n')),
    (219, 0, ARRAY['ed2b4c63a9442a809d3ab40686717846']::text[], ARRAY['0fdff2bb023549de29bc23ca46c506d6']::text[], 'aa2cc1645f05da3d5c256b1cd58ea6b9', replace($b$يضع مجلس النقابة، بناء على اقتراح لجنة الصندوق اللائحة التنفيذية للرعاية الاجتماعية والصحية مبينا بها إجراءات تقديم الطلبات والفصل فيها وما يقدم من مستندات مؤيدة لها وتحديد اختصاصات كل من النقابة العامة والنقابات الفرعية بشأنها.$b$, E'\n', E'\r\n')),
    (220, 0, ARRAY['e015412dcc2f991de4acdf6329aa9224']::text[], ARRAY['5a730b648e3bdb355ff4ba06194d80c3']::text[], '9eff2f6027ac490be9a761951e3dd49d', replace($b$يكون للنقابة أمانة عامة تتولى الشئون الإدارية والمالية والتنفيذية المتعلقة بالنقابة وتخضع للإشراف المباشر لأمين عام النقابة والإشراف الأعلى للنقيب.$b$, E'\n', E'\r\n')),
    (221, 0, ARRAY['e165c9c0fc59bb299a3e6077c5eabb5b']::text[], ARRAY['0c3500237e73290d9c9ff7f10076ecff']::text[], '060172190b37810453764b1efcb6e081', replace($b$يعين مجلس النقابة العامة مديرا عاما للنقابة من بين المحامين أو غيرهم لإدارة شئون وأعمال النقابة الإدارية والمالية والإشراف على العاملين بها ويكون مسئولا عن إدارة شئون النقابة أمام الأمين العام الذى يكون له عليه حق التنبيه والإنذار بسيط وفيما عدا ذلك لا يحاسب تأديبا إلا أمام مجلس النقابة.$b$, E'\n', E'\r\n')),
    (222, 0, ARRAY['a5b40f1006cde9e0fedef8d7289c70fa']::text[], ARRAY['656489ee92110e543daeaf1c8aaa51e3']::text[], '78e057a0c724a868b90d7854a1c1a411', replace($b$يضع مجلس النقابة العامة بناء على اقتراح الأمين العام لائحة تنظيم شئون العاملين بها وكيفية تعيينهم وتحدد مرتباتهم وعلاواتهم ومعاملتهم وتوزيعهم على النقابة العامة والنقابات الفرعية.$b$, E'\n', E'\r\n')),
    (223, 0, ARRAY['52b2b7117b8245ab79a9ff279c922066']::text[], ARRAY['5857629dc5a72a3f05952ab603a82096']::text[], 'd20aa44b139039ca80304870f7e18656', replace($b$لا تسرى أحكام القوانين الخاصة بالاجتماعات العامة على اجتماعات أعضاء النقابة للبحث فيما لا يخرج عن أهداف النقابة المحددة بهذا القانون.$b$, E'\n', E'\r\n')),
    (224, 0, ARRAY['2d63bc99b64e4e0b481e77629b743bfc']::text[], ARRAY['a622f68a13bee0b84fe8d90b14bc8c43']::text[], '8d011960b9e24d10bea97ee5d82a8b0c', replace($b$لا يجوز تفتيش مقار نقابة المحامين ونقاباتها الفرعية ولجانها الفرعية أو وضع أختام عليها إلا بمعرفة أحد أعضاء النيابة العامة وبحضور نقيب المحامين أو نقيب النقابة الفرعية أو من يمثلها.$b$, E'\n', E'\r\n')),
    (225, 0, ARRAY['a60985e19f87fb5d6004a63f27936675']::text[], ARRAY['ee01fb0687a430e1ae1a34d1be35de3f']::text[], '30d578ab5ad6686ae2804d9b5188c0ba', replace($b$تنشر القرارات ذات الطابع العام التى تصدرها الجمعية العمومية ومجلس النقابة العامة والجمعيات العمومية للنقابات الفرعية ومجالسها بمجلة المحاماة وفق ما يقرره مجلس النقابة العامة.$b$, E'\n', E'\r\n')),
    (226, 0, ARRAY['eedec07a915e384fab04667ec1261a8e']::text[], ARRAY['940ab5b49da68e19888018d400c069a9']::text[], 'd3560ef6c54b9ac8d979a31da7a6d6f6', replace($b$كل تنبيه أو إخطار يجب أن يكون بمقتضى خطاب موصى عليه بعلم الوصول ما لم يرد فى القانون نص على خلاف ذلك.$b$, E'\n', E'\r\n')),
    (227, 0, ARRAY['0f75ce6e664610ce82581dc7a2aeb0df']::text[], ARRAY['ce0d99801a87e0d59bea414670d57977']::text[], '9e6d0c601295c0cea38d333883ca4dd1', replace($b$مع عدم الإخلال بأية عقوبات أشد ينص عليها قانون العقوبات أو أى قانون آخر يعاقب بالحبس لمدة لا تقل عن سنة وبغرامة لا تقل عن ألفى جنيه ولا تتجاوز خمسة آلاف جنيه كل من انتحل صفة محام على خلاف أحكام هذا القانون.
وتكون العقوبة الحبس لمدة شهر وغرامة لا تقل عن ألف جنيه ولا تزيد على ألفى جنيه لكل من زاول عملا من إعمال المحاماة ولم يكن من المحامين المقيدين بجدول المحامين المشتغلين أو كان ممنوعا من مزاولة المهنة.
وتؤول حصيلة الغرامة المحكوم بها إلى صندوق الرعاية الاجتماعية والصحية.$b$, E'\n', E'\r\n')),
    (228, 0, ARRAY['047f9d054e9b92d38b2008df99a68292']::text[], ARRAY['3b221318a35ee43b73c64d9380cc50b5']::text[], '7e7618426f26de3b224b6eeb37c8568c', replace($b$يجب على المحامين المقيدين بجدول المحامين المشتغلين عدم التخلف عن تأدية الانتخاب والا وجبت على المتخلف غرامة قدرها عشرون جنيها تحصلها النقابة عند سداد الاشتراك لصالح صندوق الرعاية الاجتماعية والصحية ولا يجوز الإعفاء منها إلا لعذر يقبله مجلس النقابة العامة وبشرط الإخطار به سلفا ما لم يثبت أنه كان طارئا.$b$, E'\n', E'\r\n')),
    (229, 0, ARRAY['40db3cb0b81753f3641c8082077c4a53']::text[], ARRAY['529c49a8616ceb760cbce9004a16c161']::text[], 'a3c9dab7854f64f770ee38b81dbd974b', replace($b$تسرى الأحكام المقررة فى المادة (331) من قانون الإجراءات الجنائية على مخالفة أحكام المواد 49، 50، 51 من هذا القانون.$b$, E'\n', E'\r\n')),
    (230, 0, ARRAY['d96b130c0dec95a769f932d6bda4f449']::text[], ARRAY['996389a2791b7421244a49fce9b3e047']::text[], '53f16a5d62686be889ab47f3b7d944ba', replace($b$تنشأ أكاديمية تسمى " أكاديمية المحاماة والدراسات القانونية "، تتبع نقابة المحامين، وتكون لها شخصية اعتبارية وتتمتع بالاستقلال الفنى والإدارى والمالى، وتتولى تطوير الدراسات المتعلقة بمهنة المحاماة، وتدريب المحامين والارتقاء بمهاراتهم ومنحهم شهادات مهنية.
ومع عدم الإخلال بحكم المادة (13) من هذا القانون، لا يجوز القيد بالجدول العام لأول مرة إلا بعد اجتياز الدراسة بهذه الأكاديمية وحصول طالب القيد على شهادة إتمام الدراسة بها، على أن تبدأ الدراسة اعتبارًا من يناير 2021.$b$, E'\n', E'\r\n')),
    (231, 0, ARRAY['f710adc2df39f892d4d80a42d2f877be']::text[], ARRAY['c249e3805083e5426f4e5c5e1df95c2a']::text[], '2b2fb110b484bd7a3fbbc46ed46c13d5', replace($b$يكون للأكاديمية مجلس إدارة يتولى إدارة أعمالها لمدة أربع سنوات، برئاسة نقيب المحامين وعضوية أثنى عشر عضوًا يختارهم مجلس النقابة العامة، ويجوز أن يعين فى مجلس الإدارة أربعة أعضاء على الأكثر من أعضاء مجلس النقابة العامة.
ويضع مجلس النقابة العامة جميع اللوائح الإدارية والمالية والفنية المنظمة للأكاديمية، ويحدد هيكلها الفنى والإدارى وضوابط القبول والدراسة ومدتها ومناهجها واستصدار المعادلات للمؤهلات المهنية الصادرة عنها.$b$, E'\n', E'\r\n'))
  ) AS t(art_no, suf, old_md5s, old_skels, new_md5, new_body) ORDER BY art_no, suf
  LOOP
    IF md5(r.new_body) <> r.new_md5 THEN
      RAISE EXCEPTION '[215] نص المادة %/% المحمَّل لا يطابق md5 المختبَر', r.art_no, r.suf;
    END IF;
    v_aid := NULL; v_cur := NULL;
    SELECT a.id, a.body INTO v_aid, v_cur FROM articles a
     WHERE a.law_id = v_law AND a.article_no = r.art_no AND a.article_suffix_order = r.suf;
    IF v_aid IS NULL THEN
      RAISE WARNING '[215] المادة %/% غير موجودة — تخطّى', r.art_no, r.suf;
      v_skip := v_skip + 1; CONTINUE;
    END IF;
    IF md5(v_cur) = r.new_md5 THEN
      v_done := v_done + 1; CONTINUE;
    END IF;
    IF NOT (md5(v_cur) = ANY (r.old_md5s)
            OR md5(regexp_replace(v_cur, '[^ء-ي0-9]|[اأإآلهـ]', '', 'g')) = ANY (r.old_skels)) THEN
      RAISE WARNING '[215] نص المادة %/% الحالى يختلف عن المتوقع (md5 %) — تُخطّيت دون تعديل، راجعها يدوياً', r.art_no, r.suf, md5(v_cur);
      v_skip := v_skip + 1; CONTINUE;
    END IF;

    INSERT INTO migration_215_backup (article_id, version_id, old_body)
      SELECT a.id, NULL, a.body FROM articles a WHERE a.id = v_aid ON CONFLICT DO NOTHING;
    INSERT INTO migration_215_backup (article_id, version_id, old_body)
      SELECT v.article_id, v.id, v.body FROM article_versions v
       WHERE v.article_id = v_aid AND v.body = v_cur ON CONFLICT DO NOTHING;

    UPDATE article_versions SET body = r.new_body WHERE article_id = v_aid AND body = v_cur;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_ok_ver := v_ok_ver + v_n;
    UPDATE articles SET body = r.new_body WHERE id = v_aid AND body = v_cur;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 1 THEN
      RAISE EXCEPTION '[215] عدد المواد المعدلة % بدل 1 (المادة %/%)', v_n, r.art_no, r.suf;
    END IF;
    IF (SELECT md5(body) FROM articles WHERE id = v_aid) <> r.new_md5 THEN
      RAISE EXCEPTION '[215] نص المادة %/% بعد التعديل لا يطابق المختبَر', r.art_no, r.suf;
    END IF;
    v_ok_art := v_ok_art + 1;
  END LOOP;

  -- 2) المواد المكررة السبع: تُنشأ إن لم تكن موجودة
  FOR r IN SELECT * FROM (VALUES
    (13, 1, '2019-08-07', 147, 2019, 'أُضيفت المادة بموجب القانون رقم 147 لسنة 2019 (المنشور بالجريدة الرسمية العدد 31 مكرر (و) فى 7 أغسطس 2019).', '33fdde9108305f02e2033464e42030b1', replace($b$لا يجوز القيد فى نقابة المحامين إلا بعد الحصول على الشهادة المنصوص عليها بالمادة (230) من هذا القانون، واجتياز اختبار تحريرى تضعه على مستوى قومى لجنة يشكلها مجلس النقابة العامة لهذا الغرض، على أن تضم فى عضويتها عناصر لها الخبرة الكافية، ويجب أن يشترك فى وضع الاختبار كبار رجال المحاماة والقضاة وأساتذة القانون، على أن يتم إجراؤه خارج مقر النقابة مرتين سنويًا، بما يكفل تحقيق العدالة وتكافؤ الفرص، وذلك كله وفقا للقواعد التى يضعها مجلس النقابة العامة. ويبدأ تطبيق هذا الاختبار اعتبارًا من يناير عام 2021.
ويعفى من أداء الاختبار المنصوص عليه فى الفقرة الأولى من هذه المادة كل من شغل وظيفة أستاذ فى القانون بإحدى الجامعات المصرية، أو درجة مستشار بإحدى الجهات أو الهيئات القضائية، أو رتبة عقيد فى القضاء العسكرى أو فى جهاز الشرطة.$b$, E'\n', E'\r\n')),
    (46, 1, '2008-06-23', 197, 2008, 'أُضيفت المادة بموجب القانون رقم 197 لسنة 2008 (المنشور بالجريدة الرسمية العدد 25 مكرر (د) فى 23 يونيو 2008).', 'fd94ab2231b7c80809d5ba344fc1afbe', replace($b$ويصدر مجلس النقابة العامة ترخيصا بالمزاولة يتضمن أسم المحامى ودرجة قيده، ويحدد فيه مدة سريانه.
ومع عدم الإخلال بأحكام المادة 227 من هذا القانون لا يجوز افتتاح مكتب لمزاولة المحاماة أو أى عمل من الأعمال الوارد بيانها فى المادة الثالثة من قانون المحاماة إلا بعد الحصول على هذا الترخيص،
وإلا جاز إغلاقه بقرار من قاضى الأمور الوقتية بالمحكمة الابتدائية التابع لها المكتب المخالف، بناء على طلب النقابة العامة أو النقابة الفرعية المختصة.$b$, E'\n', E'\r\n')),
    (50, 1, '2019-08-07', 147, 2019, 'أُضيفت المادة بموجب القانون رقم 147 لسنة 2019 (المنشور بالجريدة الرسمية العدد 31 مكرر (و) فى 7 أغسطس 2019).', '7819bcddcde047b3b1726fc13fd71397', replace($b$يتمتع المحامى بالضمانات المقررة فى القانون إذا وقعت الأفعال المشار إليها فى المادتين (49، 50) من هذا القانون أمام جهات الاستدلال أو التحقيق، وفى جميع الأحوال، تحرر مذكرة بالوقائع ترفع إلى المحامى العام الأول لنيابة الاستئناف المختصة للتصرف.$b$, E'\n', E'\r\n')),
    (135, 1, '2019-08-07', 147, 2019, 'عُدِّلت المادة بموجب القانون رقم 147 لسنة 2019 (المنشور بالجريدة الرسمية العدد 31 مكرر (و) فى 7 أغسطس 2019).', '9c1f936b228adcef1ccc25fc4e16e0d7', replace($b$يجوز لخمسين محاميا على الأقل ممن حضروا الجمعية العمومية أو شاركوا فى انتخاب مجلس النقابة الطعن فى القرارات الصادرة منها وفى تشكيل مجلس النقابة، وذلك بتقرير موقع عليه منهم يقدم إلى قلم كتاب محكمة النقض خلال أسبوعين من تاريخ القرار بشرط التصديق على امضاءاتهم.
ويجب أن يكون الطعن مسببا وتفصل المحكمة فى الطعن على وجه الاستعجال بعد سماع أقوال النيابة وأقوال النقيب أو من ينوب عنه وكيل الطاعنين.
فإذا قضى ببطلان تشكيل الجمعية العمومية، بطلت قراراتها، وإذا قضى ببطلان انتخاب النقيب أو أكثر من ثلاثة من أعضاء المجلس أجريت انتخابات جديدة لانتخاب من يحل محلهم.
وفى الأحوال التى يقضى بها ببطلان الانتخابات، يتم تشكيل لجنة برئاسة رئيس محكمة استئناف القاهرة، وعضوية ثلاثة من قضاتها، وثلاثة محامين من آخر مجلس للنقابة منتخب انتخابا صحيحا، يتم اختيارهم من رئيس محكمة استئناف القاهرة لإجراء العملية الانتخابية والإشراف على صناديق الاقتراع وإعلان النتيجة خلال ستين يوما.$b$, E'\n', E'\r\n')),
    (156, 1, '2019-08-07', 147, 2019, 'استُبدلت المادة بموجب القانون رقم 147 لسنة 2019 (المنشور بالجريدة الرسمية العدد 31 مكرر (و) فى 7 أغسطس 2019).', '2501bbcd67dce9d5d936325e64301181', replace($b$مع عدم الإخلال بالحق فى التقاضى، يختص مجلس النقابة العامة بالنظر فى التظلمات من تشكيل الجمعيات العمومية أو مجالس النقابات الفرعية بطلب يقدم إليه خلال أسبوعين من تاريخ إبلاغه بالتشكيل بالقرارات من عشر أعضاء الجمعية العمومية للنقابة الفرعية على الأقل الذين حضروا اجتماعها.
كما يختص مجلس النقابة العامة بالفصل فى التظلمات فى القرارات الصادرة من مجالس النقابات الفرعية خلال الثلاثين يوما التالية لإبلاغها إليه.$b$, E'\n', E'\r\n')),
    (156, 2, '2008-06-23', 197, 2008, 'أُضيفت المادة (156 مكرر (1)) بموجب القانون رقم 197 لسنة 2008 (المنشور بالجريدة الرسمية العدد 25 مكرر (د) فى 23 يونيو 2008).', 'aed01505cdcc581a2642f21e3dd9a5fa', replace($b$تنشأ لجان نقابية فى دائرة كل محكمة جزئية وتعمل على تحقيق أهداف النقابة الفرعية فى حدود اختصاصها.
ويضع مجلس النقابة العامة قواعد إنشاء اللجنة واختصاصها، ويجوز لمجلس النقابة العامة، بعد استطلاع رأى النقابة الفرعية المختصة دمج أكثر من لجنة نقابية.$b$, E'\n', E'\r\n')),
    (206, 1, '1984-10-18', 227, 1984, 'أُضيفت المادة بموجب القانون رقم 227 لسنة 1984 (المنشور بالجريدة الرسمية العدد 42 فى 18 أكتوبر 1984).', 'b70ccfcde97b27784ba93d790cecd5b8', replace($b$يستمر صرف معاشات المحامين الشرعيين المعاملين بالمادة (96) من القانون رقم (101) لسنة 1994، والذين أحيلوا إلى المعاش أو توفوا قبل صدور القانون رقم (61) لسنة 1968 أو وراثتهم.$b$, E'\n', E'\r\n'))
  ) AS t(art_no, suf, eff_from, by_no, by_year, note, new_md5, new_body)
  LOOP
    IF md5(r.new_body) <> r.new_md5 THEN
      RAISE EXCEPTION '[215] نص المادة المكررة %/% المحمَّل لا يطابق md5 المختبَر', r.art_no, r.suf;
    END IF;
    IF EXISTS (SELECT 1 FROM articles a WHERE a.law_id = v_law AND a.article_no = r.art_no AND a.article_suffix_order = r.suf) THEN
      CONTINUE;
    END IF;
    INSERT INTO articles (law_id, article_no, article_suffix_order, body)
      VALUES (v_law, r.art_no, r.suf, r.new_body) RETURNING id INTO v_aid;
    INSERT INTO article_versions (article_id, version_no, body, effective_from, status, amended_by_law_no, amended_by_law_year, change_note)
      VALUES (v_aid, 1, r.new_body, r.eff_from::date, 'active', r.by_no, r.by_year, r.note);
    v_new := v_new + 1;
  END LOOP;

  -- 3) المواد 2 و3 و5 كانت مُصنَّفة ملغاة خطأً (خلط مع مواد الإصدار) — تُفعَّل بعد تحديث نصها
  INSERT INTO migration_215_meta_backup (kind, ref_id, old_status, old_note)
    SELECT 'status', v.id, v.status, v.change_note FROM article_versions v JOIN articles a ON a.id = v.article_id
     WHERE a.law_id = v_law AND a.article_suffix_order = 0 AND a.article_no IN (2, 3, 5)
       AND v.status = 'repealed' AND a.body NOT LIKE 'ملغاة%' AND v.change_note LIKE '%327 لسنة 1984%'
    ON CONFLICT DO NOTHING;
  UPDATE article_versions v SET status = 'active', change_note = NULL FROM articles a
   WHERE a.id = v.article_id AND a.law_id = v_law AND a.article_suffix_order = 0 AND a.article_no IN (2, 3, 5)
     AND v.status = 'repealed' AND a.body NOT LIKE 'ملغاة%' AND v.change_note LIKE '%327 لسنة 1984%';

  -- 4) المادة 216: رقم القانون الملغى الصحيح 227 لسنة 1984
  INSERT INTO migration_215_meta_backup (kind, ref_id, old_status, old_note)
    SELECT 'note216', v.id, v.status, v.change_note FROM article_versions v JOIN articles a ON a.id = v.article_id
     WHERE a.law_id = v_law AND a.article_suffix_order = 0 AND a.article_no = 216 AND v.change_note LIKE '%327 لسنة 1984%'
    ON CONFLICT DO NOTHING;
  UPDATE article_versions v SET change_note = replace(v.change_note, '327 لسنة 1984', '227 لسنة 1984') FROM articles a
   WHERE a.id = v.article_id AND a.law_id = v_law AND a.article_suffix_order = 0 AND a.article_no = 216 AND v.change_note LIKE '%327 لسنة 1984%';

