    (231, 0, 'القسم الثاني — في نظام نقابة المحامين — الباب السابع — أكاديمية المحاماة والدراسات القانونية')
  ) AS t(art_no, suf, loc)
  LOOP
    INSERT INTO migration_215_meta_backup (kind, ref_id, old_loc)
      SELECT 'loc', a.id, a.hierarchical_location FROM articles a
       WHERE a.law_id = v_law AND a.article_no = r.art_no AND a.article_suffix_order = r.suf
         AND a.hierarchical_location IS DISTINCT FROM r.loc
      ON CONFLICT DO NOTHING;
    UPDATE articles a SET hierarchical_location = r.loc
     WHERE a.law_id = v_law AND a.article_no = r.art_no AND a.article_suffix_order = r.suf
       AND a.hierarchical_location IS DISTINCT FROM r.loc;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_loc := v_loc + v_n;
  END LOOP;

  IF (SELECT count(*) FROM articles WHERE law_id = v_law) <> 238 THEN
    RAISE EXCEPTION '[215] عدد مواد القانون % بدل 238', (SELECT count(*) FROM articles WHERE law_id = v_law);
  END IF;
  RAISE NOTICE '[215] قانون 17/1983: مواد معدَّلة % ، نسخ معدَّلة % ، مُصلَحة سابقاً % ، متخطّاة % ، مواد مكررة جديدة % ، مواقع محدَّثة %', v_ok_art, v_ok_ver, v_done, v_skip, v_new, v_loc;
END
